// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {CallContextChecker} from "solady/utils/CallContextChecker.sol";
import {CredentialManager} from "./CredentialManager.sol";
import {CredentialManagerStorage} from "./CredentialManagerStorage.sol";
import {IAutomataDcapAttestation} from "./interfaces/IAutomataDcapAttestation.sol";
import {ICredentialManagerFacet} from "./interfaces/ICredentialManagerFacet.sol";
import {IMeasurementProfileRegistry} from "./interfaces/IMeasurementProfileRegistry.sol";

/// @title AttestationFacet
/// @notice The CredentialManager's attestation packet verification: code the CredentialManager
///         delegatecalls, working on the CredentialManager's own storage.
contract AttestationFacet is ICredentialManagerFacet, CredentialManagerStorage, CallContextChecker {
    uint256 private constant _OUTPUT_HEADER_LENGTH = 11;
    uint256 private constant _TCB_STATUS_INDEX = 4;
    uint256 private constant _REPORT_BODY_LENGTH = 584;
    uint256 private constant _MRTD_OFFSET = 136;
    uint256 private constant _RTMR0_OFFSET = 328;
    uint256 private constant _RTMR1_OFFSET = 376;
    uint256 private constant _RTMR2_OFFSET = 424;
    uint256 private constant _RTMR3_OFFSET = 472;
    uint256 private constant _REPORT_KEY_OFFSET = 520;
    uint256 private constant _REPORT_OPERATOR_OFFSET = 540;
    uint256 private constant _REPORT_DATA_LENGTH = 40;
    uint8 private constant _TCB_STATUS_UP_TO_DATE = 0;

    /// @notice Verifies an operator's attestation packet for the CredentialManager, records its
    ///         sequence, and returns the operator and the key it attests.
    /// @dev With no verifier set, `rawQuote` is the report data itself, at least 40 bytes.
    /// @param rawQuote The clearing engine's DCAP quote, or its report data with no verifier.
    /// @param tcbEvaluationDataNumber Intel TCB evaluation number passed to the verifier.
    /// @param sequence The packet's sequence, above the operator's last accepted one.
    /// @param operatorSignature The operator's 65-byte low-s ECDSA signature over
    ///        `attestationPacketDigest(rawQuote, sequence)`.
    /// @return operator The attesting operator.
    /// @return key The attested key, held by no other operator.
    function acceptAttestation(
        bytes calldata rawQuote,
        uint32 tcbEvaluationDataNumber,
        uint256 sequence,
        bytes calldata operatorSignature
    ) external onlyProxy returns (address operator, address key) {
        (key, operator) = _readReportData(rawQuote, tcbEvaluationDataNumber);
        if (
            _recoverSigner(_attestationPacketDigest(rawQuote, sequence), operatorSignature)
                != operator
        ) {
            revert CredentialManager.InvalidOperatorSignature();
        }
        if (!isOperator[operator]) revert CredentialManager.NotOperator(operator);
        uint256 lastSequence = lastAttestationSequence[operator];
        if (sequence <= lastSequence) {
            revert CredentialManager.StaleSequence(sequence, lastSequence);
        }
        lastAttestationSequence[operator] = sequence;
        _requireKeyAvailable(operator, key);
    }

    function _readReportData(bytes calldata rawQuote, uint32 tcbEvaluationDataNumber)
        private
        returns (address key, address operator)
    {
        IAutomataDcapAttestation verifier = automataVerifier;
        if (address(verifier) == address(0)) {
            if (rawQuote.length < _REPORT_DATA_LENGTH) {
                revert CredentialManager.InvalidQuoteLength();
            }
            return (address(bytes20(rawQuote[0:20])), address(bytes20(rawQuote[20:40])));
        }
        IMeasurementProfileRegistry registry = measurementProfileRegistry;
        if (address(registry) == address(0)) revert CredentialManager.ProfileRegistryUnset();

        (bool success, bytes memory output) =
            verifier.verifyAndAttestOnChain(rawQuote, tcbEvaluationDataNumber);
        if (!success) revert CredentialManager.QuoteRejected(output);
        if (output.length < _OUTPUT_HEADER_LENGTH + _REPORT_BODY_LENGTH) {
            revert CredentialManager.InvalidQuoteLength();
        }
        uint8 tcbStatus = uint8(output[_TCB_STATUS_INDEX]);
        if (tcbStatus != _TCB_STATUS_UP_TO_DATE) {
            revert CredentialManager.InvalidTcbStatus(tcbStatus);
        }

        bytes32[5] memory quoteMeasurements;
        assembly ("memory-safe") {
            let body := add(add(output, 0x20), _OUTPUT_HEADER_LENGTH)
            mstore(quoteMeasurements, mload(add(body, _MRTD_OFFSET)))
            mstore(add(quoteMeasurements, 0x20), mload(add(body, _RTMR0_OFFSET)))
            mstore(add(quoteMeasurements, 0x40), mload(add(body, _RTMR1_OFFSET)))
            mstore(add(quoteMeasurements, 0x60), mload(add(body, _RTMR2_OFFSET)))
            mstore(add(quoteMeasurements, 0x80), mload(add(body, _RTMR3_OFFSET)))
            key := shr(96, mload(add(body, _REPORT_KEY_OFFSET)))
            operator := shr(96, mload(add(body, _REPORT_OPERATOR_OFFSET)))
        }

        bytes32[5] memory profileMeasurements;
        (
            profileMeasurements[0],
            profileMeasurements[1],
            profileMeasurements[2],
            profileMeasurements[3],
            profileMeasurements[4]
        ) = registry.clearingEngineProfile();
        if (profileMeasurements[0] == bytes32(0)) {
            revert CredentialManager.NoClearingEngineProfile();
        }
        for (uint256 register; register < 5; ++register) {
            bytes32 profileValue = profileMeasurements[register];
            if (profileValue != bytes32(0) && quoteMeasurements[register] != profileValue) {
                revert CredentialManager.MeasurementMismatch(register);
            }
        }
    }
}

