// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {EfficientHashLib} from "solady/utils/EfficientHashLib.sol";
import {SignatureCheckerLib} from "solady/utils/SignatureCheckerLib.sol";
import {TPlusUUPSUpgradeable} from "./utils/TPlusUUPSUpgradeable.sol";

/**
 * @title Checkpointer
 * @notice Tracks and validates state root checkpoints using EIP-712 signatures from admin and leader nodes.
 * @dev Designed for use in DStack-like distributed settlement systems.
 */
contract Checkpointer is TPlusUUPSUpgradeable {
    /**
     * @notice Address with the authority to set initial parameters.
     * @dev Should be set to the DStack app shared secret public key.
     */
    address public admin;

    /**
     * @notice Public key of the current designated leader node.
     * @dev Leader is responsible for signing and submitting new checkpoints.
     */
    address public leader;

    /**
     * @notice Gnosis Safe address used as the council multisig.
     * @dev Can rotate the leader and self.
     */
    address public councilMultisig;

    /**
     * @notice Monotonically increasing nonce for checkpoint submissions.
     * @dev Used to prevent replay attacks and enforce checkpoint ordering.
     */
    uint256 public stateRootNonce;

    /// @notice Typehash used for EIP-712 encoding of the Checkpoint struct.
    bytes32 public constant CHECKPOINT_TYPEHASH =
        keccak256("Checkpoint(uint256 nonce,uint8[] stateRoot,string[] approvedWithdrawals)");

    /**
     * @notice Emitted when a new list of approved withdrawals is recorded in a checkpoint.
     * @param approvedWithdrawals List of withdrawal IDs approved in the checkpoint.
     */
    event Withdrawals(string[] approvedWithdrawals);

    /// @notice Cached domain separator for EIP-712 signature verification.
    bytes32 internal _domainSeparator;

    /**
     * @notice The current state root, encoded as a serialized vector.
     * @dev Serialized as `(user, eth_balance, usdc_balance, deposit_nonce, is_mm)` tuples.
     *      In production, this may store multiple roots and rotate.
     */
    uint8[] public stateRoot;

    /// @notice Reverts if caller is not the admin.
    error NotAdmin();

    /// @notice Reverts if a value has already been set.
    error AlreadySet();

    /// @notice Reverts if caller is not the current council multisig.
    error NotCouncilMultisig();

    /// @notice Reverts if a signature does not match the expected signer or payload.
    error InvalidSignature();

    constructor() {
        _initialize(msg.sender);
    }

    /**
     * @notice Initializes contract configuration for proxy deployments.
     */
    function initialize(address _admin, uint64 _upgradeDelaySeconds) external initializer {
        _initialize(_admin);
        _initializeUpgradeDelay(_upgradeDelaySeconds);
    }

    function _initialize(address _admin) internal {
        require(_admin != address(0));
        admin = _admin;
    }

    function _isUpgradeAuthority(address caller) internal view override returns (bool) {
        // Once configured, the council multisig becomes the sole upgrade authority.
        if (councilMultisig != address(0)) return caller == councilMultisig;
        return caller == admin;
    }

    /**
     * @notice Sets the EIP-712 domain separator used for verifying signatures.
     * @param domainSeparator The domain separator to store.
     */
    function setDomainSeparator(bytes32 domainSeparator) external {
        if (msg.sender != admin) revert NotAdmin();
        if (_domainSeparator != 0) revert AlreadySet();
        _domainSeparator = domainSeparator;
    }

    /**
     * @notice Transfers admin control to a new address.
     * @param newAdmin The new admin address.
     */
    function setAdmin(address newAdmin) external {
        if (msg.sender != admin) revert NotAdmin();
        require(newAdmin != address(0));
        admin = newAdmin;
    }

    /**
     * @notice Sets the initial council multisig address.
     * @param newCouncilMultisig The council's Gnosis Safe address.
     */
    function setInitialCouncilMultisig(address newCouncilMultisig) external {
        if (msg.sender != admin) revert NotAdmin();
        if (councilMultisig != address(0)) revert AlreadySet();
        councilMultisig = newCouncilMultisig;
    }

    /**
     * @notice Allows the current council to rotate itself to a new address.
     * @param newCouncilMultisig The new multisig address.
     */
    function setNewCouncilMultisig(address newCouncilMultisig) external {
        if (msg.sender != councilMultisig) revert NotCouncilMultisig();
        councilMultisig = newCouncilMultisig;
    }

    /**
     * @notice Sets the leader node address.
     * @dev This should be reviewed depending on the leader rotation mechanism.
     * @param newLeader The address of the new leader node.
     */
    function setLeader(address newLeader) external {
        if (msg.sender != councilMultisig) revert NotCouncilMultisig();
        leader = newLeader;
    }

    /**
     * @notice Checkpoint submitted by a node to update the system state.
     * @dev Requires valid EIP-712 signatures from both admin and leader.
     * @param sharedSignature Signature by the admin.
     * @param leaderSignature Signature by the leader.
     * @param _checkpoint The checkpoint payload to commit.
     */
    function checkpoint(
        bytes calldata sharedSignature,
        bytes calldata leaderSignature,
        Checkpoint calldata _checkpoint
    ) external {
        require(_checkpoint.nonce == stateRootNonce); // dev: Nonce mismatch

        // Compute the EIP-712 struct hash.
        bytes32 structHash = EfficientHashLib.hash(
            abi.encode(
                CHECKPOINT_TYPEHASH,
                _checkpoint.nonce,
                EfficientHashLib.hash(abi.encodePacked(_checkpoint.stateRoot)),
                hashStringArray(_checkpoint.approvedWithdrawals)
            )
        );

        // Check both admin and leader signatures.
        bytes32 digest =
            EfficientHashLib.hash(abi.encodePacked("\x19\x01", _domainSeparator, structHash));

        if (!SignatureCheckerLib.isValidSignatureNow(admin, digest, sharedSignature)) {
            revert InvalidSignature();
        }

        if (!SignatureCheckerLib.isValidSignatureNow(leader, digest, leaderSignature)) {
            revert InvalidSignature();
        }

        stateRootNonce++;
        stateRoot = _checkpoint.stateRoot;

        emit Withdrawals(_checkpoint.approvedWithdrawals);
    }

    /**
     * @notice Internal helper for hashing an array of strings.
     * @dev Each string is hashed individually and packed before final hashing.
     * @param arr The array of strings to hash.
     * @return A single keccak256 hash of the packed array of hashed strings.
     */
    function hashStringArray(string[] memory arr) internal pure returns (bytes32) {
        bytes32[] memory hashedStrings = new bytes32[](arr.length);
        for (uint256 i = 0; i < arr.length; i++) {
            hashedStrings[i] = EfficientHashLib.hash(bytes(arr[i]));
        }
        return EfficientHashLib.hash(abi.encodePacked(hashedStrings));
    }

    /**
     * @notice Struct defining a checkpoint message.
     * @dev Checkpoints include the current state root, a nonce, and a list of approved withdrawals.
     */
    struct Checkpoint {
        uint256 nonce;
        uint8[] stateRoot;
        string[] approvedWithdrawals;
    }
}

src/CredentialManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Initializable} from "solady/utils/Initializable.sol";
import {LibCall} from "solady/utils/LibCall.sol";
import {SafeCastLib} from "solady/utils/SafeCastLib.sol";
import {SafeTransferLib} from "solady/utils/SafeTransferLib.sol";
import {UUPSUpgradeable} from "solady/utils/UUPSUpgradeable.sol";
import {AttestationFacet} from "./AttestationFacet.sol";
import {CredentialManagerStorage} from "./CredentialManagerStorage.sol";
import {GovernanceCore} from "./governance/GovernanceCore.sol";
import {IAutomataDcapAttestation} from "./interfaces/IAutomataDcapAttestation.sol";
import {IMeasurementProfileRegistry} from "./interfaces/IMeasurementProfileRegistry.sol";
import {VaultFacet} from "./VaultFacet.sol";
import {
    CommitteeMember,
    GovernanceSnapshot,
    hashGovernanceSnapshot
} from "./types/GovernanceSnapshot.sol";

/// @title CredentialManager
/// @notice Root of trust for the TEE clearing engine: the operator committee, the security
///         council, the operators' attested signer keys and the deposit-vault registry.
/// @dev Every committee action is an operation on `GovernanceCore`. Each op type's portable ID
///      is `keccak256("CredentialManager.<NAME>")`, which callers pass everywhere. A portable op
///      type is signed and keyed under that ID, so one approval schedules on every manager in
///      the universe. A deployment-specific op type is signed and keyed under
///      `deploymentOpType(portableId)`, so its approvals schedule only on this manager. Each
///      constant's doc gives its scope, the `params` encoding and its key, where `opType` is the
///      deployment op type.
contract CredentialManager is Initializable, UUPSUpgradeable, CredentialManagerStorage {
    using GovernanceCore for GovernanceCore.State;

    uint256 private constant _OP_TYPE_COUNT = 17;

    /// @notice The facet holding the vault registry's and vault delivery's code, deployed with
    ///         this implementation.
    address public immutable vaultFacet;

    /// @notice The facet holding the attestation packet verification's code, deployed with this
    ///         implementation.
    address public immutable attestationFacet;

    /// @notice Whether this manager is the canonical manager or the manager of another L1.
    enum ManagerRole {
        /// @dev The canonical manager, which holds the system-wide vault list.
        Canonical,
        /// @dev The manager of another L1, governing the vaults on that L1 and its L2s.
        Local
    }

    /// @notice Whether this manager synchronizes a registered vault.
    enum VaultManagementMode {
        /// @dev This manager delivers governance snapshots to the vault.
        ManagedByThisManager,
        /// @dev Another L1's manager delivers to the vault; this one only lists it.
        ManagedByAnotherManager
    }

    /// @notice Ingestion settings for a vault's chain.
    struct ChainConfig {
        /// @dev Average block time in milliseconds.
        uint64 blockTimeMs;
        /// @dev Confirmations for events without a dedicated setting.
        uint8 defaultConfirmations;
        /// @dev Confirmations before a deposit is ingested.
        uint8 depositIngestConfirmations;
        /// @dev Confirmations before a withdrawal is ingested.
        uint8 withdrawalIngestConfirmations;
        /// @dev Confirmations before a settlement is ingested.
        uint8 settlementIngestConfirmations;
    }

    /// @notice The CredentialManager on another chain that is that chain's trust anchor.
    struct ChildManager {
        /// @dev Routing namespace of the child manager's chain.
        uint8 routingId;
        /// @dev Chain identifier within the routing namespace; the chain ID for EVM chains.
        uint64 vmId;
        /// @dev The child manager's address, left-aligned for EVM chains.
        bytes32 manager;
    }

    /// @notice A deposit vault on some chain.
    struct Vault {
        /// @dev Routing namespace of the vault's chain.
        uint8 routingId;
        /// @dev Chain identifier within the routing namespace; the chain ID for EVM chains.
        uint64 vmId;
        /// @dev The vault's address, left-aligned for EVM chains.
        bytes32 vaultAddress;
        /// @dev Ingestion settings for the vault's chain.
        ChainConfig config;
    }

    /// @notice An op type's initial lower and upper delay bounds.
    struct DelayPair {
        /// @dev Wait before a council-approved execute succeeds.
        uint64 lowerSeconds;
        /// @dev Wait before anyone can execute without council approval.
        uint64 upperSeconds;
    }

    /// @notice Initial delay bounds, one pair per op type. Immediate op types start at zero.
    struct InitialBounds {
        /// @dev Bounds of `OP_ADD_OPERATOR`.
        DelayPair addOperator;
        /// @dev Bounds of `OP_REMOVE_OPERATOR`.
        DelayPair removeOperator;
        /// @dev Bounds of `OP_SET_COMMITTEE_THRESHOLD`, an immediate op type.
        DelayPair setCommitteeThreshold;
        /// @dev Bounds of `OP_SET_SECURITY_COUNCIL`, an immediate op type.
        DelayPair setSecurityCouncil;
        /// @dev Bounds of `OP_SET_WITHDRAWAL_QUORUM`, an immediate op type.
        DelayPair setWithdrawalQuorum;
        /// @dev Bounds of `OP_KEY_ROTATION`, an immediate op type.
        DelayPair keyRotation;
        /// @dev Bounds of `OP_ROTATE_OPERATOR`.
        DelayPair rotateOperator;
        /// @dev Bounds of `OP_SET_AUTOMATA_VERIFIER`.
        DelayPair setAutomataVerifier;
        /// @dev Bounds of `OP_SET_PROFILE_REGISTRY`, an immediate op type.
        DelayPair setProfileRegistry;
        /// @dev Bounds of `OP_SET_REGISTRY`, an immediate op type.
        DelayPair setRegistry;
        /// @dev Bounds of `OP_ADD_VAULT`, an immediate op type.
        DelayPair addVault;
        /// @dev Bounds of `OP_SET_VAULT_MANAGEMENT_MODE`, an immediate op type.
        DelayPair setVaultManagementMode;
        /// @dev Bounds of `OP_REGISTER_STRATEGY`.
        DelayPair registerStrategy;
        /// @dev Bounds of `OP_REPLACE_STRATEGY`.
        DelayPair replaceStrategy;
        /// @dev Bounds of `OP_WITHDRAW`, an immediate op type.
        DelayPair withdraw;
        /// @dev Bounds of `OP_UPGRADE`.
        DelayPair upgrade;
        /// @dev Bounds of `OP_ADD_CHILD_MANAGER`.
        DelayPair addChildManager;
    }

    /// @notice Arguments of `initialize`.
    struct InitializationParams {
        /// @dev Universe whose managers accept the same portable approvals; not zero.
        bytes32 universeId;
        /// @dev Initial operators, distinct.
        address[] operators;
        /// @dev Uncompressed 64-byte secp256k1 public key of each operator, in operator order.
        bytes[] operatorPublicKeys;
        /// @dev Committee signatures a schedule needs, from one to the operator count.
        uint256 committeeThreshold;
        /// @dev Initial security council members, non-zero and distinct.
        address[] securityCouncil;
        /// @dev Council signatures an early execute or a veto needs, from one to the member count.
        uint256 securityCouncilThreshold;
        /// @dev Automata DCAP verifier, or zero for unverified attestation.
        address automataVerifier;
        /// @dev The tplus `Registry` contract, or zero.
        address registryContract;
        /// @dev Withdrawal quorum, from one to the operator count.
        uint256 withdrawalQuorum;
        /// @dev Whether this manager is canonical or local.
        ManagerRole managerRole;
        /// @dev Initial delay bounds of every op type.
        InitialBounds bounds;
    }

    /// @notice Emitted when an operator joins the committee.
    /// @param operator The new operator.
    /// @param publicKey The operator's uncompressed secp256k1 public key.
    event OperatorAdded(address indexed operator, bytes publicKey);

    /// @notice Emitted when an operator leaves the committee.
    /// @param operator The removed operator.
    event OperatorRemoved(address indexed operator);

    /// @notice Emitted when an operator replaces its address and public key.
    /// @param operator The operator's previous address.
    /// @param newOperator The operator's new address.
    /// @param publicKey The new address's uncompressed secp256k1 public key.
    event OperatorRotated(address indexed operator, address indexed newOperator, bytes publicKey);

    /// @notice Emitted when the committee threshold changes.
    /// @param threshold The new threshold.
    event CommitteeThresholdUpdated(uint256 threshold);

    /// @notice Emitted when the security council changes.
    /// @param members The new members.
    /// @param threshold The new threshold.
    event SecurityCouncilUpdated(address[] members, uint256 threshold);

    /// @notice Emitted when the withdrawal quorum changes.
    /// @param quorum The new quorum.
    event WithdrawalQuorumUpdated(uint256 quorum);

    /// @notice Emitted when an operator's attested key changes.
    /// @param operator The operator.
    /// @param oldKey The previous key, or zero.
    /// @param newKey The new key.
    event AttestedKeySet(address indexed operator, address oldKey, address newKey);

    /// @notice Emitted when the Automata verifier changes.
    /// @param verifier The new verifier.
    event AutomataVerifierUpdated(address indexed verifier);

    /// @notice Emitted when the measurement profile registry is set.
    /// @param registry The registry.
    event MeasurementProfileRegistrySet(address indexed registry);

    /// @notice Emitted when the tplus `Registry` pointer is set.
    /// @param registry The `Registry`.
    event RegistryContractSet(address indexed registry);

    /// @notice Emitted when a vault is registered.
    /// @param routingId Routing namespace of the vault's chain.
    /// @param vmId Chain identifier within the routing namespace.
    /// @param vaultAddress The vault's address.
    /// @param config Ingestion settings for the vault's chain.
    event VaultAdded(
        uint256 indexed routingId, uint64 indexed vmId, bytes32 vaultAddress, ChainConfig config
    );

    /// @notice Emitted when a chain's child manager is recorded.
    /// @param routingId Routing namespace of the child manager's chain.
    /// @param vmId Chain identifier within the routing namespace.
    /// @param manager The child manager's address, left-aligned for EVM chains.
    event ChildManagerAdded(uint8 indexed routingId, uint64 indexed vmId, bytes32 manager);

    /// @notice Emitted when a vault's management mode changes.
    /// @param vaultKey The vault's key, see `vaultKey`.
    /// @param mode The new mode.
    event VaultManagementModeUpdated(bytes32 indexed vaultKey, VaultManagementMode mode);

    /// @notice Emitted when a chain's admin-update strategy is registered.
    /// @param routingId Routing namespace of the chain.
    /// @param vmId Chain identifier within the routing namespace.
    /// @param strategy The strategy.
    event AdminUpdateStrategyRegistered(
        uint256 indexed routingId, uint64 indexed vmId, address strategy
    );

    /// @notice Emitted when a chain's admin-update strategy is replaced.
    /// @param routingId Routing namespace of the chain.
    /// @param vmId Chain identifier within the routing namespace.
    /// @param oldStrategy The replaced strategy.
    /// @param newStrategy The replacement.
    event AdminUpdateStrategyReplaced(
        uint256 indexed routingId,
        uint64 indexed vmId,
        address indexed oldStrategy,
        address newStrategy
    );

    /// @notice Emitted when a new governance snapshot is committed.
    /// @param version The snapshot's version.
    /// @param stateHash The snapshot's hash, see `hashGovernanceSnapshot`.
    /// @param snapshot The snapshot.
    event GovernanceSnapshotCommitted(
        uint64 indexed version, bytes32 indexed stateHash, GovernanceSnapshot snapshot
    );

    /// @notice Emitted after a vault's strategy accepts a snapshot delivery.
    /// @param vaultKey The vault's key, see `vaultKey`.
    /// @param version The delivered snapshot's version.
    /// @param stateHash The delivered snapshot's hash.
    /// @param strategy The strategy that delivered it.
    /// @param deliveryIdentifier The strategy's identifier for the delivery.
    event VaultGovernanceSnapshotSyncSubmitted(
        bytes32 indexed vaultKey,
        uint256 indexed version,
        bytes32 indexed stateHash,
        address strategy,
        bytes32 deliveryIdentifier
    );

    /// @notice Thrown when a required address is zero.
    error ZeroAddress();

    /// @notice Thrown when an address is already an operator.
    /// @param operator The address.
    error AlreadyOperator(address operator);

    /// @notice Thrown when an address that has been an operator is added or rotated to.
    /// @param operator The address.
    error FormerOperator(address operator);

    /// @notice Thrown when an address is not an operator.
    /// @param operator The address.
    error NotOperator(address operator);

    /// @notice Thrown when a public key is not 64 bytes or does not derive its operator address.
    /// @param operator The operator the key was given for.
    error InvalidPublicKey(address operator);

    /// @notice Thrown when the operator and public key arrays differ in length.
    error PublicKeyCountMismatch();

    /// @notice Thrown when a committee threshold is zero or above the operator count.
    error InvalidCommitteeThreshold();

    /// @notice Thrown when a council threshold is zero or above the member count.
    error InvalidCouncilThreshold();

    /// @notice Thrown when a member list repeats an address.
    error DuplicateMember();

    /// @notice Thrown when a withdrawal quorum is zero or above the keys that can meet it.
    error InvalidWithdrawalQuorum();

    /// @notice Thrown when an op type's initial bounds must be zero and are not.
    /// @param opType The op type.
    error NonZeroInitialBounds(bytes32 opType);

    /// @notice Thrown when another operator already holds an attested key.
    /// @param key The key.
    error KeyInUse(address key);

    /// @notice Thrown when an attestation sequence does not exceed the last accepted one.
    /// @param sequence The rejected sequence.
    /// @param lastSequence The last accepted sequence.
    error StaleSequence(uint256 sequence, uint256 lastSequence);

    /// @notice Thrown when a packet or rotation signature is malformed or by another signer.
    error InvalidOperatorSignature();

    /// @notice Thrown when an operator rotates while its removal is pending.
    /// @param operator The operator.
    error RemovalPending(address operator);

    /// @notice Thrown when a quote or the verifier's output is too short.
    error InvalidQuoteLength();

    /// @notice Thrown when the verifier rejects a quote.
    /// @param reason The verifier's output.
    error QuoteRejected(bytes reason);

    /// @notice Thrown when the verifier reports a TCB status other than up to date.
    /// @param status The reported status.
    error InvalidTcbStatus(uint8 status);

    /// @notice Thrown when a verified attestation needs the profile registry and it is unset.
    error ProfileRegistryUnset();

    /// @notice Thrown when the profile registry is already set.
    error ProfileRegistryAlreadySet();

    /// @notice Thrown when the tplus `Registry` pointer is already set.
    error RegistryContractAlreadySet();

    /// @notice Thrown when a local manager is asked to set the tplus `Registry` pointer.
    error NotCanonicalManager();

    /// @notice Thrown when the registry has no clearing-engine profile.
    error NoClearingEngineProfile();

    /// @notice Thrown when a measured register differs from the profile.
    /// @param register 0 for MRTD, 1 to 4 for RTMR0 to RTMR3.
    error MeasurementMismatch(uint256 register);

    /// @notice Thrown when a vault address is zero.
    error InvalidVaultAddress();

    /// @notice Thrown when a chain already has a vault.
    error VaultAlreadyExists();

    /// @notice Thrown when a child manager names the chain this manager runs on.
    /// @param routingId The chain's routing namespace.
    /// @param vmId The chain's identifier.
    error ChildManagerOnOwnChain(uint8 routingId, uint64 vmId);

    /// @notice Thrown when a chain already has a child manager.
    /// @param routingId The chain's routing namespace.
    /// @param vmId The chain's identifier.
    error ChildManagerAlreadyAdded(uint8 routingId, uint64 vmId);

    /// @notice Thrown when a chain has no vault.
    error VaultNotFound();

    /// @notice Thrown when another manager synchronizes the vault.
    error VaultManagedByAnotherManager();

    /// @notice Thrown when a strategy address has no code.
    error StrategyHasNoCode();

    /// @notice Thrown when a strategy's code hash is not the pinned one.
    /// @param strategy The strategy.
    error StrategyCodeMismatch(address strategy);

    /// @notice Thrown when a chain already has a strategy.
    error StrategyAlreadyExists();

    /// @notice Thrown when a chain has no strategy.
    error NoStrategy();

    /// @notice Thrown when a chain's strategy is not the expected one.
    error UnexpectedStrategy();

    /// @notice Thrown when a strategy does not enforce snapshot versions.
    error StrategyDoesNotEnforceSnapshotVersion();

    /// @notice Thrown when no governance snapshot has been committed.
    error GovernanceSnapshotUnavailable();

    /// @notice Thrown when an upgrade was not armed by `executeUpgrade`.
    error UpgradeNotAuthorized();

    /// @notice Deploys this implementation's facets and locks it; proxies initialize through
    ///         `initialize`.
    constructor() {
        vaultFacet = address(new VaultFacet());
        attestationFacet = address(new AttestationFacet());
        _disableInitializers();
    }

    /// @notice Allows the manager to hold ETH for bridge fees.
    receive() external payable {}

    /// @notice Initializes a fresh proxy.
    /// @param config The universe, committee, council, verifier, `Registry`, quorum, role and
    ///        bounds.
    function initialize(InitializationParams calldata config) external initializer {
        _core.initializeUniverse(config.universeId);
        uint256 operatorCount = config.operators.length;
        if (config.operatorPublicKeys.length != operatorCount) revert PublicKeyCountMismatch();
        for (uint256 operatorIndex; operatorIndex < operatorCount; ++operatorIndex) {
            address operator = config.operators[operatorIndex];
            bytes memory publicKey = config.operatorPublicKeys[operatorIndex];
            _requireNewOperator(operator, publicKey);
            _addOperator(operator, publicKey);
        }
        _requireCommitteeThreshold(config.committeeThreshold);
        _setCommitteeThreshold(config.committeeThreshold);
        _requireCouncil(config.securityCouncil, config.securityCouncilThreshold);
        _setCouncil(config.securityCouncil, config.securityCouncilThreshold);
        _requireWithdrawalQuorum(config.withdrawalQuorum, operatorCount);
        withdrawalQuorum = config.withdrawalQuorum;
        automataVerifier = IAutomataDcapAttestation(config.automataVerifier);
        registryContract = config.registryContract;
        managerRole = config.managerRole;

        InitialBounds calldata bounds = config.bounds;
        bytes32[_OP_TYPE_COUNT] memory opTypes = [
            OP_ADD_OPERATOR,
            OP_REMOVE_OPERATOR,
            OP_SET_COMMITTEE_THRESHOLD,
            OP_SET_SECURITY_COUNCIL,
            OP_SET_WITHDRAWAL_QUORUM,
            OP_KEY_ROTATION,
            OP_ROTATE_OPERATOR,
            OP_SET_AUTOMATA_VERIFIER,
            OP_SET_PROFILE_REGISTRY,
            OP_SET_REGISTRY,
            OP_ADD_VAULT,
            OP_SET_VAULT_MANAGEMENT_MODE,
            OP_REGISTER_STRATEGY,
            OP_REPLACE_STRATEGY,
            OP_WITHDRAW,
            OP_UPGRADE,
            OP_ADD_CHILD_MANAGER
        ];
        DelayPair[_OP_TYPE_COUNT] calldata pairs;
        assembly ("memory-safe") {
            pairs := bounds
        }
        for (uint256 opIndex; opIndex < _OP_TYPE_COUNT; ++opIndex) {
            bytes32 opType = opTypes[opIndex];
            DelayPair calldata pair = pairs[opIndex];
            if (_isImmediateOpType(opType) && pair.upperSeconds != 0) {
                revert NonZeroInitialBounds(opType);
            }
            _core.initializeBounds(_deploymentOpType(opType), pair.lowerSeconds, pair.upperSeconds);
        }
    }

    // =============================================================
    //                    COMMITTEE OPERATIONS
    // =============================================================

    /// @notice Schedules a committee operation of any op type documented on the `OP_` constants,
    ///         except `OP_KEY_ROTATION`, `OP_ROTATE_OPERATOR` and `OP_UPGRADE`.
    /// @dev Members sign the schedule digest over `deploymentOpType(opType)`.
    /// @param opType The op type's portable ID.
    /// @param params The op type's parameters, ABI-encoded as its constant documents.
    /// @param nonce The nonce the approval was signed with, above the last accepted one.
    /// @param deadline Last timestamp at which the approval may be submitted.
    /// @param signers Committee members in strictly ascending order.
    /// @param signatures Their signatures over the schedule digest.
    /// @return opId The operation's ID.
    function scheduleOperation(
        bytes32 opType,
        bytes calldata params,
        uint256 nonce,
        uint256 deadline,
        address[] calldata signers,
        bytes[] calldata signatures
    ) external returns (bytes32 opId) {
        bytes32 deploymentType = _deploymentOpType(opType);
        return _core.schedule(
            deploymentType,
            _applyOperation(opType, deploymentType, params, false),
            params,
            _committee(),
            nonce,
            deadline,
            signers,
            signatures
        );
    }

    /// @notice Executes a scheduled committee operation and applies it.
    /// @param opId The operation's ID.
    /// @param opType The operation's portable op type ID.
    /// @param params The scheduled parameters.
    /// @param councilSigners Council members in strictly ascending order, or empty.
    /// @param councilSignatures Their signatures over the execute digest, or empty.
    function executeOperation(
        bytes32 opId,
        bytes32 opType,
        bytes calldata params,
        address[] calldata councilSigners,
        bytes[] calldata councilSignatures
    ) external {
        bytes32 deploymentType = _deploymentOpType(opType);
        _execute(
            opId,
            deploymentType,
            _applyOperation(opType, deploymentType, params, false),
            params,
            councilSigners,
            councilSignatures
        );
        _applyOperation(opType, deploymentType, params, true);
    }

    /// @notice Schedules the caller's rotation to a new operator address and public key.
    /// @param newOperator The caller's new address.
    /// @param newPublicKey The new address's uncompressed 64-byte secp256k1 public key.
    /// @param newOperatorSignature The new address's 65-byte low-s ECDSA signature over
    ///        `operatorRotationDigest(msg.sender, newOperator, newPublicKey)`.
    /// @return The operation's ID.
    function scheduleRotateOperator(
        address newOperator,
        bytes calldata newPublicKey,
        bytes calldata newOperatorSignature
    ) external returns (bytes32) {
        _requireOperatorRotation(msg.sender, newOperator, newPublicKey);
        if (
            _recoverSigner(
                    operatorRotationDigest(msg.sender, newOperator, newPublicKey),
                    newOperatorSignature
                ) != newOperator
        ) {
            revert InvalidOperatorSignature();
        }
        return _core.scheduleSelfAuthorized(
            OP_ROTATE_OPERATOR,
            _operatorKey(OP_ROTATE_OPERATOR, msg.sender),
            abi.encode(msg.sender, newOperator, newPublicKey)
        );
    }

    /// @notice Digest a new operator address signs, with no prefix, to take a seat on this manager.
    /// @param operator The operator's current address.
    /// @param newOperator The new address.
    /// @param newPublicKey The new address's public key.
    /// @return The digest.
    function operatorRotationDigest(
        address operator,
        address newOperator,
        bytes calldata newPublicKey
    ) public view returns (bytes32) {
        return keccak256(
            abi.encode(
                OPERATOR_ROTATION_TAG,
                operator,
                newOperator,
                keccak256(newPublicKey),
                block.chainid,
                address(this)
            )
        );
    }

    /// @notice Executes a scheduled operator rotation; the new address keeps the operator's seat,
    ///         membership and attested key.
    /// @param opId The operation's ID.
    /// @param operator The operator's current address.
    /// @param newOperator The scheduled new address.
    /// @param newPublicKey The scheduled public key.
    /// @param councilSigners Council members in strictly ascending order, or empty.
    /// @param councilSignatures Their signatures over the execute digest, or empty.
    function executeRotateOperator(
        bytes32 opId,
        address operator,
        address newOperator,
        bytes calldata newPublicKey,
        address[] calldata councilSigners,
        bytes[] calldata councilSignatures
    ) external {
        _execute(
            opId,
            OP_ROTATE_OPERATOR,
            _operatorKey(OP_ROTATE_OPERATOR, operator),
            abi.encode(operator, newOperator, newPublicKey),
            councilSigners,
            councilSignatures
        );
        _requireOperatorRotation(operator, newOperator, newPublicKey);

        operators[_operatorIndex(operator)] = newOperator;
        delete isOperator[operator];
        isOperator[newOperator] = true;
        _operatorPublicKeys[newOperator] = newPublicKey;
        operatorToAttestedKey[newOperator] = operatorToAttestedKey[operator];
        delete operatorToAttestedKey[operator];
        emit OperatorRotated(operator, newOperator, newPublicKey);
        _commitSnapshotIfChanged();
    }

    // =============================================================
    //                        ATTESTATION
    // =============================================================

    /// @notice Verifies an operator's attestation packet and schedules its key rotation.
    /// @dev With no verifier set, `rawQuote` is the report data itself, at least 40 bytes.
    /// @param rawQuote The clearing engine's DCAP quote, or its report data with no verifier.
    /// @param tcbEvaluationDataNumber Intel TCB evaluation number passed to the verifier.
    /// @param sequence The packet's sequence, above the operator's last accepted one.
    /// @param operatorSignature The operator's 65-byte low-s ECDSA signature over
    ///        `attestationPacketDigest(rawQuote, sequence)`.
    /// @return The rotation operation's ID.
    function submitNodeAttestationOnChain(
        bytes calldata rawQuote,
        uint32 tcbEvaluationDataNumber,
        uint256 sequence,
        bytes calldata operatorSignature
    ) external returns (bytes32) {
        (address operator, address key) = abi.decode(
            LibCall.delegateCallContract(
                attestationFacet,
                abi.encodeCall(
                    AttestationFacet.acceptAttestation,
                    (rawQuote, tcbEvaluationDataNumber, sequence, operatorSignature)
                )
            ),
            (address, address)
        );
        return _core.scheduleSelfAuthorized(
            OP_KEY_ROTATION, _operatorKey(OP_KEY_ROTATION, operator), abi.encode(operator, key)
        );
    }

    /// @notice Executes a scheduled key rotation and commits the snapshot if it changed.
    /// @dev Commits only once the attested keys reach the withdrawal quorum.
    /// @param opId The operation's ID.
    /// @param operator The scheduled operator.
    /// @param key The scheduled attested key.
    /// @param councilSigners Council members in strictly ascending order, or empty.
    /// @param councilSignatures Their signatures over the execute digest, or empty.
    function executeKeyRotation(
        bytes32 opId,
        address operator,
        address key,
        address[] calldata councilSigners,
        bytes[] calldata councilSignatures
    ) external {
        _execute(
            opId,
            OP_KEY_ROTATION,
            _operatorKey(OP_KEY_ROTATION, operator),
            abi.encode(operator, key),
            councilSigners,
            councilSignatures
        );
        if (!isOperator[operator]) revert NotOperator(operator);
        _requireKeyAvailable(operator, key);
        address oldKey = address(uint160(uint256(operatorToAttestedKey[operator])));
        operatorToAttestedKey[operator] = bytes32(uint256(uint160(key)));
        emit AttestedKeySet(operator, oldKey, key);
        _commitSnapshotIfChanged();
    }

    /// @notice Digest an operator signs, with no prefix, for an attestation packet, the same on
    ///         every manager in this manager's universe.
    /// @param rawQuote The packet's quote.
    /// @param sequence The packet's sequence.
    /// @return The digest.
    function attestationPacketDigest(bytes calldata rawQuote, uint256 sequence)
        public
        view
        returns (bytes32)
    {
        return _attestationPacketDigest(rawQuote, sequence);
    }

    // =============================================================
    //                          VAULTS
    // =============================================================

    /// @notice Delivers the committed governance snapshot to a vault through its strategy.
    /// @dev Permissionless and retryable; `msg.value` pays the strategy's bridge fees.
    /// @param routingId Routing namespace of the vault's chain.
    /// @param vmId Chain identifier within the routing namespace.
    function syncVaultGovernanceSnapshot(uint8 routingId, uint64 vmId) external payable {
        (routingId, vmId);
        _forwardToFacet(vaultFacet);
    }

    /// @notice The committed governance snapshot a registered vault receives on sync.
    /// @param routingId Routing namespace of the vault's chain.
    /// @param vmId Chain identifier within the routing namespace.
    /// @return snapshot The snapshot.
    /// @return stateHash The snapshot's hash.
    function getVaultGovernanceSnapshot(uint8 routingId, uint64 vmId)
        external
        view
        returns (GovernanceSnapshot memory snapshot, bytes32 stateHash)
    {
        (routingId, vmId, snapshot, stateHash);
        _forwardToFacetAsView(vaultFacet);
    }

    /// @notice The committed governance snapshot, the genesis a new vault is deployed with.
    /// @dev Reverts with `GovernanceSnapshotUnavailable` before the first commit.
    /// @return snapshot The snapshot.
    /// @return stateHash The snapshot's hash.
    function getGovernanceSnapshot()
        external
        view
        returns (GovernanceSnapshot memory snapshot, bytes32 stateHash)
    {
        (snapshot, stateHash);
        _forwardToFacetAsView(vaultFacet);
    }

    /// @notice Registered vaults in `[start, end)`, clamped to the list.
    /// @param start The first index.
    /// @param end The index after the last.
    /// @return page The vaults.
    function getVaults(uint16 start, uint16 end) external view returns (Vault[] memory page) {
        (start, end, page);
        _forwardToFacetAsView(vaultFacet);
    }

    /// @notice A chain's vault; `vaultAddress` is zero when it has none.
    /// @param routingId Routing namespace of the chain.
    /// @param vmId Chain identifier within the routing namespace.
    /// @return vault The vault.
    function getVault(uint8 routingId, uint64 vmId) external view returns (Vault memory vault) {
        (routingId, vmId, vault);
        _forwardToFacetAsView(vaultFacet);
    }

    /// @notice Every child manager, in the order they were added.
    /// @return children The child managers.
    function getChildManagers() external view returns (ChildManager[] memory children) {
        (children);
        _forwardToFacetAsView(vaultFacet);
    }

    /// @notice A chain's child manager; zero when it has none.
    /// @param routingId Routing namespace of the chain.
    /// @param vmId Chain identifier within the routing namespace.
    /// @return manager The child manager's address, left-aligned for EVM chains.
    function getChildManager(uint8 routingId, uint64 vmId) external view returns (bytes32 manager) {
        (routingId, vmId, manager);
        _forwardToFacetAsView(vaultFacet);
    }

    /// @notice Key of a vault's management mode.
    /// @param routingId Routing namespace of the vault's chain.
    /// @param vmId Chain identifier within the routing namespace.
    /// @param vaultAddress The vault's address.
    /// @return The key.
    function vaultKey(uint8 routingId, uint64 vmId, bytes32 vaultAddress)
        public
        pure
        returns (bytes32)
    {
        return _vaultKey(routingId, vmId, vaultAddress);
    }

    // =============================================================
    //                    UPGRADES AND DELAYS
    // =============================================================

    /// @notice Schedules an upgrade pinned to the implementation's current code hash.
    /// @param implementation The new implementation, a UUPS implementation with code.
    /// @param migrationDataHash Hash of the call made on the new implementation after the switch.
    /// @param nonce The nonce the approval was signed with, above the last accepted one.
    /// @param deadline Last timestamp at which the approval may be submitted.
    /// @param signers Committee members in strictly ascending order.
    /// @param signatures Their signatures over the schedule digest.
    /// @return The operation's ID.
    function scheduleUpgrade(
        address implementation,
        bytes32 migrationDataHash,
        uint256 nonce,
        uint256 deadline,
        address[] calldata signers,
        bytes[] calldata signatures
    ) external returns (bytes32) {
        if (implementation.code.length == 0) revert UpgradeFailed();
        try UUPSUpgradeable(implementation).proxiableUUID() returns (bytes32 slot) {
            if (slot != _ERC1967_IMPLEMENTATION_SLOT) revert UpgradeFailed();
        } catch {
            revert UpgradeFailed();
        }
        bytes32 upgradeType = _deploymentOpType(OP_UPGRADE);
        return _core.schedule(
            upgradeType,
            upgradeType,
            abi.encode(implementation, implementation.codehash, migrationDataHash),
            _committee(),
            nonce,
            deadline,
            signers,
            signatures
        );
    }

    /// @notice Executes a scheduled upgrade and runs its migration call.
    /// @param opId The operation's ID.
    /// @param implementation The scheduled implementation, with its scheduled code hash.
    /// @param migrationData The call whose hash was scheduled; empty skips the call.
    /// @param councilSigners Council members in strictly ascending order, or empty.
    /// @param councilSignatures Their signatures over the execute digest, or empty.
    function executeUpgrade(
        bytes32 opId,
        address implementation,
        bytes calldata migrationData,
        address[] calldata councilSigners,
        bytes[] calldata councilSignatures
    ) external {
        bytes32 upgradeType = _deploymentOpType(OP_UPGRADE);
        _execute(
            opId,
            upgradeType,
            upgradeType,
            abi.encode(implementation, implementation.codehash, keccak256(migrationData)),
            councilSigners,
            councilSignatures
        );
        _authorizedUpgradeImplementation = implementation;
        upgradeToAndCall(implementation, migrationData);
    }

    /// @notice Schedules a change of an op type's delay bounds, waiting its current bounds.
    /// @dev Members sign the delay change for `deploymentOpType(targetOpType)`.
    /// @param targetOpType The portable ID of the op type whose bounds change.
    /// @param lowerSeconds The new lower bound.
    /// @param upperSeconds The new upper bound.
    /// @param nonce The nonce the approval was signed with, above the last accepted one.
    /// @param deadline Last timestamp at which the approval may be submitted.
    /// @param signers Committee members in strictly ascending order.
    /// @param signatures Their signatures over the schedule digest.
    /// @return The operation's ID.
    function scheduleDelayChange(
        bytes32 targetOpType,
        uint64 lowerSeconds,
        uint64 upperSeconds,
        uint256 nonce,
        uint256 deadline,
        address[] calldata signers,
        bytes[] calldata signatures
    ) external returns (bytes32) {
        return _core.scheduleDelayChange(
            _deploymentOpType(targetOpType),
            lowerSeconds,
            upperSeconds,
            _committee(),
            nonce,
            deadline,
            signers,
            signatures
        );
    }

    /// @notice Executes a scheduled delay change.
    /// @param opId The operation's ID.
    /// @param targetOpType The portable ID of the scheduled op type.
    /// @param lowerSeconds The scheduled lower bound.
    /// @param upperSeconds The scheduled upper bound.
    /// @param councilSigners Council members in strictly ascending order, or empty.
    /// @param councilSignatures Their signatures over the execute digest, or empty.
    function executeDelayChange(
        bytes32 opId,
        bytes32 targetOpType,
        uint64 lowerSeconds,
        uint64 upperSeconds,
        address[] calldata councilSigners,
        bytes[] calldata councilSignatures
    ) external {
        _core.executeDelayChange(
            opId,
            _deploymentOpType(targetOpType),
            lowerSeconds,
            upperSeconds,
            _council(),
            councilSigners,
            councilSignatures
        );
    }

    /// @notice Cancels a pending operation with council approval.
    /// @param opId The operation's ID.
    /// @param councilSigners Council members in strictly ascending order.
    /// @param councilSignatures Their signatures over the veto digest.
    function vetoOperation(
        bytes32 opId,
        address[] calldata councilSigners,
        bytes[] calldata councilSignatures
    ) external {
        _core.veto(opId, _council(), councilSigners, councilSignatures);
    }

    // =============================================================
    //                           VIEWS
    // =============================================================

    /// @notice A current operator's uncompressed 64-byte secp256k1 public key.
    /// @param operator The operator.
    /// @return The public key, or empty for an address that is not an operator.
    function operatorPublicKey(address operator) external view returns (bytes memory) {
        if (!isOperator[operator]) return "";
        return _operatorPublicKeys[operator];
    }

    /// @notice The operators with their public keys and the committee threshold.
    /// @return members The operators in member order.
    /// @return keys Each operator's public key, in member order.
    /// @return threshold The committee threshold.
    /// @return memberCount The operator count.
    function getCommitteeConfig()
        external
        view
        returns (
            address[] memory members,
            bytes[] memory keys,
            uint256 threshold,
            uint256 memberCount
        )
    {
        members = operators;
        memberCount = members.length;
        keys = new bytes[](memberCount);
        for (uint256 memberIndex; memberIndex < memberCount; ++memberIndex) {
            keys[memberIndex] = _operatorPublicKeys[members[memberIndex]];
        }
        threshold = committeeThreshold;
    }

    /// @notice The security council and its threshold.
    /// @return members The members.
    /// @return threshold The threshold.
    function getSecurityCouncil()
        external
        view
        returns (address[] memory members, uint256 threshold)
    {
        return (securityCouncil, securityCouncilThreshold);
    }

    /// @notice ID of the operation pending under `key`, or zero.
    /// @param key The key.
    /// @return The operation's ID.
    function pendingId(bytes32 key) external view returns (bytes32) {
        return _core.pendingId(key);
    }

    /// @notice An operation by ID.
    /// @param opId The operation's ID.
    /// @return The operation.
    function operation(bytes32 opId) external view returns (GovernanceCore.Operation memory) {
        return _core.operation(opId);
    }

    /// @notice An op type's delay bounds.
    /// @param opType The op type's portable ID.
    /// @return The bounds.
    function delayBounds(bytes32 opType) external view returns (GovernanceCore.DelayBounds memory) {
        return _core.delayBounds(_deploymentOpType(opType));
    }

    /// @notice The ID this deployment signs, keys and bounds an op type under: the portable ID
    ///         itself, or this deployment's own ID for a deployment-specific op type.
    /// @param opType The op type's portable ID.
    /// @return The deployment op type.
    function deploymentOpType(bytes32 opType) external view returns (bytes32) {
        return _deploymentOpType(opType);
    }

    /// @notice EIP-712 domain separator committee and council approvals are signed under.
    /// @return The domain separator.
    function domainSeparator() external view returns (bytes32) {
        return _core.domainSeparator();
    }

    /// @notice The highest schedule nonce accepted and the council nonce signed next.
    /// @return lastScheduleNonce The highest schedule nonce accepted; sign a schedule above it.
    /// @return nextCouncilNonce The nonce the next council execute or veto signs.
    function governanceNonces()
        external
        view
        returns (uint256 lastScheduleNonce, uint256 nextCouncilNonce)
    {
        return _core.governanceNonces();
    }

    // =============================================================
    //                         INTERNALS
    // =============================================================

    /// @notice Authorizes only the implementation `executeUpgrade` is installing, then clears it.
    /// @param newImplementation The implementation `upgradeToAndCall` switches to.
    function _authorizeUpgrade(address newImplementation) internal override {
        address armedImplementation = _authorizedUpgradeImplementation;
        if (armedImplementation == address(0) || armedImplementation != newImplementation) {
            revert UpgradeNotAuthorized();
        }
        delete _authorizedUpgradeImplementation;
    }

    /// @dev Returns the facet's answer to this same call, for a facet function that is `view`.
    function _forwardToFacetAsView(address facet) private view {
        function(address) internal forward = _forwardToFacet;
        function(address) internal view forwardAsView;
        assembly ("memory-safe") {
            forwardAsView := forward
        }
        forwardAsView(facet);
    }

    function _forwardToFacet(address facet) private {
        bytes memory result = LibCall.delegateCallContract(facet, msg.data);
        assembly ("memory-safe") {
            return(add(result, 0x20), mload(result))
        }
    }

    function _applyOperation(
        bytes32 opType,
        bytes32 deploymentType,
        bytes calldata params,
        bool applyChange
    ) private returns (bytes32 key) {
        if (opType == OP_ADD_OPERATOR) {
            (address operator, bytes memory publicKey) = abi.decode(params, (address, bytes));
            _requireNewOperator(operator, publicKey);
            if (applyChange) {
                _addOperator(operator, publicKey);
                _commitSnapshotIfChanged();
            }
            return _operatorKey(deploymentType, operator);
        } else if (opType == OP_REMOVE_OPERATOR) {
            address operator = abi.decode(params, (address));
            _requireRemovable(operator);
            if (applyChange) {
                uint256 lastIndex = operators.length - 1;
                operators[_operatorIndex(operator)] = operators[lastIndex];
                operators.pop();
                delete isOperator[operator];
                delete operatorToAttestedKey[operator];
                emit OperatorRemoved(operator);
                _commitSnapshotIfChanged();
            }
            return _operatorKey(deploymentType, operator);
        } else if (opType == OP_SET_COMMITTEE_THRESHOLD) {
            uint256 threshold = abi.decode(params, (uint256));
            _requireCommitteeThreshold(threshold);
            if (applyChange) {
                _setCommitteeThreshold(threshold);
                _commitSnapshotIfChanged();
            }
            return deploymentType;
        } else if (opType == OP_SET_SECURITY_COUNCIL) {
            address[] memory members;
            uint256 threshold;
            (members, threshold) = abi.decode(params, (address[], uint256));
            _requireCouncil(members, threshold);
            if (applyChange) {
                uint256 memberCount = securityCouncil.length;
                for (uint256 memberIndex; memberIndex < memberCount; ++memberIndex) {
                    delete isSecurityCouncil[securityCouncil[memberIndex]];
                }
                _setCouncil(members, threshold);
                _commitSnapshotIfChanged();
            }
            return deploymentType;
        } else if (opType == OP_SET_WITHDRAWAL_QUORUM) {
            uint256 quorum = abi.decode(params, (uint256));
            _requireWithdrawalQuorum(quorum, _attestedKeys().length);
            if (applyChange) {
                withdrawalQuorum = quorum;
                emit WithdrawalQuorumUpdated(quorum);
                _commitSnapshotIfChanged();
            }
            return deploymentType;
        } else if (opType == OP_SET_AUTOMATA_VERIFIER) {
            address verifier = abi.decode(params, (address));
            if (verifier == address(0)) revert ZeroAddress();
            if (applyChange) {
                automataVerifier = IAutomataDcapAttestation(verifier);
                emit AutomataVerifierUpdated(verifier);
            }
            return deploymentType;
        } else if (opType == OP_SET_PROFILE_REGISTRY) {
            address registry = abi.decode(params, (address));
            if (registry == address(0)) revert ZeroAddress();
            if (address(measurementProfileRegistry) != address(0)) {
                revert ProfileRegistryAlreadySet();
            }
            if (applyChange) {
                measurementProfileRegistry = IMeasurementProfileRegistry(registry);
                emit MeasurementProfileRegistrySet(registry);
            }
            return deploymentType;
        } else if (opType == OP_SET_REGISTRY) {
            address registry = abi.decode(params, (address));
            if (registry == address(0)) revert ZeroAddress();
            if (managerRole != ManagerRole.Canonical) revert NotCanonicalManager();
            if (registryContract != address(0)) revert RegistryContractAlreadySet();
            if (applyChange) {
                registryContract = registry;
                emit RegistryContractSet(registry);
            }
            return deploymentType;
        } else if (
            opType == OP_ADD_VAULT || opType == OP_SET_VAULT_MANAGEMENT_MODE
                || opType == OP_REGISTER_STRATEGY || opType == OP_REPLACE_STRATEGY
                || opType == OP_ADD_CHILD_MANAGER
        ) {
            return abi.decode(
                LibCall.delegateCallContract(
                    vaultFacet,
                    abi.encodeCall(
                        VaultFacet.applyOperation, (opType, deploymentType, params, applyChange)
                    )
                ),
                (bytes32)
            );
        } else if (opType == OP_WITHDRAW) {
            (address recipient, uint256 amount) = abi.decode(params, (address, uint256));
            if (recipient == address(0)) revert ZeroAddress();
            if (applyChange) SafeTransferLib.safeTransferETH(recipient, amount);
            return deploymentType;
        } else {
            revert GovernanceCore.UnknownOperationType(opType);
        }
    }

    function _isImmediateOpType(bytes32 opType) private pure returns (bool) {
        return opType != OP_ADD_OPERATOR && opType != OP_REMOVE_OPERATOR
            && opType != OP_ROTATE_OPERATOR && opType != OP_SET_AUTOMATA_VERIFIER
            && opType != OP_REGISTER_STRATEGY && opType != OP_REPLACE_STRATEGY
            && opType != OP_UPGRADE && opType != OP_ADD_CHILD_MANAGER;
    }

    function _deploymentOpType(bytes32 opType) private view returns (bytes32) {
        if (
            opType == OP_SET_AUTOMATA_VERIFIER || opType == OP_SET_PROFILE_REGISTRY
                || opType == OP_SET_REGISTRY || opType == OP_UPGRADE || opType == OP_ADD_VAULT
                || opType == OP_SET_VAULT_MANAGEMENT_MODE || opType == OP_REGISTER_STRATEGY
                || opType == OP_REPLACE_STRATEGY || opType == OP_WITHDRAW
                || opType == OP_ADD_CHILD_MANAGER
        ) {
            return GovernanceCore.deriveDeploymentOpType(opType);
        }
        return opType;
    }

    function _execute(
        bytes32 opId,
        bytes32 opType,
        bytes32 key,
        bytes memory params,
        address[] calldata councilSigners,
        bytes[] calldata councilSignatures
    ) private {
        _core.execute(opId, opType, key, params, _council(), councilSigners, councilSignatures);
    }

    function _committee() private view returns (GovernanceCore.Authority memory) {
        return
            GovernanceCore.Authority({isMember: _isCommitteeMember, threshold: committeeThreshold});
    }

    function _council() private view returns (GovernanceCore.Authority memory) {
        return
            GovernanceCore.Authority({
                isMember: _isCouncilMember, threshold: securityCouncilThreshold
            });
    }

    function _isCommitteeMember(address account) private view returns (bool) {
        return isOperator[account];
    }

    function _isCouncilMember(address account) private view returns (bool) {
        return isSecurityCouncil[account];
    }

    function _operatorKey(bytes32 opType, address operator) private pure returns (bytes32) {
        return keccak256(abi.encode(opType, operator));
    }

    function _requireWithdrawalQuorum(uint256 quorum, uint256 maxQuorum) private pure {
        if (quorum == 0 || quorum > maxQuorum) revert InvalidWithdrawalQuorum();
    }

    function _requireNewOperator(address operator, bytes memory publicKey) private view {
        if (isOperator[operator]) revert AlreadyOperator(operator);
        if (_operatorPublicKeys[operator].length != 0) revert FormerOperator(operator);
        if (publicKey.length != 64 || address(uint160(uint256(keccak256(publicKey)))) != operator) {
            revert InvalidPublicKey(operator);
        }
    }

    function _addOperator(address operator, bytes memory publicKey) private {
        operators.push(operator);
        isOperator[operator] = true;
        _operatorPublicKeys[operator] = publicKey;
        emit OperatorAdded(operator, publicKey);
    }

    function _requireRemovable(address operator) private view {
        if (!isOperator[operator]) revert NotOperator(operator);
        if (committeeThreshold > operators.length - 1) revert InvalidCommitteeThreshold();
        if (
            operatorToAttestedKey[operator] != bytes32(0)
                && _attestedKeys().length - 1 < withdrawalQuorum
        ) {
            revert InvalidWithdrawalQuorum();
        }
    }

    function _requireOperatorRotation(
        address operator,
        address newOperator,
        bytes memory newPublicKey
    ) private view {
        if (!isOperator[operator]) revert NotOperator(operator);
        if (_core.pendingId(_operatorKey(OP_REMOVE_OPERATOR, operator)) != bytes32(0)) {
            revert RemovalPending(operator);
        }
        _requireNewOperator(newOperator, newPublicKey);
    }

    function _operatorIndex(address operator) private view returns (uint256 index) {
        while (operators[index] != operator) {
            unchecked {
                ++index;
            }
        }
    }

    function _requireCommitteeThreshold(uint256 threshold) private view {
        if (threshold == 0 || threshold > operators.length) revert InvalidCommitteeThreshold();
    }

    function _setCommitteeThreshold(uint256 threshold) private {
        committeeThreshold = threshold;
        emit CommitteeThresholdUpdated(threshold);
    }

    function _requireCouncil(address[] memory members, uint256 threshold) private pure {
        uint256 memberCount = members.length;
        if (threshold == 0 || threshold > memberCount) revert InvalidCouncilThreshold();
        for (uint256 memberIndex; memberIndex < memberCount; ++memberIndex) {
            address member = members[memberIndex];
            if (member == address(0)) revert ZeroAddress();
            for (uint256 otherIndex = memberIndex + 1; otherIndex < memberCount; ++otherIndex) {
                if (members[otherIndex] == member) revert DuplicateMember();
            }
        }
    }

    function _setCouncil(address[] memory members, uint256 threshold) private {
        for (uint256 memberIndex; memberIndex < members.length; ++memberIndex) {
            isSecurityCouncil[members[memberIndex]] = true;
        }
        securityCouncil = members;
        securityCouncilThreshold = threshold;
        emit SecurityCouncilUpdated(members, threshold);
    }

    function _attestedKeys() private view returns (address[] memory keys) {
        uint256 operatorCount = operators.length;
        keys = new address[](operatorCount);
        uint256 keyCount;
        for (uint256 operatorIndex; operatorIndex < operatorCount; ++operatorIndex) {
            bytes32 attestedKey = operatorToAttestedKey[operators[operatorIndex]];
            if (attestedKey != bytes32(0)) {
                keys[keyCount] = address(uint160(uint256(attestedKey)));
                unchecked {
                    ++keyCount;
                }
            }
        }
        assembly ("memory-safe") {
            mstore(keys, keyCount)
        }
    }

    /// @dev Every operator with its attested key, zero while it has none, and the number of keys.
    function _committeeMembers()
        private
        view
        returns (CommitteeMember[] memory members, uint256 keyCount)
    {
        uint256 operatorCount = operators.length;
        members = new CommitteeMember[](operatorCount);
        for (uint256 operatorIndex; operatorIndex < operatorCount; ++operatorIndex) {
            address operator = operators[operatorIndex];
            address key = address(uint160(uint256(operatorToAttestedKey[operator])));
            members[operatorIndex] = CommitteeMember({operator: operator, key: key});
            if (key != address(0)) ++keyCount;
        }
    }

    /// @dev Builds the snapshot from live state and commits it under the next version when its
    ///      content differs from the committed one, once the live keys reach the withdrawal quorum.
    ///      A threshold or quorum above `uint16` reverts rather than truncates.
    function _commitSnapshotIfChanged() private {
        (CommitteeMember[] memory members, uint256 keyCount) = _committeeMembers();
        GovernanceSnapshot memory snapshot = GovernanceSnapshot({
            version: _governanceSnapshot.version,
            members: members,
            council: securityCouncil,
            committeeThreshold: SafeCastLib.toUint16(committeeThreshold),
            councilThreshold: SafeCastLib.toUint16(securityCouncilThreshold),
            withdrawalQuorum: SafeCastLib.toUint16(withdrawalQuorum)
        });
        if (keyCount < snapshot.withdrawalQuorum) return;
        // Same version as the committed snapshot, so equal hashes mean equal content.
        if (hashGovernanceSnapshot(snapshot) == governanceSnapshotHash) return;

        ++snapshot.version;
        bytes32 stateHash = hashGovernanceSnapshot(snapshot);
        _governanceSnapshot = snapshot;
        governanceSnapshotHash = stateHash;
        emit GovernanceSnapshotCommitted(snapshot.version, stateHash, snapshot);
    }
}

