// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {ECDSA} from "solady/utils/ECDSA.sol";
import {CredentialManager} from "./CredentialManager.sol";
import {GovernanceCore} from "./governance/GovernanceCore.sol";
import {IAdminUpdateStrategy} from "./interfaces/IAdminUpdateStrategy.sol";
import {IAutomataDcapAttestation} from "./interfaces/IAutomataDcapAttestation.sol";
import {IMeasurementProfileRegistry} from "./interfaces/IMeasurementProfileRegistry.sol";
import {GovernanceSnapshot} from "./types/GovernanceSnapshot.sol";

/// @title CredentialManagerStorage
/// @notice The CredentialManager's op types, storage layout and the helpers its facets share.
abstract contract CredentialManagerStorage {
    using GovernanceCore for GovernanceCore.State;

    /// @notice Adds an operator with its public key.
    /// @dev Portable. Params `abi.encode(address operator, bytes publicKey)`, the key 64
    ///      uncompressed bytes deriving `operator`. Key `(opType, operator)`.
    bytes32 internal constant OP_ADD_OPERATOR = keccak256("CredentialManager.ADD_OPERATOR");
    /// @notice Removes an operator and its attested key.
    /// @dev Portable. Params `abi.encode(address operator)`. Key `(opType, operator)`.
    bytes32 internal constant OP_REMOVE_OPERATOR = keccak256("CredentialManager.REMOVE_OPERATOR");
    /// @notice Sets the committee threshold.
    /// @dev Portable. Params `abi.encode(uint256 threshold)`. Key `opType`.
    bytes32 internal constant OP_SET_COMMITTEE_THRESHOLD =
        keccak256("CredentialManager.SET_COMMITTEE_THRESHOLD");
    /// @notice Replaces the security council and its threshold.
    /// @dev Portable. Params `abi.encode(address[] members, uint256 threshold)`. Key `opType`.
    bytes32 internal constant OP_SET_SECURITY_COUNCIL =
        keccak256("CredentialManager.SET_SECURITY_COUNCIL");
    /// @notice Sets the withdrawal quorum.
    /// @dev Portable. Params `abi.encode(uint256 quorum)`. Key `opType`.
    bytes32 internal constant OP_SET_WITHDRAWAL_QUORUM =
        keccak256("CredentialManager.SET_WITHDRAWAL_QUORUM");
    /// @notice Sets an operator's attested key, scheduled by `submitNodeAttestationOnChain`.
    /// @dev Portable. Params `abi.encode(address operator, address key)`. Key `(opType, operator)`.
    bytes32 internal constant OP_KEY_ROTATION = keccak256("CredentialManager.KEY_ROTATION");
    /// @notice Moves an operator's seat to a new address and public key, scheduled by
    ///         `scheduleRotateOperator`.
    /// @dev Portable key and bounds; its signature binds this manager. Params
    ///      `abi.encode(address operator, address newOperator, bytes newPublicKey)`. Key
    ///      `(opType, operator)`.
    bytes32 internal constant OP_ROTATE_OPERATOR = keccak256("CredentialManager.ROTATE_OPERATOR");
    /// @notice Sets the Automata DCAP verifier.
    /// @dev Deployment-specific. Params `abi.encode(address verifier)`. Key `opType`.
    bytes32 internal constant OP_SET_AUTOMATA_VERIFIER =
        keccak256("CredentialManager.SET_AUTOMATA_VERIFIER");
    /// @notice Sets the measurement profile registry, once.
    /// @dev Deployment-specific. Params `abi.encode(address registry)`. Key `opType`.
    bytes32 internal constant OP_SET_PROFILE_REGISTRY =
        keccak256("CredentialManager.SET_PROFILE_REGISTRY");
    /// @notice Sets the tplus `Registry` pointer, once, on the canonical manager.
    /// @dev Deployment-specific. Params `abi.encode(address registry)`. Key `opType`.
    bytes32 internal constant OP_SET_REGISTRY = keccak256("CredentialManager.SET_REGISTRY");
    /// @notice Registers a chain's deposit vault.
    /// @dev Deployment-specific. Params `abi.encode(uint8 routingId, uint64 vmId, bytes32
    ///      vaultAddress, ChainConfig config)`. Key `(opType, routingId, vmId)`.
    bytes32 internal constant OP_ADD_VAULT = keccak256("CredentialManager.ADD_VAULT");
    /// @notice Sets whether this manager synchronizes a vault.
    /// @dev Deployment-specific. Params `abi.encode(uint8 routingId, uint64 vmId,
    ///      VaultManagementMode mode)`. Key `(opType, routingId, vmId)`.
    bytes32 internal constant OP_SET_VAULT_MANAGEMENT_MODE =
        keccak256("CredentialManager.SET_VAULT_MANAGEMENT_MODE");
    /// @notice Registers a chain's admin-update strategy, pinned to its code hash.
    /// @dev Deployment-specific. Params `abi.encode(uint8 routingId, uint64 vmId, address
    ///      strategy, bytes32 codeHash)`. Key `(opType, routingId, vmId)`.
    bytes32 internal constant OP_REGISTER_STRATEGY =
        keccak256("CredentialManager.REGISTER_STRATEGY");
    /// @notice Replaces a chain's admin-update strategy, pinned to its code hash.
    /// @dev Deployment-specific. Params `abi.encode(uint8 routingId, uint64 vmId, address
    ///      expectedCurrent, address replacement, bytes32 codeHash)`. Key `(opType, routingId,
    ///      vmId)`.
    bytes32 internal constant OP_REPLACE_STRATEGY = keccak256("CredentialManager.REPLACE_STRATEGY");
    /// @notice Withdraws ETH held for bridge fees.
    /// @dev Deployment-specific. Params `abi.encode(address recipient, uint256 amount)`. Key
    ///      `opType`.
    bytes32 internal constant OP_WITHDRAW = keccak256("CredentialManager.WITHDRAW");
    /// @notice Upgrades the implementation, scheduled by `scheduleUpgrade`.
    /// @dev Deployment-specific. Params `abi.encode(address implementation, bytes32 codeHash,
    ///      bytes32 migrationDataHash)`. Key `opType`.
    bytes32 internal constant OP_UPGRADE = keccak256("CredentialManager.UPGRADE");
    /// @notice Records the child manager that is a chain's trust anchor, once per chain.
    /// @dev Deployment-specific. Params `abi.encode(uint8 routingId, uint64 vmId, bytes32
    ///      manager)`. Key `(opType, routingId, vmId)`.
    bytes32 internal constant OP_ADD_CHILD_MANAGER =
        keccak256("CredentialManager.ADD_CHILD_MANAGER");
    /// @notice Domain tag of the chain-agnostic attestation packet digest.
    bytes32 internal constant ATTESTATION_PACKET_TAG = keccak256("TPLUS_ATTESTATION_PACKET_V1");
    /// @notice Domain tag of the digest a new operator address signs to accept a seat.
    bytes32 internal constant OPERATOR_ROTATION_TAG = keccak256("TPLUS_OPERATOR_ROTATION_V1");

    /// @notice Scheduled operations, delay bounds, nonces and the universe.
    GovernanceCore.State internal _core;

    /// @notice Operator at each index, in member order.
    address[] public operators;
    /// @notice Whether an address is an operator.
    mapping(address => bool) public isOperator;
    /// @notice Public key of every address that has been an operator, kept after it leaves.
    mapping(address => bytes) internal _operatorPublicKeys;
    /// @notice Committee signatures a schedule needs.
    uint256 public committeeThreshold;

    /// @notice Security council member at each index.
    address[] public securityCouncil;
    /// @notice Whether an address is a security council member.
    mapping(address => bool) public isSecurityCouncil;
    /// @notice Council signatures an early execute or a veto needs.
    uint256 public securityCouncilThreshold;

    /// @notice Each operator's attested key, right-aligned.
    mapping(address => bytes32) public operatorToAttestedKey;
    /// @notice Highest attestation sequence accepted for each operator.
    mapping(address => uint256) public lastAttestationSequence;
    /// @notice Signer approvals a vault withdrawal needs.
    uint256 public withdrawalQuorum;

    /// @notice Automata DCAP verifier, or zero for unverified attestation.
    IAutomataDcapAttestation public automataVerifier;
    /// @notice Registry holding the clearing-engine measurement profile.
    IMeasurementProfileRegistry public measurementProfileRegistry;
    /// @notice The tplus `Registry` contract, or zero.
    address public registryContract;
    /// @notice Whether this manager is canonical or local.
    CredentialManager.ManagerRole public managerRole;

    /// @notice Registered vaults in registration order.
    CredentialManager.Vault[] public vaults;
    /// @notice Admin-update strategy per routing ID and chain.
    mapping(uint256 => mapping(uint64 => IAdminUpdateStrategy)) public adminUpdateStrategies;
    /// @notice Management mode per vault key.
    mapping(bytes32 => CredentialManager.VaultManagementMode) public vaultManagementModes;

    /// @notice The committed governance snapshot; version zero before the first commit.
    GovernanceSnapshot internal _governanceSnapshot;
    /// @notice Hash of the committed governance snapshot, see `hashGovernanceSnapshot`.
    bytes32 public governanceSnapshotHash;

    /// @notice Implementation `executeUpgrade` is installing, cleared once authorized.
    address internal _authorizedUpgradeImplementation;

    /// @notice Code hash each admin-update strategy is pinned to, per routing ID and chain.
    mapping(uint256 => mapping(uint64 => bytes32)) internal _adminUpdateStrategyCodeHashes;

    /// @notice Child managers in the order they were added.
    CredentialManager.ChildManager[] internal _childManagers;
    /// @notice Child manager per routing ID and chain; zero for none.
    mapping(uint256 => mapping(uint64 => bytes32)) internal _childManagerByChain;

    /// @notice Key of a vault's management mode.
    /// @param routingId Routing namespace of the vault's chain.
    /// @param vmId Chain identifier within the routing namespace.
    /// @param vaultAddress The vault's address.
    /// @return The key.
    function _vaultKey(uint8 routingId, uint64 vmId, bytes32 vaultAddress)
        internal
        pure
        returns (bytes32)
    {
        return keccak256(abi.encode(routingId, vmId, vaultAddress));
    }

    /// @notice Digest an operator signs, with no prefix, for an attestation packet.
    /// @param rawQuote The packet's quote.
    /// @param sequence The packet's sequence.
    /// @return The digest.
    function _attestationPacketDigest(bytes calldata rawQuote, uint256 sequence)
        internal
        view
        returns (bytes32)
    {
        return keccak256(
            abi.encode(
                ATTESTATION_PACKET_TAG, _core.domainSeparator(), keccak256(rawQuote), sequence
            )
        );
    }

    /// @notice Signer of a 65-byte low-s ECDSA signature over `digest`.
    /// @param digest The signed digest, with no prefix.
    /// @param signature The signature.
    /// @return The signer.
    function _recoverSigner(bytes32 digest, bytes calldata signature)
        internal
        view
        returns (address)
    {
        if (signature.length != 65) revert CredentialManager.InvalidOperatorSignature();
        bytes32 signatureS = bytes32(signature[32:64]);
        if (uint256(signatureS) > ECDSA.N >> 1) {
            revert CredentialManager.InvalidOperatorSignature();
        }
        return ECDSA.recover(digest, uint8(signature[64]), bytes32(signature[0:32]), signatureS);
    }

    /// @notice Reverts unless `key` is non-zero and no operator other than `operator` holds it.
    /// @param operator The operator taking the key.
    /// @param key The attested key.
    function _requireKeyAvailable(address operator, address key) internal view {
        if (key == address(0)) revert CredentialManager.ZeroAddress();
        bytes32 attestedKey = bytes32(uint256(uint160(key)));
        uint256 operatorCount = operators.length;
        for (uint256 operatorIndex; operatorIndex < operatorCount; ++operatorIndex) {
            address other = operators[operatorIndex];
            if (other != operator && operatorToAttestedKey[other] == attestedKey) {
                revert CredentialManager.KeyInUse(key);
            }
        }
    }
}

src/DepositVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {SafeTransferLib} from "solady/utils/SafeTransferLib.sol";
import {EfficientHashLib} from "solady/utils/EfficientHashLib.sol";
import {ECDSA} from "solady/utils/ECDSA.sol";
import {SafeCastLib} from "solady/utils/SafeCastLib.sol";
import {ReentrancyGuard} from "solady/utils/ReentrancyGuard.sol";
import {IAtomicSettlementCallback} from "./interfaces/IAtomicSettlementCallback.sol";
import {TPlusUUPSUpgradeable} from "./utils/TPlusUUPSUpgradeable.sol";
import {
    CommitteeMember,
    GovernanceSnapshot,
    hashGovernanceSnapshot,
    requireValidGovernanceSnapshot
} from "./types/GovernanceSnapshot.sol";

contract DepositVault is TPlusUUPSUpgradeable, ReentrancyGuard {
    /// @notice The number of decimals used by the clearing engine for normalized amounts.
    /// @dev Must stay in sync with the clearing engine's normalization logic.
    uint8 internal constant CLEARING_ENGINE_DECIMALS = 18;

    /**
     * @notice The admin approves settlements and withdrawals.
     * @dev Should be set to the DStack container shared secret address.
     */
    address public owner;

    /**
     * @notice The address responsible for adding or removing administrators
     * @dev In production, this will be an upgradeable proxy
     */
    address public credentialManager;

    /// @notice Domain separator used for signature verification. It should include the routing ID, the vm ID, this
    /// vault address, and the settlement schema version.
    bytes32 internal _domainSeparator;

    /// @notice Maps settler IDs to their executor addresses.
    mapping(bytes32 => SettlerInfo) settlerExecutorMap;

    /// @notice List of all approved settler IDs.
    bytes32[] public approvedSettlers;

    /// @notice Tracks which settler IDs have been approved.
    mapping(bytes32 => bool) internal settlerIsApproved;

    /**
     * @notice Maximum total tokens that can be settled in a single block for each token.
     * @dev Currently unused — implementation pending design finalization.
     */
    mapping(address => uint256) public settlementCaps;

    /// @notice Maps (settler ID, account_index) pairs to their settlement count (nonce).
    mapping(bytes32 => mapping(uint64 => uint64)) public settlementCounts;

    /// @notice Maps user ID pairs to their deposit count (nonce).
    mapping(bytes32 => uint64) public depositCounts;

    /// @notice Per-asset minimum amount required on a user's first deposit, in token native units.
    /// @dev A value of 0 disables first-deposit minimum enforcement for that token.
    mapping(address => uint256) public minFirstDepositAmounts;

    /// @notice Maps user ID to their withdrawal count (nonce).
    mapping(bytes32 => uint64) public withdrawalCounts;

    /// @notice The governance snapshot the credential manager last delivered, stored as delivered.
    /// @dev Its members' non-zero keys are the withdrawal administrators and its
    ///      `withdrawalQuorum` the number of their approvals a withdrawal needs. Before the first
    ///      delivery it holds the genesis snapshot the vault was deployed with.
    GovernanceSnapshot internal _governanceSnapshot;

    // TODO: Delete before official production.
    /// @notice Whether an address may deposit while depositor approval is in force.
    mapping(address => bool) public canDeposit;

    /// @notice Block number of latest signature use
    uint256 public lastSignatureUse;

    /**
     * Makes the signature unambiguous that it is for settlements.
     */
    bytes32 public constant SETTLEMENT_TYPEHASH = keccak256("SettlementApprovalV2");

    /**
     * Makes the signature unambiguous that it is for withdrawals.
     */
    bytes32 constant WITHDRAWAL_TYPEHASH = keccak256("WithdrawalApprovalV1");

    enum SettlementMode {
        Spot,
        Margin
    }

    /// @notice Request for settlement
    /// @dev Used for all forms of settlement supported by the t+ vault
    struct Settlement {
        /// @notice Address of the token to be sent OUT from the vault
        address tokenOut;
        /// @notice Quantity of the output token to be sent OUT from the vault
        uint256 amountOut;
        /// @notice Address of the token to be sent IN to the vault
        address tokenIn;
        /// @notice Quantity of the input token to be sent IN from the vault
        uint256 amountIn;
        /// @notice Explicit CE settlement mode.
        SettlementMode mode;
        /// @notice Unique identifier of the user being settled
        bytes32 user;
        /// @notice Account index of the user being settled
        uint64 account;
        /// @notice Settlement nonce for this request
        uint64 nonce;
        /// @notice Unix timestamp (seconds) at which this request is valid until (i.e.,
        ///         immediately after this time this request is considered
        ///         expired). Compared against `block.timestamp`.
        uint256 validUntil;
    }

    /// @notice A settlement request with associated signatures
    struct SignedSettlement {
        /// @notice Settlement request
        Settlement settlement;
        /// @notice Signature from the t+ Clearing Engine (CE)
        bytes clearingEngineSignature;
    }

    /// @notice Records a withdrawal.
    struct Withdrawal {
        address tokenAddress;
        uint256 amount;
        uint64 nonce;
    }

    /// @notice Information about a settler account.
    struct SettlerInfo {
        address[] executors;
        mapping(address => bool) isExecutor;
    }

    /// @notice Balance of a token for squashing purposes
    struct TokenSquashingBalance {
        /// @notice Address of the token that this balance represents
        address token;
        /// @notice Total quantity of tokens that the vault needs to receive
        uint256 input;
        /// @notice Total quantity of tokens that the vault needs to send
        uint256 output;
        /// @notice Net quantity of tokens that the vault needs to receive
        ///         (i.e., negative implies sending more tokens out than the
        ///         vault is receiving)
        int256 netAmount;
    }

    /// @notice Multisig signer configuration
    struct SignerConfig {
        bytes32 key;
        uint8 keyType;
        uint8 keyPrefix;
        uint32 weight;
        uint64 expiresAtNs;
        uint64 maxSigningWindowNs;
    }

    /// @notice Signals a settlement.
    event Settled(
        bytes32 indexed user,
        uint64 indexed account,
        uint256 indexed nonce,
        address tokenOut,
        uint256 amountOut,
        address tokenIn,
        uint256 amountIn,
        SettlementMode mode,
        bytes32 settler
    );

    /// @notice Emitted when the vault stores a governance snapshot, its genesis or a delivery.
    /// @param version The snapshot's version.
    /// @param stateHash The snapshot's hash, see `hashGovernanceSnapshot`.
    /// @param snapshot The snapshot.
    event GovernanceSnapshotSet(
        uint64 indexed version, bytes32 indexed stateHash, GovernanceSnapshot snapshot
    );

    /// @notice Signals that the withdrawal quorum has changed
    event WithdrawalQuorumChanged(uint256 previous, uint256 current);

    /// @notice Signals that the credential manager address has changed
    event CredentialManagerChanged(address oldCredentialManager, address newCredentialManager);

    /// @notice Signals a deposit
    event Deposited(
        bytes32 indexed user, uint256 indexed nonce, address indexed tokenAddress, uint256 amount
    );

    /// @notice Signals a deposit containing additional multisig signer information
    event DepositedWithConfig(
        bytes32 indexed user,
        uint256 indexed nonce,
        address indexed tokenAddress,
        uint256 amount,
        uint32 masterWeight,
        uint32 lowThreshold,
        uint32 mediumThreshold,
        uint32 highThreshold,
        SignerConfig[] signers,
        bytes masterConfigSignature
    );

    /// @notice Signals that the minimum first-deposit amount for a token has changed.
    event MinFirstDepositAmountChanged(
        address indexed tokenAddress, uint256 previous, uint256 current
    );

    /// @notice Signals a withdrawal.
    event Withdrew(
        bytes32 indexed user, uint256 indexed nonce, address tokenAddress, uint256 amount
    );

    /// @notice Reverts if the caller is not the owner.
    error NotOwner();

    /// @notice Reverts if the specified settler is not an approved settler on
    ///         this vault
    error SettlerNotApproved();

    /// @notice Reverts if the specified depositor is not approved.
    error DepositorNotApproved();

    /// @notice Reverts when the vault receives a different amount than requested.
    error TokenAmountMismatch(uint256 expected, uint256 actual);

    /// @notice Reverts when an incoming transfer's token balance cannot be read.
    error TokenBalanceQueryFailed();

    /// @notice Reverts if the number of callback data payloads does not match
    ///         the number of settlement requests
    error PayloadMismatch();

    /// @notice Reverts if a settlement callback returns an insufficient input token amount
    error InsufficientAmountFromExecutor(uint256 actual, uint256 required);

    /// @notice Reverts if a settlement callback returns insufficient amount for a specific settlement
    error InsufficientCallbackReturnForSettlement(
        uint256 settlementIndex, uint256 actual, uint256 required
    );

    /// @notice Reverts if the caller is not the credential manager
    error NotCredentialManager();

    /// @notice Reverts if a new withdrawal quorum value is equal to zero
    error ZeroWithdrawalQuorum();

    /// @notice Reverts if the caller is not an admin.
    error NotAdmin();

    /// @notice Reverts if the caller is not the authorized executor.
    error NotExecutor();

    /// @notice Reverts if a signed operation is past its deadline.
    error Expired();

    /// @notice Reverts if the nonce used in a transaction is incorrect.
    error InvalidNonce(uint256 expected, uint256 given);

    /// @notice Reverts if the signature provided is invalid.
    error InvalidSignature();

    /// @notice Reverts when given the zero address.
    error ZeroAddress();

    /// @notice Reverts when given a zero amount.
    error ZeroAmount();

    /// @notice Reverts when normalizing the deposit amount to 18 decimals would overflow
    error NormalizationOverflow();

    /// @notice Reverts when the token does not implement decimals()
    error DecimalsCallFailed();

    /// @notice Reverts when the user's first deposit amount is below the configured minimum.
    error FirstDepositBelowMinimum(uint256 minimum, uint256 actual);

    /// @notice Reverts when normalizing a deposit amount to 18 decimals would round to zero.
    error NormalizationRoundsToZero();

    /// @notice Reverts when an insufficient number of signatures are provided for a withdrawal request
    error MissedQuorum(uint256 provided, uint256 required);

    /// @notice Reverts when `administrators(index)` is past the last administrator.
    error AdministratorIndexOutOfBounds(uint256 index);

    /// @notice Reverts when caller is not authorized to configure vault-local settings.
    /// @dev Authorized callers are owner, credential manager, and vault administrators.
    error NotVaultConfigManager();

    /// @dev Direct (non-proxy) deployments cannot be upgraded, so no upgrade delay is set here.
    /// @param _owner The address to set as the owner.
    /// @param _credentialManager The credential manager, see `initialize`.
    /// @param genesis The genesis snapshot, see `initialize`.
    constructor(address _owner, address _credentialManager, GovernanceSnapshot memory genesis) {
        _initialize(_owner, _credentialManager, genesis);
    }

    /**
     * @notice Initializes a proxy deployment.
     * @param _owner The address to set as the owner.
     * @param _credentialManager The address of the credential manager (or, on a spoke chain,
     *        the admin-update receiver that relays the credential manager's decisions).
     * @param _upgradeDelaySeconds Timelock applied to implementation upgrades; see
     *        {TPlusUUPSUpgradeable} for bounds and how it can be changed later.
     * @param genesis The credential manager's committed snapshot at deploy time, which the vault
     *        runs on until the first delivery. Checked by `requireValidGovernanceSnapshot`, since
     *        it comes from the deployer rather than the credential manager.
     * @dev Reverts with `ZeroAddress()` if `_owner` or `_credentialManager` is null.
     */
    function initialize(
        address _owner,
        address _credentialManager,
        uint64 _upgradeDelaySeconds,
        GovernanceSnapshot calldata genesis
    ) external initializer {
        _initialize(_owner, _credentialManager, genesis);
        _initializeUpgradeDelay(_upgradeDelaySeconds);
    }

    function _initialize(
        address _owner,
        address _credentialManager,
        GovernanceSnapshot memory genesis
    ) internal {
        if (_owner == address(0)) revert ZeroAddress();
        if (_credentialManager == address(0)) revert ZeroAddress();
        owner = _owner;
        credentialManager = _credentialManager;
        requireValidGovernanceSnapshot(genesis);
        _governanceSnapshot = genesis;
        _emitGovernanceSnapshotSet(0);
    }

    function _isUpgradeAuthority(address caller) internal view override returns (bool) {
        return caller == owner || caller == credentialManager;
    }

    /// @notice Whether `account` is a withdrawal administrator: a member's key in the governance
    ///         snapshot. Zero, a member's key while it has none, never is.
    /// @param account The account.
    /// @return Whether it is an administrator.
    function isAdministrator(address account) public view returns (bool) {
        if (account == address(0)) return false;
        CommitteeMember[] storage members = _governanceSnapshot.members;
        for (uint256 i = 0; i < members.length; i++) {
            if (members[i].key == account) return true;
        }

        return false;
    }

    /// @notice The withdrawal administrator at `index`: the `index`-th non-zero member key in the
    ///         governance snapshot.
    /// @dev Reverts with `AdministratorIndexOutOfBounds` past the last one.
    /// @param index The administrator's index.
    /// @return The administrator.
    function administrators(uint256 index) external view returns (address) {
        CommitteeMember[] storage members = _governanceSnapshot.members;
        uint256 seen;
        for (uint256 i = 0; i < members.length; i++) {
            address key = members[i].key;
            if (key == address(0)) continue;
            if (seen == index) return key;
            seen++;
        }
        revert AdministratorIndexOutOfBounds(index);
    }

    /// @notice Administrator approvals a withdrawal needs, from the governance snapshot.
    /// @return The withdrawal quorum.
    function withdrawalQuorum() public view returns (uint256) {
        return _governanceSnapshot.withdrawalQuorum;
    }

    /**
     * @notice Sets the owner of the vault.
     * @dev Reverts with `NotOwner`; Only the owner can set a new owner.
     */
    function setOwner(address newOwner) external {
        if (msg.sender != owner) revert NotOwner();
        if (newOwner == address(0)) revert ZeroAddress();
        owner = newOwner;
    }

    /// @notice Sets the credential manager, the only caller of `setGovernanceSnapshot`.
    /// @dev Reverts with `NotOwner` unless called by the owner, and with `ZeroAddress` for zero.
    /// @param newCredentialManager The new credential manager: the CredentialManager on its own
    ///        chain, the receiver on an L2.
    function setCredentialManager(address newCredentialManager) external {
        if (msg.sender != owner) revert NotOwner();
        if (newCredentialManager == address(0)) revert ZeroAddress();
        // TODO: Protect credential-manager changes with a scheduled, delayed operation on the
        // governance core, as the CredentialManager's own settings are.
        address oldCredentialManager = credentialManager;
        credentialManager = newCredentialManager;
        emit CredentialManagerChanged(oldCredentialManager, newCredentialManager);
    }

    /// @notice Stores a governance snapshot delivered by the credential manager.
    /// @dev The content is not validated: the credential manager only commits snapshots that can
    ///      authorise a withdrawal, and `withdraw` rejects a zero quorum at use.
    /// @param snapshot The snapshot.
    function setGovernanceSnapshot(GovernanceSnapshot calldata snapshot) external {
        if (msg.sender != credentialManager) revert NotCredentialManager();
        uint256 oldWithdrawalQuorum = _governanceSnapshot.withdrawalQuorum;
        _governanceSnapshot = snapshot;
        _emitGovernanceSnapshotSet(oldWithdrawalQuorum);
    }

    /// @notice The governance snapshot the credential manager last delivered.
    function getGovernanceSnapshot() external view returns (GovernanceSnapshot memory) {
        return _governanceSnapshot;
    }

    function _emitGovernanceSnapshotSet(uint256 oldWithdrawalQuorum) private {
        GovernanceSnapshot memory snapshot = _governanceSnapshot;
        emit GovernanceSnapshotSet(snapshot.version, hashGovernanceSnapshot(snapshot), snapshot);

        uint256 newWithdrawalQuorum = _governanceSnapshot.withdrawalQuorum;
        if (oldWithdrawalQuorum != newWithdrawalQuorum) {
            emit WithdrawalQuorumChanged(oldWithdrawalQuorum, newWithdrawalQuorum);
        }
    }

    /// @notice Domain separator bound into settlement and withdrawal approval digests.
    function domainSeparator() external view returns (bytes32) {
        return _domainSeparator;
    }

    /**
     * @notice Sets the domain separators for EIP-712 signatures.
     * @param domainSeparator: The value to set.
     * @dev Reverts with `NotOwner`; Only the admin can set the domain separator.
     */
    function setDomainSeparator(bytes32 domainSeparator) external {
        if (msg.sender != owner) revert NotOwner();
        require(_domainSeparator == 0); // dev: Already set.
        _domainSeparator = domainSeparator;
    }

    /**
     * @notice Sets the settle executor.
     * @param settler: The settler's tplus account key.
     * @param executor: The settler's assigned executor address.
     * @dev Reverts with `NotOwner`; Only the admin can set the settler executor.
     */
    function addSettlerExecutor(bytes32 settler, address executor) external {
        if (msg.sender != owner) revert NotOwner();

        if (!settlerIsApproved[settler]) {
            approvedSettlers.push(settler);
            settlerIsApproved[settler] = true;
        }

        SettlerInfo storage data = settlerExecutorMap[settler];
        if (!data.isExecutor[executor]) {
            data.executors.push(executor);
            data.isExecutor[executor] = true;
        }
    }

    /**
     * @notice Removes a settler.
     * @param settler: The settler's tplus account key.
     * @dev Reverts with `NotOwner`; Only the admin can remove a settler.
     */
    function removeSettler(bytes32 settler) external {
        if (msg.sender != owner) revert NotOwner();
        uint256 length = approvedSettlers.length;

        settlerIsApproved[settler] = false;

        for (uint256 i = 0; i < length; i++) {
            if (approvedSettlers[i] == settler) {
                // Move last element to this spot and pop the last element.
                approvedSettlers[i] = approvedSettlers[length - 1];
                approvedSettlers.pop();
                break;
            }
        }

        // Remove all executors.
        SettlerInfo storage info = settlerExecutorMap[settler];
        for (uint256 i = 0; i < info.executors.length; i++) {
            address exec = info.executors[i];
            info.isExecutor[exec] = false;
        }
        delete info.executors;
    }

    /**
     * @notice Deposits a token into the vault.
     * @param user: The user whose account will be credited with the deposit.
     * @param tokenAddress: The address of the token to deposit.
     * @param amount: The amount of the token to deposit.
     * @dev Reverts if the amount is 0.
     */
    function deposit(bytes32 user, address tokenAddress, uint256 amount) external {
        uint256 nonce = _deposit(user, tokenAddress, amount);
        emit Deposited(user, nonce, tokenAddress, amount);
    }

    /**
     * @notice Deposits a token into the vault with additional multisig signer configuration.
     * @param user: The user whose account will be credited with the deposit.
     * @param tokenAddress: The address of the token to deposit.
     * @param amount: The amount of the token to deposit.
     * @dev Reverts if the amount is 0.
     */
    function deposit(
        bytes32 user,
        address tokenAddress,
        uint256 amount,
        uint32 masterWeight,
        uint32 lowThreshold,
        uint32 mediumThreshold,
        uint32 highThreshold,
        SignerConfig[] calldata signers,
        bytes calldata masterConfigSignature
    ) external {
        uint256 nonce = _deposit(user, tokenAddress, amount);
        emit DepositedWithConfig(
            user,
            nonce,
            tokenAddress,
            amount,
            masterWeight,
            lowThreshold,
            mediumThreshold,
            highThreshold,
            signers,
            masterConfigSignature
        );
    }

    function _deposit(bytes32 user, address tokenAddress, uint256 amount)
        internal
        nonReadReentrant
        returns (uint64 nonce)
    {
        if (!canDeposit[msg.sender]) revert DepositorNotApproved();
        if (amount == 0) revert ZeroAmount();

        // Ensure the deposit amount won't overflow when the clearing engine
        // normalizes it to CLEARING_ENGINE_DECIMALS.
        uint8 decimals = _getDecimals(tokenAddress);
        if (decimals < CLEARING_ENGINE_DECIMALS) {
            uint256 scalingFactor = 10 ** (CLEARING_ENGINE_DECIMALS - decimals);
            if (amount > type(uint256).max / scalingFactor) revert NormalizationOverflow();
        } else if (decimals > CLEARING_ENGINE_DECIMALS) {
            uint256 scalingFactor = 10 ** (decimals - CLEARING_ENGINE_DECIMALS);
            if (amount < scalingFactor) revert NormalizationRoundsToZero();
        }

        nonce = depositCounts[user];
        if (nonce == 0) {
            uint256 minimumFirstDepositAmount = minFirstDepositAmounts[tokenAddress];
            if (amount < minimumFirstDepositAmount) {
                revert FirstDepositBelowMinimum(minimumFirstDepositAmount, amount);
            }
        }
        depositCounts[user] = nonce + 1;

        _pullExact(tokenAddress, msg.sender, amount);
        return nonce;
    }

    /// @dev Isolate the receipt measurement without locking settlement executor callbacks.
    function _pullExact(address token, address from, uint256 amount) private nonReentrant {
        (bool beforeOk, uint256 balanceBefore) =
            SafeTransferLib.checkBalanceOf(token, address(this));
        if (!beforeOk) revert TokenBalanceQueryFailed();
        SafeTransferLib.safeTransferFrom(token, from, address(this), amount);
        (bool afterOk, uint256 balanceAfter) = SafeTransferLib.checkBalanceOf(token, address(this));
        if (!afterOk) revert TokenBalanceQueryFailed();
        uint256 received = balanceAfter >= balanceBefore ? balanceAfter - balanceBefore : 0;
        if (balanceAfter < balanceBefore || received != amount) {
            revert TokenAmountMismatch(amount, received);
        }
    }

    function _getDecimals(address tokenAddress) internal view returns (uint8) {
        (bool success, bytes memory data) =
            tokenAddress.staticcall(abi.encodeWithSignature("decimals()"));
        if (!success || data.length < 32) revert DecimalsCallFailed();
        return abi.decode(data, (uint8));
    }

    // TODO: Delete this method and notion of approved-depositor before official production.
    /// @notice Allows or disallows an address to deposit. Owner only.
    /// @param depositor The address.
    /// @param allowed Whether it may deposit.
    function setDepositorStatus(address depositor, bool allowed) external {
        if (msg.sender != owner) revert NotOwner();
        canDeposit[depositor] = allowed;
    }

    /**
     * @notice Sets the minimum first-deposit amount for a token on this vault.
     * @dev This is intentionally vault-local so each chain can be configured without cross-chain registry reads.
     * @dev Callable by owner (bootstrap), credential manager, or vault administrators.
     */
    function setMinFirstDepositAmount(address tokenAddress, uint256 minimumAmount) external {
        if (msg.sender != owner && msg.sender != credentialManager && !isAdministrator(msg.sender))
        {
            revert NotVaultConfigManager();
        }
        if (tokenAddress == address(0)) revert ZeroAddress();

        uint256 previous = minFirstDepositAmounts[tokenAddress];
        minFirstDepositAmounts[tokenAddress] = minimumAmount;
        emit MinFirstDepositAmountChanged(tokenAddress, previous, minimumAmount);
    }

    /**
     * @notice Computes the canonical `SettlementApprovalV2` digest for a settlement order.
     * @dev Shared by `executeAtomicSettlement` and `executeSquashingSettlements` so their
     *      digest formats cannot drift apart. `settler` is bound into the digest so a
     *      signature issued for one settler cannot be replayed under another.
     */
    function _settlementDigest(Settlement memory order, bytes32 settler)
        internal
        view
        returns (bytes32)
    {
        return keccak256(
            bytes.concat(
                SETTLEMENT_TYPEHASH,
                _domainSeparator,
                bytes32(uint256(uint160(order.tokenOut)) << 96),
                bytes32(order.amountOut),
                bytes32(uint256(uint160(order.tokenIn)) << 96),
                bytes32(order.amountIn),
                bytes32(uint256(uint8(order.mode))),
                order.user,
                bytes32(uint256(uint160(order.account))),
                bytes32(uint256(order.nonce)),
                bytes32(order.validUntil),
                settler
            )
        );
    }

    /**
     * @notice Executes an atomic settlement.
     * @param order: The settlement order.
     * @param settler: The t+ identity of the settler executing this order.
     * @param data: The data to execute as part of settlement callback.
     * @param signature: The signature from the t+ clearing engine.
     * @dev Reverts with `Expired` if the block timestamp is greater than `validUntil`.
     * @dev Reverts with `SettlerNotApproved` if the settler is not in the approved set.
     * @dev Reverts with `NotExecutor`; Only the executor can settle.
     * @dev Reverts with `InvalidNonce` if the nonce has already been used.
     * @dev Reverts with `InvalidSignature` if the signer is not an admin.
     * @dev Reverts with `InsufficientAmountFromExecutor` if the `order.amountIn` is less than what the executor reports
     */
    function executeAtomicSettlement(
        Settlement calldata order,
        bytes32 settler,
        bytes calldata data,
        bytes calldata signature
    ) external nonReadReentrant {
        bytes32 user = order.user;
        uint64 account = order.account;
        uint256 validUntil = order.validUntil;

        if (block.timestamp > validUntil) revert Expired();
        if (!settlerIsApproved[settler]) revert SettlerNotApproved();
        if (!settlerExecutorMap[settler].isExecutor[msg.sender]) revert NotExecutor();

        uint256 expectedNonce = settlementCounts[user][account];
        if (order.nonce < expectedNonce) revert InvalidNonce(expectedNonce, order.nonce);

        bytes32 digest = _settlementDigest(order, settler);

        // Check the signature and record latest signature usage if it's valid
        checkApproval(digest, signature);
        lastSignatureUse = block.number;

        /* SAFETY(jmcph4): Increment nonce prior to callback to avoid signature
        * replay attacks. Additionally, we increase the nonce by more than one
        * in order to allow skipping ahead (as the CE may legitimately approve
        * nonces higher than the current latest). */
        settlementCounts[user][account] = order.nonce + 1;

        // Transfer tokens OUT to the executor
        SafeTransferLib.safeTransfer(order.tokenOut, msg.sender, order.amountOut);

        // Invoke callback on the executor
        uint256 expectedAmountIn = IAtomicSettlementCallback(msg.sender)
            .onAtomicSettlement(order.tokenOut, order.amountOut, data);
        if (expectedAmountIn < order.amountIn) {
            revert InsufficientAmountFromExecutor(expectedAmountIn, order.amountIn);
        }

        // Transfer tokens IN from the executor
        _pullExact(order.tokenIn, msg.sender, expectedAmountIn);

        emit Settled(
            user,
            account,
            order.nonce,
            order.tokenOut,
            order.amountOut,
            order.tokenIn,
            order.amountIn,
            order.mode,
            settler
        );
    }

    /// @notice Execute a sequence of settlement requests in a squashing fashion
    /// @param requests List of settlement requests
    function executeSquashingSettlements(
        SignedSettlement[] calldata requests,
        bytes[] calldata data,
        bytes32 settler
    ) external nonReadReentrant {
        address caller = msg.sender;
        uint256 numRequests = requests.length;
        uint256 numDataPayloads = data.length;
        if (numRequests != numDataPayloads) revert PayloadMismatch();

        /**
         * SAFETY(jmcph4): Check that settler is approved
         *
         * This prevents unauthorised settlers from executing settlements.
         */
        if (!settlerIsApproved[settler]) revert SettlerNotApproved();

        /**
         * SAFETY(jmcph4): Check that the caller is an assigned executor for this settler
         *
         * This prevents unauthorised execution of valid settlement requests.
         */
        if (!settlerExecutorMap[settler].isExecutor[caller]) revert NotExecutor();

        // Allocate token balances for netting off
        TokenSquashingBalance[] memory balances = new TokenSquashingBalance[](numRequests * 2);
        uint256 numUniqueTokens = 0;

        for (uint256 i = 0; i < numRequests; i++) {
            SignedSettlement memory currRequest = requests[i];
            bytes32 user = currRequest.settlement.user;
            uint64 account = currRequest.settlement.account;
            uint64 actualNonce = currRequest.settlement.nonce;
            uint256 validUntil = currRequest.settlement.validUntil;
            address tokenIn = currRequest.settlement.tokenIn;
            address tokenOut = currRequest.settlement.tokenOut;
            uint256 amountIn = currRequest.settlement.amountIn; /* TODO(jmcph4): callback */
            uint256 amountOut = currRequest.settlement.amountOut;

            /**
             * SAFETY(jmcph4): Check expiry
             *
             * This prevents stale settlement requests from being executed.
             */
            if (block.timestamp > validUntil) revert Expired();

            /**
             * SAFETY(jmcph4): Check nonce
             *
             * This prevents replay attacks on settlement requests.
             */
            uint256 expectedNonce = settlementCounts[user][account];
            if (actualNonce < expectedNonce) revert InvalidNonce(expectedNonce, actualNonce);

            bytes32 digest = _settlementDigest(currRequest.settlement, settler);

            /**
             * SAFETY(jmcph4): Verify t+ Clearing Engine (CE) signature
             *
             * This prevents unauthorised settlements.
             */
            checkApproval(digest, requests[i].clearingEngineSignature); /* TODO(jmcph4): horrific calldata load */
            lastSignatureUse = block.number;

            /**
             * SAFETY(jmcph4): Increment settlement nonce prior to invoking the
             *                  callback
             *
             * This prevents replay attacks (reentrant or otherwise) on
             * settlement requests.
             */
            settlementCounts[user][account] = actualNonce + 1;

            // Apply this request to running net token balances
            bool inputFound = false;
            bool outputFound = false;
            for (uint256 j = 0; j < numUniqueTokens; j++) {
                if (balances[j].token == tokenIn) {
                    balances[j].input += amountIn;
                    inputFound = true;
                    break;
                }
            }

            if (!inputFound) {
                balances[numUniqueTokens] = TokenSquashingBalance(tokenIn, amountIn, 0, 0);
                numUniqueTokens++;
            }

            for (uint256 j = 0; j < numUniqueTokens; j++) {
                if (balances[j].token == tokenOut) {
                    balances[j].output += amountOut;
                    outputFound = true;
                    break;
                }
            }

            if (!outputFound) {
                balances[numUniqueTokens] = TokenSquashingBalance(tokenOut, 0, amountOut, 0);
                numUniqueTokens++;
            }
        }

        // Net off each token balance
        for (uint256 i = 0; i < numUniqueTokens; i++) {
            if (balances[i].input > balances[i].output) {
                balances[i].netAmount = int256(balances[i].input - balances[i].output);
            } else if (balances[i].output > balances[i].input) {
                balances[i].netAmount = -int256(balances[i].output - balances[i].input);
            }
        }

        // Push funds out from the vault and into the executor
        for (uint256 i = 0; i < numUniqueTokens; i++) {
            // Negative net amount implies that we must push funds out from the vault
            if (balances[i].netAmount < 0) {
                // Transfer tokens OUT to the executor
                SafeTransferLib.safeTransfer(
                    balances[i].token, caller, uint256(-balances[i].netAmount)
                );
            }
        }

        // Call callbacks and record return values
        uint256[] memory callbackReturns = new uint256[](numRequests);

        for (uint256 i = 0; i < numRequests; i++) {
            Settlement memory request = requests[i].settlement;

            /**
             * SAFETY(jmcph4): Record callback return value
             *
             * The executor reports how much of tokenIn it will provide for this
             * specific settlement. Pass the per-settlement amountOut, not the net.
             * These values will be validated against requirements before pulling funds.
             */
            callbackReturns[i] = IAtomicSettlementCallback(msg.sender)
                .onAtomicSettlement(request.tokenOut, request.amountOut, data[i]);

            /**
             * SAFETY(jmcph4): Validate per-settlement callback return
             *
             * Ensure the executor commits to provide at least the promised amountIn
             * for THIS specific settlement. This prevents cross-settlement subsidization
             * where an executor could shortchange one user while overpaying another.
             */
            if (callbackReturns[i] < request.amountIn) {
                revert InsufficientCallbackReturnForSettlement(
                    i, callbackReturns[i], request.amountIn
                );
            }
        }

        // Validate callback returns and pull funds
        for (uint256 i = 0; i < numUniqueTokens; i++) {
            // Only process tokens that need to be pulled (positive net amount)
            if (balances[i].netAmount > 0) {
                address token = balances[i].token;
                uint256 requiredAmount = uint256(balances[i].netAmount);

                /**
                 * SAFETY(jmcph4): Sum callback returns by token
                 *
                 * Calculate total amount the executor has committed to provide
                 * for this token across all settlements.
                 */
                uint256 totalCallbackAmount = 0;
                for (uint256 j = 0; j < numRequests; j++) {
                    if (requests[j].settlement.tokenIn == token) {
                        totalCallbackAmount += callbackReturns[j];
                    }
                }

                /**
                 * SAFETY(jmcph4): Validate executor commitment
                 *
                 * Ensure the executor has committed to provide at least the
                 * required net amount for this token.
                 */
                if (totalCallbackAmount < requiredAmount) {
                    revert InsufficientAmountFromExecutor(totalCallbackAmount, requiredAmount);
                }

                // Transfer tokens IN from the executor
                _pullExact(token, caller, requiredAmount);
            }
        }

        // Emit settlement events
        for (uint256 i = 0; i < numRequests; i++) {
            Settlement memory request = requests[i].settlement;

            /**
             * SAFETY(jmcph4): Emit per-settlement amounts
             *
             * Events must reflect the actual per-settlement amounts, not the netted
             * amounts. This ensures proper accounting and allows off-chain systems
             * to correctly track what each user received.
             */
            emit Settled(
                request.user,
                request.account,
                request.nonce,
                request.tokenOut,
                request.amountOut,
                request.tokenIn,
                request.amountIn,
                request.mode,
                settler
            );
        }
    }

    /**
     * @notice Withdraws a token from the vault.
     * @param withdrawal: The withdrawal token and amount.
     * @param user: The user whose account will be debited by the withdrawal.
     * @param target: The target address to send the token to.
     * @param validUntil: The timestamp when the withdrawal signature expires.
     * @param signatures: t+ clearing engine signatures.
     * @dev Reverts with `Expired` if the block timestamp is greater than `validUntil`.
     * @dev Reverts with `InvalidNonce` if the nonce has already been used.
     * @dev Reverts with `SignatureError` if the signer is not an admin.
     */
    function withdraw(
        Withdrawal calldata withdrawal,
        bytes32 user,
        address target,
        uint256 validUntil,
        bytes32 epochHash,
        bytes[] calldata signatures
    ) external nonReadReentrant {
        /* PERF(jmcph4): cache storage variable to the stack */
        uint256 quorum = withdrawalQuorum();
        // The genesis and every committed snapshot have a non-zero quorum; a zero one would need
        // no signature at all.
        if (quorum == 0) revert ZeroWithdrawalQuorum();
        if (block.timestamp > validUntil) revert Expired();
        if (signatures.length < quorum) {
            revert MissedQuorum(signatures.length, quorum);
        }

        uint256 expectedNonce = withdrawalCounts[user];
        if (withdrawal.nonce < expectedNonce) {
            revert InvalidNonce(expectedNonce, withdrawal.nonce);
        }

        /**
         * BEGIN SIGNATURE CHECKS *************************
         */

        // Set of administrators that have provided signatures for this withdrawal
        address[] memory seenAdmins = new address[](signatures.length);
        uint256 numSeenAdmins = 0;

        // PERF(jmcph4): No need to recompute inside the loop body
        bytes32 digest = keccak256(
            bytes.concat(
                WITHDRAWAL_TYPEHASH,
                _domainSeparator,
                bytes32(uint256(uint160((withdrawal.tokenAddress))) << 96),
                bytes32(withdrawal.amount),
                user,
                bytes32(uint256(withdrawal.nonce)),
                bytes32(validUntil),
                bytes32(epochHash),
                bytes32(uint256(uint160(target)) << 96)
            )
        );

        for (uint256 i = 0; i < signatures.length; i++) {
            /* Verify the signature.
             *
             * This determines whether the digest is really signed by the provided
             * signature and computes the signer's address.
             */
            address signer = ECDSA.tryRecoverCalldata(digest, signatures[i]);
            if (signer == address(0)) revert InvalidSignature();

            // Check that the recovered signer is in fact an administrator
            if (!isAdministrator(signer)) revert InvalidSignature();

            /* Check that this administrator is unique. Without this step, a
             * single admin could provide `k` signatures where `k == withdrawalQuorum`
             * and we'd happily approve the withdrawal.
             */
            bool isCurrentSignerUnique = true;
            for (uint256 j = 0; j < numSeenAdmins; j++) {
                if (seenAdmins[j] == signer) {
                    isCurrentSignerUnique = false;
                    break;
                }
            }
            if (isCurrentSignerUnique) {
                seenAdmins[numSeenAdmins] = signer;
                numSeenAdmins++;
            }
            if (numSeenAdmins == quorum) break;
        }

        if (numSeenAdmins < quorum) revert MissedQuorum(numSeenAdmins, quorum);

        /**
         * END SIGNATURE CHECKS *************************
         */

        // SAFETY(jmcph4): Purposely bump the nonce as close to signature verification as possible, to alleviate callback concerns.
        withdrawalCounts[user] = withdrawal.nonce + 1;

        // Record latest signature usage
        lastSignatureUse = block.number;

        SafeTransferLib.safeTransfer(withdrawal.tokenAddress, target, withdrawal.amount);
        emit Withdrew(user, withdrawal.nonce, withdrawal.tokenAddress, withdrawal.amount);
    }

    /**
     * @notice Get the array of approved settlers.
     * @return An array of addresses (as bytes32) that are currently approved settlers.
     */
    function getApprovedSettlers() external view returns (bytes32[] memory) {
        return approvedSettlers;
    }

    // TODO: Delete this method before official production.
    /// @notice Transfers `amount` of `token` held by the vault to `to`. Owner only.
    /// @param token The token.
    /// @param to The recipient, non-zero.
    /// @param amount The amount, in the token's own decimals.
    function ownerWithdrawToken(address token, address to, uint256 amount)
        external
        nonReadReentrant
    {
        if (msg.sender != owner) revert NotOwner();
        require(to != address(0));
        SafeTransferLib.safeTransfer(token, to, amount);
    }

    function checkApproval(bytes32 digest, bytes calldata signature) internal view {
        address signer = ECDSA.tryRecoverCalldata(digest, signature);
        if (signer == address(0)) revert InvalidSignature();
        if (!isAdministrator(signer)) revert InvalidSignature();
    }
}

src/MeasurementProfileRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Initializable} from "solady/utils/Initializable.sol";
import {UUPSUpgradeable} from "solady/utils/UUPSUpgradeable.sol";
import {GovernanceCore} from "./governance/GovernanceCore.sol";
import {ICredentialManager} from "./interfaces/ICredentialManager.sol";

/// @title MeasurementProfileRegistry
/// @notice Approved TDX (Intel Trust Domain Extensions) build measurements per service kind: the
///         MRTD (Measurement Register of the Trust Domain) and RTMR0 to RTMR3 (Runtime
///         Measurement Registers), set by the CredentialManager's committee and vetoable by its
///         security council. Every chain that hosts a CredentialManager has its own, signed for by
///         that chain's manager. Kind IDs: 0 clearing engine, 1 orderbook, 2 order management
///         service, 3 oracle, 4 blockchain client, 5 interest engine, 6 cross-venue margin
///         adapter, 7 market data service, 8 other, 9 liquidator.
contract MeasurementProfileRegistry is Initializable, UUPSUpgradeable {
    using GovernanceCore for GovernanceCore.State;

    /// @notice Number of service kinds.
    uint32 public constant KIND_COUNT = 10;

    /// @notice Kind ID of the clearing engine.
    uint32 internal constant _CLEARING_ENGINE_KIND = 0;

    /// @notice Sets a kind's profile.
    /// @dev Portable. Op type and key `profileOpType(kind)`, hashed from this and the kind.
    ///      Params `abi.encode(uint32 kind, Profile profile)`.
    bytes32 public constant OP_SET_PROFILE = keccak256("MeasurementProfileRegistry.SET_PROFILE");

    /// @notice Upgrades the implementation, scheduled by `scheduleUpgrade`.
    /// @dev Deployment-specific. Params `abi.encode(address implementation, bytes32 codeHash,
    ///      bytes32 migrationDataHash)`. Key `opType`.
    bytes32 public constant OP_UPGRADE = keccak256("MeasurementProfileRegistry.UPGRADE");

    /// @notice A service kind's approved measurements.
    struct Profile {
        /// @dev The first 32 bytes of the expected MRTD; zero means no profile is in force.
        bytes32 mrtd;
        /// @dev The first 32 bytes of the expected RTMR0; zero means not checked.
        bytes32 rtmr0;
        /// @dev The first 32 bytes of the expected RTMR1; zero means not checked.
        bytes32 rtmr1;
        /// @dev The first 32 bytes of the expected RTMR2; zero means not checked.
        bytes32 rtmr2;
        /// @dev The first 32 bytes of the expected RTMR3; zero means not checked.
        bytes32 rtmr3;
    }

    /// @notice The CredentialManager whose committee and security council govern here.
    ICredentialManager public credentialManager;

    /// @dev Each kind's profile.
    mapping(uint32 kind => Profile) internal _profiles;
    /// @dev The governance state of every operation here.
    GovernanceCore.State internal _core;
    /// @dev The implementation `executeUpgrade()` is installing, for `_authorizeUpgrade`.
    address internal _authorizedUpgradeImplementation;

    /// @notice Emitted when a kind's profile is set.
    /// @param kind The service kind.
    /// @param profile The kind's new measurements.
    event ProfileSet(uint32 indexed kind, Profile profile);

    /// @notice Thrown when a kind ID is not below `KIND_COUNT`.
    /// @param kind The rejected kind.
    error UnknownKind(uint32 kind);

    /// @notice Thrown when a required address is zero.
    error ZeroAddress();

    /// @notice Thrown when the CredentialManager's approvals are signed under another domain.
    error DomainMismatch();

    /// @notice Thrown when `upgradeToAndCall` is called outside `executeUpgrade()`.
    error UpgradeNotAuthorized();

    /// @notice Locks the implementation so only proxies can be initialized.
    constructor() {
        _disableInitializers();
    }

    /// @notice Sets the CredentialManager, the universe and every op type's delay bounds, once.
    /// @param manager The CredentialManager whose committee and security council govern here.
    /// @param universeId The universe whose approvals the CredentialManager accepts.
    /// @param kindBounds Each kind's delay pair, by kind ID.
    /// @param upgradeBounds The delay pair of `OP_UPGRADE`.
    function initialize(
        ICredentialManager manager,
        bytes32 universeId,
        ICredentialManager.DelayPair[KIND_COUNT] calldata kindBounds,
        ICredentialManager.DelayPair calldata upgradeBounds
    ) external initializer {
        if (address(manager) == address(0)) revert ZeroAddress();
        credentialManager = manager;
        _core.initializeUniverse(universeId);
        if (_core.domainSeparator() != manager.domainSeparator()) {
            revert DomainMismatch();
        }
        for (uint32 kind; kind < KIND_COUNT; ++kind) {
            ICredentialManager.DelayPair calldata bounds = kindBounds[kind];
            _core.initializeBounds(_profileOpType(kind), bounds.lowerSeconds, bounds.upperSeconds);
        }
        _core.initializeBounds(
            _deploymentOpType(OP_UPGRADE), upgradeBounds.lowerSeconds, upgradeBounds.upperSeconds
        );
    }

    /// @notice Schedules a kind's profile, superseding the one pending for that kind.
    /// @param kind The service kind.
    /// @param newProfile The measurements; a zero MRTD clears the kind's profile.
    /// @param nonce The nonce the approval was signed with, above the last accepted one.
    /// @param deadlineSeconds Last timestamp at which the approval may be submitted.
    /// @param signers Committee members in strictly ascending order.
    /// @param signatures Their signatures over the schedule digest.
    /// @return opId The operation's ID.
    function scheduleSetProfile(
        uint32 kind,
        Profile calldata newProfile,
        uint256 nonce,
        uint256 deadlineSeconds,
        address[] calldata signers,
        bytes[] calldata signatures
    ) external returns (bytes32 opId) {
        bytes32 opType = _profileOpType(kind);
        return _core.schedule(
            opType,
            opType,
            abi.encode(kind, newProfile),
            _committee(),
            nonce,
            deadlineSeconds,
            signers,
            signatures
        );
    }

    /// @notice Executes a scheduled profile.
    /// @param opId The operation's ID.
    /// @param kind The scheduled kind.
    /// @param newProfile The scheduled measurements.
    /// @param councilSigners Council members in strictly ascending order, or empty.
    /// @param councilSignatures Their signatures over the execute digest, or empty.
    function executeSetProfile(
        bytes32 opId,
        uint32 kind,
        Profile calldata newProfile,
        address[] calldata councilSigners,
        bytes[] calldata councilSignatures
    ) external {
        bytes32 opType = _profileOpType(kind);
        _core.execute(
            opId,
            opType,
            opType,
            abi.encode(kind, newProfile),
            _councilIfSigned(councilSigners, councilSignatures),
            councilSigners,
            councilSignatures
        );
        _profiles[kind] = newProfile;
        emit ProfileSet(kind, newProfile);
    }

    /// @notice Schedules an upgrade pinned to the implementation's current code hash.
    /// @param implementation The new implementation, a UUPS implementation with code.
    /// @param migrationDataHash Hash of the call made on the new implementation after the switch.
    /// @param nonce The nonce the approval was signed with, above the last accepted one.
    /// @param deadlineSeconds Last timestamp at which the approval may be submitted.
    /// @param signers Committee members in strictly ascending order.
    /// @param signatures Their signatures over the schedule digest.
    /// @return opId The operation's ID.
    function scheduleUpgrade(
        address implementation,
        bytes32 migrationDataHash,
        uint256 nonce,
        uint256 deadlineSeconds,
        address[] calldata signers,
        bytes[] calldata signatures
    ) external returns (bytes32 opId) {
        if (implementation.code.length == 0) revert UpgradeFailed();
        try UUPSUpgradeable(implementation).proxiableUUID() returns (bytes32 slot) {
            if (slot != _ERC1967_IMPLEMENTATION_SLOT) revert UpgradeFailed();
        } catch {
            revert UpgradeFailed();
        }
        bytes32 upgradeType = _deploymentOpType(OP_UPGRADE);
        return _core.schedule(
            upgradeType,
            upgradeType,
            abi.encode(implementation, implementation.codehash, migrationDataHash),
            _committee(),
            nonce,
            deadlineSeconds,
            signers,
            signatures
        );
    }

    /// @notice Executes a scheduled upgrade and runs its migration call.
    /// @param opId The operation's ID.
    /// @param implementation The scheduled implementation, with its scheduled code hash.
    /// @param migrationData The call whose hash was scheduled; empty skips the call.
    /// @param councilSigners Council members in strictly ascending order, or empty.
    /// @param councilSignatures Their signatures over the execute digest, or empty.
    function executeUpgrade(
        bytes32 opId,
        address implementation,
        bytes calldata migrationData,
        address[] calldata councilSigners,
        bytes[] calldata councilSignatures
    ) external {
        bytes32 upgradeType = _deploymentOpType(OP_UPGRADE);
        _core.execute(
            opId,
            upgradeType,
            upgradeType,
            abi.encode(implementation, implementation.codehash, keccak256(migrationData)),
            _councilIfSigned(councilSigners, councilSignatures),
            councilSigners,
            councilSignatures
        );
        _authorizedUpgradeImplementation = implementation;
        upgradeToAndCall(implementation, migrationData);
    }

    /// @notice Schedules a change of an op type's delay bounds, waiting its current bounds.
    /// @param targetOpType `profileOpType(kind)` or `OP_UPGRADE`.
    /// @param lowerSeconds The new lower bound.
    /// @param upperSeconds The new upper bound.
    /// @param nonce The nonce the approval was signed with, above the last accepted one.
    /// @param deadlineSeconds Last timestamp at which the approval may be submitted.
    /// @param signers Committee members in strictly ascending order.
    /// @param signatures Their signatures over the schedule digest.
    /// @return opId The operation's ID.
    function scheduleDelayChange(
        bytes32 targetOpType,
        uint64 lowerSeconds,
        uint64 upperSeconds,
        uint256 nonce,
        uint256 deadlineSeconds,
        address[] calldata signers,
        bytes[] calldata signatures
    ) external returns (bytes32 opId) {
        return _core.scheduleDelayChange(
            _deploymentOpType(targetOpType),
            lowerSeconds,
            upperSeconds,
            _committee(),
            nonce,
            deadlineSeconds,
            signers,
            signatures
        );
    }

    /// @notice Executes a scheduled delay change.
    /// @param opId The operation's ID.
    /// @param targetOpType The scheduled op type.
    /// @param lowerSeconds The scheduled lower bound.
    /// @param upperSeconds The scheduled upper bound.
    /// @param councilSigners Council members in strictly ascending order, or empty.
    /// @param councilSignatures Their signatures over the execute digest, or empty.
    function executeDelayChange(
        bytes32 opId,
        bytes32 targetOpType,
        uint64 lowerSeconds,
        uint64 upperSeconds,
        address[] calldata councilSigners,
        bytes[] calldata councilSignatures
    ) external {
        _core.executeDelayChange(
            opId,
            _deploymentOpType(targetOpType),
            lowerSeconds,
            upperSeconds,
            _councilIfSigned(councilSigners, councilSignatures),
            councilSigners,
            councilSignatures
        );
    }

    /// @notice Cancels a pending operation with council approval.
    /// @param opId The operation's ID.
    /// @param councilSigners Council members in strictly ascending order.
    /// @param councilSignatures Their signatures over the veto digest.
    function vetoOperation(
        bytes32 opId,
        address[] calldata councilSigners,
        bytes[] calldata councilSignatures
    ) external {
        _core.veto(opId, _council(), councilSigners, councilSignatures);
    }

    /// @notice A kind's approved measurements; a zero MRTD means no profile is set.
    /// @param kind The service kind.
    /// @return The kind's profile.
    function profile(uint32 kind) external view returns (Profile memory) {
        _requireKnownKind(kind);
        return _profiles[kind];
    }

    /// @notice The clearing engine's approved measurements; a zero MRTD means no profile is set.
    /// @return mrtd The first 32 bytes of the expected MRTD.
    /// @return rtmr0 The first 32 bytes of the expected RTMR0.
    /// @return rtmr1 The first 32 bytes of the expected RTMR1.
    /// @return rtmr2 The first 32 bytes of the expected RTMR2.
    /// @return rtmr3 The first 32 bytes of the expected RTMR3.
    function clearingEngineProfile()
        external
        view
        returns (bytes32 mrtd, bytes32 rtmr0, bytes32 rtmr1, bytes32 rtmr2, bytes32 rtmr3)
    {
        Profile storage clearingEngine = _profiles[_CLEARING_ENGINE_KIND];
        return (
            clearingEngine.mrtd,
            clearingEngine.rtmr0,
            clearingEngine.rtmr1,
            clearingEngine.rtmr2,
            clearingEngine.rtmr3
        );
    }

    /// @notice The op type and key a kind's profile is scheduled under.
    /// @param kind The service kind.
    /// @return The op type.
    function profileOpType(uint32 kind) external pure returns (bytes32) {
        return _profileOpType(kind);
    }

    /// @notice The ID this deployment signs, keys and bounds an op type under.
    /// @param opType The op type's portable ID.
    /// @return The deployment op type.
    function deploymentOpType(bytes32 opType) external view returns (bytes32) {
        return _deploymentOpType(opType);
    }

    /// @notice An op type's delay bounds.
    /// @param opType The op type's portable ID.
    /// @return The bounds.
    function delayBounds(bytes32 opType) external view returns (GovernanceCore.DelayBounds memory) {
        return _core.delayBounds(_deploymentOpType(opType));
    }

    /// @notice ID of the operation pending under `key`, or zero.
    /// @param key The key the operation is scheduled under.
    /// @return The operation's ID.
    function pendingId(bytes32 key) external view returns (bytes32) {
        return _core.pendingId(key);
    }

    /// @notice An operation by ID.
    /// @param opId The operation's ID.
    /// @return The operation.
    function operation(bytes32 opId) external view returns (GovernanceCore.Operation memory) {
        return _core.operation(opId);
    }

    /// @notice [EIP-712](https://eips.ethereum.org/EIPS/eip-712) domain separator committee and council approvals are signed under.
    /// @return The domain separator.
    function domainSeparator() external view returns (bytes32) {
        return _core.domainSeparator();
    }

    /// @notice The highest schedule nonce accepted and the council nonce signed next.
    /// @return lastScheduleNonce The highest schedule nonce accepted; sign a schedule above it.
    /// @return nextCouncilNonce The nonce the next council execute or veto signs.
    function governanceNonces()
        external
        view
        returns (uint256 lastScheduleNonce, uint256 nextCouncilNonce)
    {
        return _core.governanceNonces();
    }

    /// @notice Authorizes only the implementation `executeUpgrade()` is installing, then clears it.
    /// @param newImplementation The implementation `upgradeToAndCall` switches to.
    function _authorizeUpgrade(address newImplementation) internal override {
        address armedImplementation = _authorizedUpgradeImplementation;
        if (armedImplementation == address(0) || armedImplementation != newImplementation) {
            revert UpgradeNotAuthorized();
        }
        delete _authorizedUpgradeImplementation;
    }

    function _profileOpType(uint32 kind) private pure returns (bytes32) {
        _requireKnownKind(kind);
        return keccak256(abi.encode(OP_SET_PROFILE, kind));
    }

    function _deploymentOpType(bytes32 opType) private view returns (bytes32) {
        if (opType == OP_UPGRADE) {
            return GovernanceCore.deriveDeploymentOpType(opType);
        } else {
            return opType;
        }
    }

    function _committee() private view returns (GovernanceCore.Authority memory) {
        return GovernanceCore.Authority({
            isMember: _isCommitteeMember, threshold: credentialManager.committeeThreshold()
        });
    }

    function _council() private view returns (GovernanceCore.Authority memory) {
        return GovernanceCore.Authority({
            isMember: _isCouncilMember, threshold: credentialManager.securityCouncilThreshold()
        });
    }

    function _councilIfSigned(address[] calldata signers, bytes[] calldata signatures)
        private
        view
        returns (GovernanceCore.Authority memory)
    {
        bool unsigned = signers.length == 0 && signatures.length == 0;
        if (unsigned) {
            return GovernanceCore.Authority({isMember: _isCouncilMember, threshold: 0});
        } else {
            return _council();
        }
    }

    function _isCommitteeMember(address account) private view returns (bool) {
        return credentialManager.isOperator(account);
    }

    function _isCouncilMember(address account) private view returns (bool) {
        return credentialManager.isSecurityCouncil(account);
    }

    function _requireKnownKind(uint32 kind) private pure {
        if (kind >= KIND_COUNT) revert UnknownKind(kind);
    }
}

