// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {CallContextChecker} from "solady/utils/CallContextChecker.sol";
import {Registry} from "./Registry.sol";
import {RegistryStorage} from "./RegistryStorage.sol";
import {IRegistryFacet} from "./interfaces/IRegistryFacet.sol";
import {indexKey} from "./utils/IndexKey.sol";
import {Paging} from "./utils/Paging.sol";

/// @dev Maximum registered sources per asset, bounding config storage rewrites.
uint256 constant MAX_ORACLE_SOURCES = 16;

/// @dev Maximum endpoint identities per source, bounding nested config rewrites.
uint256 constant MAX_ORACLE_TLS_IDENTITIES = 8;

/// @title OracleConfigFacet
/// @notice The Registry's oracle configurations: code the Registry delegatecalls, reading and
///         writing the Registry's storage through `RegistryStorage`.
contract OracleConfigFacet is IRegistryFacet, RegistryStorage, CallContextChecker {
    /// @dev Chainlink source kind; source kinds are frozen, independent of wire enum order, and
    ///      retired values stay reserved.
    uint8 internal constant _SOURCE_KIND_CHAINLINK = 0;
    /// @dev Internal source kind.
    uint8 internal constant _SOURCE_KIND_INTERNAL = 2;
    /// @dev Continuous validity; validity kind 3 is reserved for deferred session support.
    uint8 internal constant _VALIDITY_CONTINUOUS = 1;
    /// @dev Heartbeat validity, the only kind with a grace period.
    uint8 internal constant _VALIDITY_HEARTBEAT = 2;
    /// @dev Receipt-time validity.
    uint8 internal constant _VALIDITY_RECEIPT_TIME = 4;
    /// @dev Bit `kind` is set for each supported validity kind.
    uint256 internal constant _KNOWN_VALIDITY_KINDS = (uint256(1) << _VALIDITY_CONTINUOUS)
        | (uint256(1) << _VALIDITY_HEARTBEAT) | (uint256(1) << _VALIDITY_RECEIPT_TIME);

    /// @notice Validates an oracle config operation for the Registry, applies it when
    ///         `applyChange`, and returns the key it is pending under.
    /// @param opType The Registry's oracle config op type.
    /// @param params `abi.encode(uint16 index, Registry.OracleConfig config)`.
    /// @param applyChange Whether to store the config.
    /// @return pendingKey The pending key.
    function applyOperation(bytes32 opType, bytes calldata params, bool applyChange)
        external
        onlyProxy
        returns (bytes32 pendingKey)
    {
        (uint16 index, Registry.OracleConfig memory config) =
            abi.decode(params, (uint16, Registry.OracleConfig));
        if (index >= assets.count) revert Registry.IndexOutOfBounds();
        _requireOracleConfig(config);
        if (applyChange) {
            oracleConfigs[index] = config;
            emit Registry.OracleConfigSet(index);
        }
        return indexKey(opType, index);
    }

    /// @notice The oracle configurations of a range of asset indices.
    /// @param start The start index (inclusive).
    /// @param end The end index (not inclusive).
    /// @return configs Entry i is the configuration of asset index `start + i`.
    function getOracleConfigs(uint16 start, uint16 end)
        external
        view
        onlyProxy
        returns (Registry.OracleConfig[] memory configs)
    {
        configs = new Registry.OracleConfig[](Paging.clampPage(start, end, assets.count));
        for (uint256 position; position < configs.length; ++position) {
            configs[position] = oracleConfigs[uint16(start + position)];
        }
    }

    /// @dev An empty source list unconfigures the asset. Below-quorum states, priceDecimals,
    ///      maxDeviationBps, unknown sourceKinds and identity values stay representable;
    ///      consumers validate supported semantics before using them.
    function _requireOracleConfig(Registry.OracleConfig memory config) private pure {
        uint256 sourceCount = config.sources.length;
        if (sourceCount > MAX_ORACLE_SOURCES) revert Registry.InvalidOracleConfig();
        if (sourceCount == 0) return;

        uint256 seenKinds;
        for (uint256 position; position < sourceCount; ++position) {
            Registry.OracleSourceConfig memory source = config.sources[position];
            uint8 validityKind = source.validityKind;
            uint256 kindBit = uint256(1) << source.sourceKind;
            bool knownValidity = (_KNOWN_VALIDITY_KINDS >> validityKind) & 1 == 1;
            if (
                source.sourceKind == _SOURCE_KIND_CHAINLINK
                    || source.sourceKind == _SOURCE_KIND_INTERNAL
                    || source.tlsIdentities.length > MAX_ORACLE_TLS_IDENTITIES
                    || source.unitsPerContract == 0 || !knownValidity || source.validitySecs == 0
                    || (validityKind != _VALIDITY_HEARTBEAT && source.validityGraceSecs != 0)
                    || seenKinds & kindBit != 0
            ) revert Registry.InvalidOracleConfig();
            seenKinds |= kindBit;
        }
        if (config.canonicalStalenessSecs == 0) revert Registry.InvalidOracleConfig();
    }
}

