// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {SafeCastLib} from "solady/utils/SafeCastLib.sol";

import {GovernanceCore} from "./governance/GovernanceCore.sol";
import {LibCall} from "solady/utils/LibCall.sol";
import "./OracleConfigFacet.sol" as OracleFacet;
import {WithdrawalConfigFacet} from "./WithdrawalConfigFacet.sol";
import {RepresentationConfigFacet} from "./RepresentationConfigFacet.sol";
import {Paging} from "./utils/Paging.sol";
import {IGovernanceAuthority} from "./interfaces/IGovernanceAuthority.sol";
import {IRegistryFacet} from "./interfaces/IRegistryFacet.sol";
import {indexKey} from "./utils/IndexKey.sol";
import {SeriesValidation} from "./utils/SeriesValidation.sol";
import {RegistryStorage} from "./RegistryStorage.sol";
import {TPlusUUPSUpgradeable} from "./utils/TPlusUUPSUpgradeable.sol";

/// @dev The asset index `Registry.getAssetIndex` returns for an unregistered asset.
uint32 constant ASSET_NOT_FOUND = type(uint32).max;

/**
 * @title Registry
 * @notice Central registry for managing assets and associated risk parameters across multiple chains.
 * @dev A risk council schedules every risk change on the governance core; the CredentialManager's
 *      security council vetoes or fast-tracks it.
 *
 * ## Asset Registry
 *
 * Assets are organized by a uint16 index. Each index represents a **fungible asset class** —
 * not a single token, but all representations of that asset across chains. For example:
 *
 *   - Index 0: USD — USDC on Ethereum, USDC on Solana, USDT on Ethereum, etc.
 *   - Index 1: ETH — WETH on Ethereum, WETH on Arbitrum, etc.
 *
 * Once an index is assigned, it is **permanent**. There is no mechanism to remove or reorder
 * assets; indices are append-only and monotonically increasing. This invariant is critical
 * because external systems (settlement, accounting) depend on index stability.
 *
 * **Important**: There is no on-chain enforcement that all entries under an index are truly
 * fungible with each other. It is the risk council's responsibility to ensure that only
 * fungible representations of the same asset class are registered under a given index.
 * Registering a non-fungible token (e.g. a meme coin) under the USD index would be an
 * operational error with serious consequences.
 */
contract Registry is TPlusUUPSUpgradeable, RegistryStorage {
    using GovernanceCore for GovernanceCore.State;

    /// @notice Maximum registered sources per asset, bounding config storage rewrites.
    uint256 public constant MAX_ORACLE_SOURCES = OracleFacet.MAX_ORACLE_SOURCES;

    /// @notice Maximum endpoint identities per source, bounding nested config rewrites.
    uint256 public constant MAX_ORACLE_TLS_IDENTITIES = OracleFacet.MAX_ORACLE_TLS_IDENTITIES;

    /// @notice The facet holding the oracle configurations' code, deployed with this implementation.
    address public immutable oracleConfigFacet;

    /// @notice The facet holding the withdrawal delay parameters' code, deployed with this
    ///         implementation.
    address public immutable withdrawalConfigFacet;

    /// @notice The facet holding the representation configs' code, deployed with this
    ///         implementation.
    address public immutable representationConfigFacet;

    /// @notice Op type of an asset index's risk parameters. Params `abi.encode(index, parameters)`.
    bytes32 internal constant OP_RISK_PARAMETERS = keccak256("Registry.RISK_PARAMETERS");

    /// @notice Op type of an asset index's oracle config. Params `abi.encode(index, config)`.
    bytes32 internal constant OP_ORACLE_CONFIG = keccak256("Registry.ORACLE_CONFIG");

    /// @notice Op type of the withdrawal delay parameters. Params `abi.encode(parameters)`.
    bytes32 internal constant OP_WITHDRAWAL_DELAY_PARAMETERS =
        keccak256("Registry.WITHDRAWAL_DELAY_PARAMETERS");

    /// @notice Op type of an asset entry. Params `abi.encode(data)`.
    /// @dev Execute overwrites the whole entry, caps and min weight included, even when a cap or
    ///      weight op executed while it was pending.
    bytes32 internal constant OP_ASSET_DATA = keccak256("Registry.ASSET_DATA");

    /// @notice Op type of an entry's maximum deposit. Params `abi.encode(chain, index, token, value)`.
    bytes32 internal constant OP_MAX_DEPOSITS = keccak256("Registry.MAX_DEPOSITS");

    /// @notice Op type of an entry's maximum hourly deposit. Params as `OP_MAX_DEPOSITS`.
    bytes32 internal constant OP_MAX_1HR_DEPOSITS = keccak256("Registry.MAX_1HR_DEPOSITS");

    /// @notice Op type of an entry's minimum weight. Params as `OP_MAX_DEPOSITS`.
    bytes32 internal constant OP_MIN_WEIGHT = keccak256("Registry.MIN_WEIGHT");

    /// @notice Op type of a token's representation config. Params `abi.encode(chain, token, config)`.
    bytes32 internal constant OP_REPRESENTATION_CONFIG =
        keccak256("Registry.REPRESENTATION_CONFIG");

    /// @notice Op type of a risk council rotation. Params `abi.encode(members, threshold)`.
    bytes32 internal constant OP_RISK_COUNCIL = keccak256("Registry.RISK_COUNCIL");

    /// @notice The leading op types of `initializeRiskCouncil`'s seed list that wait the risk delay.
    uint256 internal constant _DELAYED_OP_TYPE_COUNT = 5;

    /// @notice Largest funding or utilization rate cap, 11.42% an hour (about 100,000% a year),
    ///         scaled by 100,000,000 per hour.
    uint256 internal constant _RATE_CEILING = 11_420_000;

    /// @notice Signals that the maximum deposit has changed for a given asset
    event MaxDepositChanged(ChainId chain, uint16 index, uint256 previous, uint256 current);

    /// @notice Signals that the maximum hourly deposit has changed for a given asset
    event Max1HrDepositChanged(ChainId chain, uint16 index, uint256 previous, uint256 current);

    /// @notice Signals that the minimum weight has changed for a given asset
    event MinWeightChanged(ChainId chain, uint16 index, uint256 previous, uint256 current);

    /// @notice Signals that the oracle configuration for a given asset was overwritten.
    event OracleConfigSet(uint16 indexed index);

    /// @notice Signals that a token's representation config was overwritten, or removed when
    ///         `config` is all zeros.
    /// @param chain The token's chain.
    /// @param token The token's address.
    /// @param config The token's config.
    event RepresentationConfigSet(
        ChainId chain, bytes32 indexed token, RepresentationConfig config
    );

    /// @notice Signals that a risk council rotation was installed.
    /// @param members The new council members.
    /// @param threshold The new council threshold.
    event RiskCouncilSet(address[] members, uint256 threshold);

    /// @notice Defines risk-related configuration parameters for an asset.
    struct RiskParameters {
        /// @notice Percentage of asset value that can be counted as collateral (e.g., 90 = 90%).
        uint8 collateralFactor;

        /// @notice Percentage multiplier applied to liabilities for risk calculations (e.g., 90 = 90%).
        uint8 liabilityFactor;

        /// @notice Maximum allowable collateral amount for this asset. May be unenforced on-chain.
        uint256 maxCollateral;

        /// @notice Maximum total open interest allowed for derivatives positions.
        uint256 maxOpenInterest;

        /// @notice Maximum open interest allowed for spot positions.
        uint256 maxSpotOpenInterest;

        /// @notice Maximum allowed utilization ratio of available liquidity.
        uint256 maxUtilization;

        /// @notice If true, asset can only be used in isolated margin mode.
        bool isolatedOnly;

        /// @notice Utilization points where the interest rate curve slope changes, scaled in 1/100th of a basis point.
        uint256[] interestKinks;

        /// @notice Interest rates corresponding to `interestKinks`, scaled by 100,000,000 per hour.
        uint256[] kinkInterestRates;

        /// @notice USD-denominated utilization kink points, scaled in 1/100th of a basis point.
        uint256[] usdInterestKinks;

        /// @notice USD-denominated interest rates corresponding to `usdInterestKinks`, scaled by 100,000,000 per hour.
        uint256[] usdKinkInterestRates;

        /// @notice Multiplier applied to skew-based pricing adjustments, scaled in 1/100th of a basis point.
        uint256 skewModifier;

        /// @notice Skew threshold at which maximum skew adjustment applies, scaled in 1/100th of a basis point.
        uint256 skewCliff;

        /// @notice Base funding rate applied regardless of skew direction, scaled by 100,000,000 per hour.
        int256 baseFundingRate;

        /// @notice Maximum allowed premium adjustment, scaled in 1/100th of a basis point.
        uint256 premiumClamp;

        /// @notice Maximum premium impact applied during initial margin calculation, scaled in 1/100th of a basis point.
        uint256[] initialMarginClamps;

        /// @notice Multipliers applied to position size when calculating initial margin, scaled in 1/100th of a basis point.
        uint256[] initialMarginFactors;

        /// @notice Maximum absolute funding rate allowed, scaled by 100,000,000 per hour.
        uint256 maxFundingRate;

        /// @notice Maximum interest rate applied at full utilization, scaled by 100,000,000 per hour.
        uint256 maxUtilizationRate;

        /// @notice Additional safety buffer multiplier applied to risk calculations, scaled in 1/100th of a basis point.
        uint256 bufferMultiple;

        /// @notice Minimum USD-denominated balance required for sub-accounts, using 18 decimals.
        uint256 minSubAccountBalance;

        /// @notice Maximum notional (USD, 18 decimals) that auto-deleverage may close
        /// for this asset in a single pass. Zero DISABLES auto-deleverage for the
        /// asset: no ADL runs until a cap is set.
        uint256 maxAdl;
    }

    /**
     * @notice Struct for managing a list of registered assets.
     * @dev Assets are stored by index and can span multiple chains.
     *      Indices are append-only — once assigned, an asset's index never changes.
     *      See contract-level documentation for the index convention (e.g. 0 = USD).
     */
    struct AssetRegistry {
        uint256 count; // Total number of assets.
        uint256 totalEntries; // Total number of (chain, address) entries across all assets.
        mapping(uint16 => Asset) registry; // Mapping from index to asset struct.
    }

    struct WithdrawalDelayParameters {
        /// @notice Minimum delay for zero cumulative, in seconds.
        uint256 minDelay;

        /// @notice Maximum delay cap, in seconds, no greater than type(uint32).max.
        uint256 maxDelay;

        /// @notice Cumulative capacity thresholds, scaled in 1/100th of a basis point.
        uint256[] delayClamps;

        /// @notice Delay duration at each clamp, in seconds.
        uint256[] delayValues;

        /// @notice Positive floor for the potential function denominator, no greater than type(uint32).max.
        uint256 capFloor;
    }

    /// @notice Endpoint identity commitment checked by the attested oracle before trusting data.
    /// Kind 1 is keccak256(lowercase DNS hostname), authenticated using normal WebPKI. Kinds
    /// 0 (unset) and 2 (SPKI) retain their encodings but are not usable identity modes this release.
    /// The registry preserves the existing representability of identity values; consumers must
    /// fail closed on an empty list or unsupported kind. Operator config only supplies the URLs.
    struct OracleTlsIdentity {
        uint8 kind;
        bytes32 identity;
    }

    /// @notice Frozen sourceKind mapping: 1=Pyth (Hermes), 3=Hyperliquid, 4=Binance, 5=Pyth Lazer.
    /// 0=Chainlink and 2=Internal are reserved and rejected. Unknown kinds remain representable
    /// for deployments ahead of a consumer; consumers skip them and never count them in quorum.
    /// feedId: Pyth Hermes = 32-byte feed id verbatim; Hyperliquid/Binance = left-aligned,
    /// zero-padded ASCII symbol; Pyth Lazer = unsigned numeric id encoded as big-endian bytes32
    /// (right-aligned, e.g. id 1 is bytes32(uint256(1))). Lazer does not reuse Hermes feed IDs.
    struct OracleSourceConfig {
        uint8 sourceKind;
        bytes32 feedId;
        bool active;
        /// @notice At most MAX_ORACLE_TLS_IDENTITIES.
        OracleTlsIdentity[] tlsIdentities;
        /// @notice Reserved and unvalidated; all supported kinds use (0, 0).
        ChainId chainId;
        /// @notice Underlying units per quoted contract; 1 for per-unit quotes, never 0.
        uint64 unitsPerContract;
        /// @notice 1: observation age; 2: heartbeat age with grace; 4: authenticated receipt age.
        /// Kinds 0 and 3 are rejected.
        uint8 validityKind;
        /// @notice > 0.
        uint64 validitySecs;
        /// @notice Must be 0 for validityKind 1 and 4.
        uint64 validityGraceSecs;
    }

    /// @notice Oracle configuration for one asset index; empty sources means unconfigured.
    /// Each sourceKind may occur only once. Every supported source contributes an external vote.
    struct OracleConfig {
        OracleSourceConfig[] sources;
        /// @notice 0 = unset (treated as 1 off-chain); below-quorum states are allowed.
        uint8 minSources;
        /// @notice 0 is a valid precision, not unset.
        uint8 priceDecimals;
        /// @notice 0 = no bps cap; the off-chain MAD guard still applies.
        uint32 maxDeviationBps;
        /// @notice > 0; never 0 as an implicit no limit.
        uint64 canonicalStalenessSecs;
    }

    /// @notice Which provider answers a token's representation rate, and how far a read may move.
    struct RepresentationConfig {
        /// @dev The contract the rate is read from, on the token's chain and encoded like its token
        ///      address (left-aligned on EVM chains).
        bytes32 providerContract;
        /// @dev Age past which a rate stops converting.
        uint64 staleAfterSecs;
        /// @dev Largest move a read may report before the token is quarantined, in basis points.
        uint32 maxRateJumpBps;
        /// @dev 0 unset (the token converts 1:1), 1 xStocks v2, 2 Ondo shares oracle. Unknown kinds
        ///      stay representable.
        uint8 sourceKind;
    }

    /// @notice A configured token and its representation config.
    struct RepresentationEntry {
        /// @dev The token's chain.
        ChainId chain;
        /// @dev The token's address.
        bytes32 token;
        /// @dev The token's config.
        RepresentationConfig config;
    }

    /**
     * @notice Struct for identifying a chain.
     */
    struct ChainId {
        // The routing ID e.g. 0=EVM style chains.
        uint64 routingId;

        // e.g. EVM chainId.
        uint64 vmId;
    }

    /**
     * @notice Struct representing an asset across multiple chains and addresses.
     */
    struct Asset {
        // Routing ID => Chain ID => Address => AssetData.
        mapping(uint64 => mapping(uint64 => mapping(bytes32 => AssetData))) data;

        // List of all known chain IDs for this asset.
        ChainId[] chains;

        // Parallel array of asset addresses, one per chain entry.
        bytes32[] addresses;
    }

    /**
     * @notice Chain-specific metadata for an asset.
     * @dev Uses bytes32 for `assetAddress` to support non-EVM chains like Solana.
     */
    struct AssetData {
        uint16 index;
        bytes32 assetAddress;
        ChainId chainId;
        uint256 maxDeposits; // Cap on deposits (collateral cap).
        uint256 max1hrDeposits; // Cap on fungible deposits over one hour
        uint256 minWeight; // Raw weight value (not percentage)
    }

    /// @notice Reverts if the asset index is out of bounds.
    error IndexOutOfBounds();

    /// @notice Reverts if the collateral factor (CF) specified as part of risk parameters is greater than one
    error InvalidCollateralFactor();

    /// @notice Reverts if the liability factor (LF) specified as part of risk parameters is greater than one
    error InvalidLiabilityFactor();

    /// @notice Reverts if the utilization cap specified as part of risk parameters is greater than one
    error InvalidUtilizationCap();

    /// @notice Reverts if the funding rate cap specified as part of risk parameters is greater than ~1000% APR
    error InvalidMaxFundingRate();

    /// @notice Reverts if the utilization rate cap specified as part of risk parameters is greater than ~1000% APR
    error InvalidMaxUtilizationRate();

    /// @notice Reverts if the buffer multiple value is less than 1% or greater than 2%.
    error InvalidBufferMultiple();

    /// @notice Reverts if the skew modifier specified as part of risk parameters exceeds 1e6.
    error InvalidSkewModifier();

    /// @notice Reverts if the skew cliff specified as part of risk parameters exceeds 1e6.
    error InvalidSkewCliff();

    /// @notice Reverts if the absolute base funding rate specified as part of risk parameters exceeds 1e8.
    error InvalidBaseFundingRate();

    /// @notice Reverts if the premium clamp specified as part of risk parameters exceeds 1e6.
    error InvalidPremiumClamp();

    /// @notice Reverts if the interest kinks specified as part of risk parameters are not increasing from 0 to 1
    error InvalidInterestKinks();

    /// @notice Reverts if interest rates are not increasing or do not match the number of interest kinks.
    error InvalidRateInterestKinks();

    /// @notice Reverts if the USD-denominated interest kinks specified as part of risk parameters are not increasing from 0 to 1
    error InvalidUSDInterestKinks();

    /// @notice Reverts if USD interest rates are not increasing or do not match the number of USD interest kinks.
    error InvalidUSDRateInterestKinks();

    /// @notice Reverts if the size of the initial margin clamps does not match the size of the initial margin factors (specified as part of risk parameters)
    error InvalidInitialMarginsConfiguration();

    /// @notice Reverts if the initial margin clamps specified as part of risk parameters are not increasing or are above 100
    error InvalidInitialMarginsClamps();

    /// @notice Reverts if the initial margin clamps specified as part of risk parameters are not decreasing or are above 100
    error InvalidInitialMarginsFactors();

    /// @notice Reverts if the withdrawal delay clamps and values arrays have different lengths.
    error InvalidWithdrawalDelayConfiguration();

    /// @notice Reverts if the withdrawal delay clamps are not strictly increasing from zero or exceed 1e6.
    error InvalidWithdrawalDelayClamps();

    /// @notice Reverts if the withdrawal delay values are not monotonically increasing.
    error InvalidWithdrawalDelayValues();

    /// @notice Reverts if minDelay > maxDelay or maxDelay exceeds type(uint32).max.
    error InvalidWithdrawalDelayBounds();

    /// @notice Reverts if capFloor is zero or exceeds type(uint32).max.
    error InvalidWithdrawalDelayCapFloor();

    /// @notice Reverts if a withdrawal delay value is outside [minDelay, maxDelay].
    error WithdrawalDelayValueOutOfBounds();

    /// @notice Reverts if an address is zero.
    error ZeroAddress();

    /// @notice Reverts if an oracle config has too many sources or breaks a field rule documented
    /// on OracleConfig and the structs it contains.
    error InvalidOracleConfig();

    /// @notice Reverts if a representation config is malformed.
    error InvalidRepresentationConfig();

    /// @notice Reverts if a representation config names a token the Registry has not registered.
    error RepresentationTokenNotRegistered();

    /// @notice Reverts if a removal names a token with no representation config.
    error RepresentationNotConfigured();

    /// @notice Reverts if a risk council has no members, a threshold outside 1 to the member
    ///         count, or a zero or duplicate member.
    error InvalidRiskCouncil();

    /// @notice Reverts if the CredentialManager's governance domain is not this Registry's.
    error DomainMismatch();

    /// @notice Reverts if the CredentialManager is not the universe's canonical manager.
    error NotCanonicalManager();

    constructor(address _admin, uint256 _riskParameterChangeDelaySeconds) {
        oracleConfigFacet = address(new OracleFacet.OracleConfigFacet());
        withdrawalConfigFacet = address(new WithdrawalConfigFacet());
        representationConfigFacet = address(new RepresentationConfigFacet());
        _initialize(_admin, _riskParameterChangeDelaySeconds);
    }

    /**
     * @notice Initializes contract configuration for proxy deployments.
     */
    function initialize(
        address _admin,
        uint256 _riskParameterChangeDelaySeconds,
        uint64 _upgradeDelaySeconds
    ) external initializer {
        _initialize(_admin, _riskParameterChangeDelaySeconds);
        _initializeUpgradeDelay(_upgradeDelaySeconds);
    }

    function _initialize(address _admin, uint256 _riskParameterChangeDelaySeconds) internal {
        admin = _admin;
        riskParameterChangeDelaySeconds = _riskParameterChangeDelaySeconds;
    }

    function _isUpgradeAuthority(address caller) internal view override returns (bool) {
        return caller == admin;
    }

    /// @dev Creates an index only at the current count, joins an entry below it, and overwrites
    ///      an existing entry in full. Nothing checks that entries under one index are fungible.
    function _writeAssetData(AssetData memory data) internal {
        Asset storage reg = assets.registry[data.index];

        uint64 routingId = data.chainId.routingId;
        uint64 vmId = data.chainId.vmId;

        bool isNewEntry = reg.data[routingId][vmId][data.assetAddress].assetAddress == bytes32(0);
        reg.data[routingId][vmId][data.assetAddress] = data;

        if (isNewEntry) {
            if (data.index == assets.count) {
                assets.count += 1;
            }
            reg.chains.push(data.chainId);
            reg.addresses.push(data.assetAddress);
            assets.totalEntries += 1;
            // Store index + 1 so that 0 means "not found".
            assetIndexLookup[routingId][vmId][data.assetAddress] = uint256(data.index) + 1;
        }
    }

    function _requireAssetData(AssetData memory data) internal view {
        if (data.index > assets.count) revert IndexOutOfBounds();
        if (data.assetAddress == bytes32(0)) revert ZeroAddress();
    }

    function _requireAsset(uint16 index) internal view {
        if (index >= assets.count) revert IndexOutOfBounds();
    }

    function _writeEntryValue(
        bytes32 opType,
        ChainId memory chain,
        uint16 index,
        bytes32 assetAddress,
        uint256 value
    ) internal {
        AssetData storage entry =
            assets.registry[index].data[chain.routingId][chain.vmId][assetAddress];
        uint256 previous;
        if (opType == OP_MAX_DEPOSITS) {
            previous = entry.maxDeposits;
            entry.maxDeposits = value;
            emit MaxDepositChanged(chain, index, previous, value);
        } else if (opType == OP_MAX_1HR_DEPOSITS) {
            previous = entry.max1hrDeposits;
            entry.max1hrDeposits = value;
            emit Max1HrDepositChanged(chain, index, previous, value);
        } else {
            previous = entry.minWeight;
            entry.minWeight = value;
            emit MinWeightChanged(chain, index, previous, value);
        }
    }

    /**
     * @notice Retrieves asset data for a specific asset, chain, and address.
     * @param chainId the chain ID to query.
     * @param index The asset index to query.
     * @param assetAddress The asset address to query.
     * @return The corresponding AssetData struct.
     */
    function getAssetData(ChainId calldata chainId, uint16 index, bytes32 assetAddress)
        external
        view
        returns (AssetData memory)
    {
        return assets.registry[index].data[chainId.routingId][chainId.vmId][assetAddress];
    }

    /**
     * @notice Returns all registered asset data across all chains.
     * @return An array of AssetData structs.
     * @param start The start index (inclusive).
     * @param end The end index (not-inclusive).
     */
    function getAssets(uint16 start, uint16 end) external view returns (AssetData[] memory) {
        uint16 length = Paging.clampPage(start, end, assets.totalEntries);
        AssetData[] memory result = new AssetData[](length);

        uint256 r = 0;
        uint256 resIdx = 0;

        for (uint16 i = 0; i < assets.count && resIdx < length; ++i) {
            Asset storage asset = assets.registry[i];
            uint256 chainsLen = asset.chains.length;

            for (uint256 c = 0; c < chainsLen && resIdx < length; ++c) {
                if (r >= start && r < end) {
                    ChainId storage chain = asset.chains[c];
                    result[resIdx++] = asset.data[chain.routingId][chain.vmId][asset.addresses[c]];
                }

                ++r;
            }
        }

        return result;
    }

    /**
     * @notice Returns the asset index for a given chain and address.
     * @param chainId The chain ID to search.
     * @param assetAddress The asset address (as bytes32).
     * @return The index of the asset, or `ASSET_NOT_FOUND` if not found.
     */
    function getAssetIndex(ChainId calldata chainId, bytes32 assetAddress)
        external
        view
        returns (uint32)
    {
        uint256 stored = assetIndexLookup[chainId.routingId][chainId.vmId][assetAddress];
        if (stored == 0) {
            return ASSET_NOT_FOUND;
        }
        // forge-lint: disable-next-line(unsafe-typecast)
        return uint32(stored - 1);
    }

    /**
     * @notice Reverts unless `params` are valid risk parameters.
     * @param params The parameters to validate.
     */
    function validateRiskParameters(RiskParameters memory params) public pure {
        if (params.collateralFactor > 1e2) revert InvalidCollateralFactor();
        if (params.liabilityFactor > 1e2) revert InvalidLiabilityFactor();
        if (params.maxUtilization > 1e18) revert InvalidUtilizationCap();
        if (params.maxFundingRate > _RATE_CEILING) revert InvalidMaxFundingRate();
        if (params.maxUtilizationRate > _RATE_CEILING) revert InvalidMaxUtilizationRate();

        if (params.skewModifier > 1e6) revert InvalidSkewModifier();
        if (params.skewCliff > 1e6) revert InvalidSkewCliff();
        if (params.baseFundingRate > 1e8 || params.baseFundingRate < -1e8) {
            revert InvalidBaseFundingRate();
        }
        if (params.premiumClamp > 1e6) revert InvalidPremiumClamp();

        uint256 bufferMultiple = params.bufferMultiple;
        if (bufferMultiple < 1e6 || bufferMultiple > 2e6) revert InvalidBufferMultiple();

        if (!SeriesValidation.validateStartAtZeroIsAlwaysBelowOneAndIncreases(params.interestKinks))
        {
            revert InvalidInterestKinks();
        }
        if (!SeriesValidation.validateLastIsOne(params.interestKinks)) {
            revert InvalidInterestKinks();
        }
        if (!SeriesValidation.validateStartAtZeroIsAlwaysBelowOneAndIncreases(
                params.usdInterestKinks
            )) {
            revert InvalidUSDInterestKinks();
        }
        if (!SeriesValidation.validateLastIsOne(params.usdInterestKinks)) {
            revert InvalidUSDInterestKinks();
        }

        if (
            params.interestKinks.length != params.kinkInterestRates.length
                || !SeriesValidation.validateIncreases(params.kinkInterestRates)
                || params.kinkInterestRates[params.kinkInterestRates.length - 1] > 1e8
        ) {
            revert InvalidRateInterestKinks();
        }
        if (
            params.usdInterestKinks.length != params.usdKinkInterestRates.length
                || !SeriesValidation.validateIncreases(params.usdKinkInterestRates)
                || params.usdKinkInterestRates[params.usdKinkInterestRates.length - 1] > 1e8
        ) {
            revert InvalidUSDRateInterestKinks();
        }

        if (params.initialMarginClamps.length != params.initialMarginFactors.length) {
            revert InvalidInitialMarginsConfiguration();
        }
        if (!SeriesValidation.validateStartAtZeroIsAlwaysBelowOneAndIncreases(
                params.initialMarginClamps
            )) {
            revert InvalidInitialMarginsClamps();
        }
        if (!validateIMFactors(params.initialMarginFactors)) revert InvalidInitialMarginsFactors();
    }

    /**
     * @notice IM factors must always decreases and be < 1 (1_000_000)
     */
    function validateIMFactors(uint256[] memory xs) internal pure returns (bool) {
        uint256 len = xs.length;
        uint256 prev = 999_999;

        for (uint256 i; i < len; ++i) {
            uint256 cur = xs[i];
            if (cur > prev) return false;
            prev = cur;
        }

        return true;
    }

    function sumIsOne(uint256[] memory xs) internal pure returns (bool) {
        uint256 len = xs.length;
        uint256 sum;

        for (uint256 i; i < len; ++i) {
            sum += xs[i];
            if (sum > 1e6) return false;
        }

        return sum == 1e6;
    }

    /**
     * @notice Returns the full list of risk parameters for all registered assets.
     * @return An array of RiskParameters.
     * @param start The start index (inclusive).
     * @param end The end index (not inclusive).
     */
    function getRiskParameters(uint16 start, uint16 end)
        external
        view
        returns (RiskParameters[] memory)
    {
        uint16 length = Paging.clampPage(start, end, assets.count);
        RiskParameters[] memory result = new RiskParameters[](length);

        for (uint16 i = 0; i < length; ++i) {
            result[i] = riskParameters[start + i];
        }

        return result;
    }

    /**
     * @notice Returns the oracle configurations for a range of asset indices.
     * @return configs An array of OracleConfig; entry i corresponds to asset index start + i.
     * @param start The start index (inclusive).
     * @param end The end index (not inclusive).
     */
    function getOracleConfigs(uint16 start, uint16 end)
        external
        view
        returns (OracleConfig[] memory configs)
    {
        (start, end, configs);
        _forwardToFacetAsView(oracleConfigFacet);
    }

    /**
     * @notice Get the global withdrawal delay parameters.
     * @return parameters The withdrawal delay parameters.
     */
    function getWithdrawalDelayParameters()
        external
        view
        returns (WithdrawalDelayParameters memory parameters)
    {
        parameters;
        _forwardToFacetAsView(withdrawalConfigFacet);
    }

    /**
     * @notice Validates withdrawal delay parameters.
     * @param params The parameters to validate.
     */
    function validateWithdrawalDelayParameters(WithdrawalDelayParameters memory params)
        external
        view
    {
        params;
        _forwardToFacetAsView(withdrawalConfigFacet);
    }

    /**
     * @notice Returns the entries at a range of positions; a removed token keeps its position
     *         with a zero config.
     * @param start The start position (inclusive).
     * @param end The end position (not inclusive).
     * @return entries Entry i is the token at position `start + i`.
     */
    function getRepresentationConfigs(uint16 start, uint16 end)
        external
        view
        returns (RepresentationEntry[] memory entries)
    {
        (start, end, entries);
        _forwardToFacetAsView(representationConfigFacet);
    }

    /**
     * @notice Returns a token's representation config, all zeros when the token converts 1:1.
     * @param chain The token's chain.
     * @param token The token's address.
     * @return config The config.
     */
    function getRepresentationConfig(ChainId calldata chain, bytes32 token)
        external
        view
        returns (RepresentationConfig memory config)
    {
        (chain, token, config);
        _forwardToFacetAsView(representationConfigFacet);
    }

    /**
     * @notice Returns the number of positions `getRepresentationConfigs` pages through, one per
     *         token ever configured.
     * @return count The count.
     */
    function representationEntryCount() external view returns (uint256 count) {
        count;
        _forwardToFacetAsView(representationConfigFacet);
    }

    // =============================================================
    //                          GOVERNANCE
    // =============================================================

    /**
     * @notice Installs the risk council, the CredentialManager address and the universe, once; only
     *         the upgrade authority may call it.
     * @dev The delayed flows (risk parameters, oracle config, withdrawal delay parameters, asset
     *      data, representation config) start with `riskParameterChangeDelaySeconds` as both
     *      bounds; every other op type starts at zero.
     * @param manager The universe's canonical CredentialManager; not zero.
     * @param universeId The governance universe whose council signatures this Registry accepts.
     * @param members The council members.
     * @param threshold The member signatures a council action needs.
     */
    function initializeRiskCouncil(
        address manager,
        bytes32 universeId,
        address[] calldata members,
        uint256 threshold
    ) external {
        if (!_isUpgradeAuthority(msg.sender)) {
            revert NotUpgradeAuthority();
        }
        if (manager == address(0)) revert ZeroAddress();
        riskCouncilGovernance.initializeUniverse(universeId);
        IGovernanceAuthority authority = IGovernanceAuthority(manager);
        if (authority.domainSeparator() != riskCouncilGovernance.domainSeparator()) {
            revert DomainMismatch();
        }
        if (authority.managerRole() != IGovernanceAuthority.ManagerRole.Canonical) {
            revert NotCanonicalManager();
        }
        _requireRiskCouncil(members, threshold);

        credentialManager = manager;
        _setRiskCouncil(members, threshold);

        uint64 seedDelaySeconds = SafeCastLib.toUint64(riskParameterChangeDelaySeconds);
        bytes32[9] memory opTypes = [
            OP_RISK_PARAMETERS,
            OP_ORACLE_CONFIG,
            OP_WITHDRAWAL_DELAY_PARAMETERS,
            OP_ASSET_DATA,
            OP_REPRESENTATION_CONFIG,
            OP_MAX_DEPOSITS,
            OP_MAX_1HR_DEPOSITS,
            OP_MIN_WEIGHT,
            OP_RISK_COUNCIL
        ];
        for (uint256 typeIndex; typeIndex < opTypes.length; ++typeIndex) {
            uint64 delaySeconds = typeIndex < _DELAYED_OP_TYPE_COUNT ? seedDelaySeconds : 0;
            riskCouncilGovernance.initializeBounds(opTypes[typeIndex], delaySeconds, delaySeconds);
        }
    }

    /**
     * @notice Schedules an operation of any op type documented on the `OP_` constants, signed by
     *         the risk council.
     * @param opType The op type.
     * @param params The op type's parameters, ABI-encoded as its constant documents.
     * @param nonce The nonce the council signed, above the last accepted one.
     * @param deadline Last timestamp at which the signatures may be submitted.
     * @param signers Members of the op type's authority in strictly ascending order.
     * @param signatures Signatures over the schedule digest, in signer order.
     * @return opId The operation's ID.
     */
    function scheduleOperation(
        bytes32 opType,
        bytes calldata params,
        uint256 nonce,
        uint256 deadline,
        address[] calldata signers,
        bytes[] calldata signatures
    ) external returns (bytes32 opId) {
        return riskCouncilGovernance.schedule(
            opType,
            _applyOperation(opType, params, false),
            params,
            _riskCouncil(),
            nonce,
            deadline,
            signers,
            signatures
        );
    }

    /**
     * @notice Executes a scheduled operation and applies it.
     * @param opId The operation's ID.
     * @param opType The op type.
     * @param params The scheduled parameters.
     * @param councilSigners Security council members in strictly ascending order, or empty.
     * @param councilSignatures Signatures over the execute digest, or empty.
     */
    function executeOperation(
        bytes32 opId,
        bytes32 opType,
        bytes calldata params,
        address[] calldata councilSigners,
        bytes[] calldata councilSignatures
    ) external {
        riskCouncilGovernance.execute(
            opId,
            opType,
            _applyOperation(opType, params, false),
            params,
            _securityCouncil(councilSigners.length),
            councilSigners,
            councilSignatures
        );
        _applyOperation(opType, params, true);
    }

    /**
     * @notice Schedules a change of an op type's delay bounds, signed by that op type's authority.
     * @param targetOpType The op type whose bounds change.
     * @param lowerSeconds The new lower bound.
     * @param upperSeconds The new upper bound.
     * @param nonce The nonce the council signed.
     * @param deadline Last timestamp at which the signatures may be submitted.
     * @param signers Members of the target's authority in strictly ascending order.
     * @param signatures Signatures over the schedule digest, in signer order.
     * @return opId The operation's ID.
     */
    function scheduleDelayChange(
        bytes32 targetOpType,
        uint64 lowerSeconds,
        uint64 upperSeconds,
        uint256 nonce,
        uint256 deadline,
        address[] calldata signers,
        bytes[] calldata signatures
    ) external returns (bytes32 opId) {
        return riskCouncilGovernance.scheduleDelayChange(
            targetOpType,
            lowerSeconds,
            upperSeconds,
            _riskCouncil(),
            nonce,
            deadline,
            signers,
            signatures
        );
    }

    /**
     * @notice Executes a scheduled change of an op type's delay bounds.
     * @param opId The operation's ID.
     * @param targetOpType The op type whose bounds change.
     * @param lowerSeconds The scheduled lower bound.
     * @param upperSeconds The scheduled upper bound.
     * @param councilSigners Security council members in strictly ascending order, or empty.
     * @param councilSignatures Signatures over the execute digest, or empty.
     */
    function executeDelayChange(
        bytes32 opId,
        bytes32 targetOpType,
        uint64 lowerSeconds,
        uint64 upperSeconds,
        address[] calldata councilSigners,
        bytes[] calldata councilSignatures
    ) external {
        riskCouncilGovernance.executeDelayChange(
            opId,
            targetOpType,
            lowerSeconds,
            upperSeconds,
            _securityCouncil(councilSigners.length),
            councilSigners,
            councilSignatures
        );
    }

    /**
     * @notice Cancels a pending operation with security council signatures.
     * @param opId The operation's ID.
     * @param councilSigners Security council members in strictly ascending order.
     * @param councilSignatures Signatures over the veto digest, in signer order.
     */
    function vetoOperation(
        bytes32 opId,
        address[] calldata councilSigners,
        bytes[] calldata councilSignatures
    ) external {
        riskCouncilGovernance.veto(
            opId, _securityCouncil(councilSigners.length), councilSigners, councilSignatures
        );
    }

    /**
     * @notice The EIP-712 domain separator the risk council signs under.
     * @return The domain separator.
     */
    function domainSeparator() external view returns (bytes32) {
        return riskCouncilGovernance.domainSeparator();
    }

    /**
     * @notice The highest schedule nonce accepted and the council nonce signed next.
     * @return lastScheduleNonce The highest schedule nonce accepted; sign a schedule above it.
     * @return nextCouncilNonce The nonce the next security council execute or veto signs.
     */
    function governanceNonces()
        external
        view
        returns (uint256 lastScheduleNonce, uint256 nextCouncilNonce)
    {
        return riskCouncilGovernance.governanceNonces();
    }

    /**
     * @notice ID of the operation pending under `pendingKey`, or zero.
     * @param pendingKey The key one setting's operation is pending under.
     * @return The operation's ID.
     */
    function pendingId(bytes32 pendingKey) external view returns (bytes32) {
        return riskCouncilGovernance.pendingId(pendingKey);
    }

    /**
     * @notice The risk council's members and threshold.
     * @return members The council members.
     * @return threshold The member signatures a council action needs.
     */
    function getRiskCouncil() external view returns (address[] memory members, uint256 threshold) {
        return (riskCouncilMembers, riskCouncilThreshold);
    }

    /// @dev Validates `params` for `opType`, applies them when `applyChange`, returns the key.
    function _applyOperation(bytes32 opType, bytes calldata params, bool applyChange)
        private
        returns (bytes32 pendingKey)
    {
        if (opType == OP_RISK_PARAMETERS) {
            (uint16 index, RiskParameters memory parameters) =
                abi.decode(params, (uint16, RiskParameters));
            _requireAsset(index);
            validateRiskParameters(parameters);
            if (applyChange) riskParameters[index] = parameters;
            return indexKey(opType, index);
        } else if (opType == OP_ORACLE_CONFIG) {
            return _applyThroughFacet(oracleConfigFacet, opType, params, applyChange);
        } else if (opType == OP_WITHDRAWAL_DELAY_PARAMETERS) {
            return _applyThroughFacet(withdrawalConfigFacet, opType, params, applyChange);
        } else if (opType == OP_REPRESENTATION_CONFIG) {
            return _applyThroughFacet(representationConfigFacet, opType, params, applyChange);
        } else if (opType == OP_ASSET_DATA) {
            AssetData memory data = abi.decode(params, (AssetData));
            _requireAssetData(data);
            if (applyChange) _writeAssetData(data);
            return _tokenKey(opType, data.chainId, data.index, data.assetAddress);
        } else if (
            opType == OP_MAX_DEPOSITS || opType == OP_MAX_1HR_DEPOSITS || opType == OP_MIN_WEIGHT
        ) {
            (ChainId memory chain, uint16 index, bytes32 assetAddress, uint256 value) =
                abi.decode(params, (ChainId, uint16, bytes32, uint256));
            _requireAsset(index);
            if (applyChange) _writeEntryValue(opType, chain, index, assetAddress, value);
            return _tokenKey(opType, chain, index, assetAddress);
        } else if (opType == OP_RISK_COUNCIL) {
            (address[] memory members, uint256 threshold) = abi.decode(params, (address[], uint256));
            _requireRiskCouncil(members, threshold);
            if (applyChange) _setRiskCouncil(members, threshold);
            return opType;
        } else {
            revert GovernanceCore.UnknownOperationType(opType);
        }
    }

    function _applyThroughFacet(
        address facet,
        bytes32 opType,
        bytes calldata params,
        bool applyChange
    ) private returns (bytes32 pendingKey) {
        bytes memory result = LibCall.delegateCallContract(
            facet, abi.encodeCall(IRegistryFacet.applyOperation, (opType, params, applyChange))
        );
        return abi.decode(result, (bytes32));
    }

    /// @dev Returns the facet's answer to this same call, for a facet function that is `view`.
    ///      Casting `_forwardToFacet`'s pointer to `view` lets a `view` function delegatecall.
    function _forwardToFacetAsView(address facet) private view {
        function(address) internal forward = _forwardToFacet;
        function(address) internal view forwardAsView;
        assembly ("memory-safe") {
            forwardAsView := forward
        }
        forwardAsView(facet);
    }

    function _forwardToFacet(address facet) private {
        bytes memory result = LibCall.delegateCallContract(facet, msg.data);
        assembly ("memory-safe") {
            return(add(result, 0x20), mload(result))
        }
    }

    function _setRiskCouncil(address[] memory members, uint256 threshold) private {
        uint256 previousCount = riskCouncilMembers.length;
        for (uint256 memberIndex; memberIndex < previousCount; ++memberIndex) {
            delete riskCouncilMembership[riskCouncilMembers[memberIndex]];
        }
        riskCouncilMembers = members;
        for (uint256 memberIndex; memberIndex < members.length; ++memberIndex) {
            riskCouncilMembership[members[memberIndex]] = true;
        }
        riskCouncilThreshold = threshold;
        emit RiskCouncilSet(members, threshold);
    }

    function _requireRiskCouncil(address[] memory members, uint256 threshold) private pure {
        uint256 memberCount = members.length;
        if (threshold == 0 || threshold > memberCount) revert InvalidRiskCouncil();
        for (uint256 memberIndex; memberIndex < memberCount; ++memberIndex) {
            address member = members[memberIndex];
            if (member == address(0)) revert InvalidRiskCouncil();
            for (uint256 earlierIndex; earlierIndex < memberIndex; ++earlierIndex) {
                if (members[earlierIndex] == member) revert InvalidRiskCouncil();
            }
        }
    }

    function _tokenKey(bytes32 opType, ChainId memory chain, uint16 index, bytes32 assetAddress)
        private
        pure
        returns (bytes32)
    {
        return keccak256(abi.encode(opType, chain.routingId, chain.vmId, index, assetAddress));
    }

    function _riskCouncil() private view returns (GovernanceCore.Authority memory) {
        return
            GovernanceCore.Authority({
                isMember: _isRiskCouncilMember, threshold: riskCouncilThreshold
            });
    }

    /// @dev An unsigned execute reads nothing from the CredentialManager.
    function _securityCouncil(uint256 signerCount)
        private
        view
        returns (GovernanceCore.Authority memory)
    {
        uint256 threshold = signerCount == 0
            ? 0
            : IGovernanceAuthority(credentialManager).securityCouncilThreshold();
        return GovernanceCore.Authority({isMember: _isSecurityCouncil, threshold: threshold});
    }

    function _isRiskCouncilMember(address account) private view returns (bool) {
        return riskCouncilMembership[account];
    }

    function _isSecurityCouncil(address account) private view returns (bool) {
        return IGovernanceAuthority(credentialManager).isSecurityCouncil(account);
    }
}

