// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Registry} from "./Registry.sol";
import {GovernanceCore} from "./governance/GovernanceCore.sol";
import {UpgradeQueueStorage} from "./utils/UpgradeQueueStorage.sol";

/// @title RegistryStorage
/// @notice The Registry's storage layout, inherited by the Registry and by each facet it
///         delegatecalls so both read the same slots.
abstract contract RegistryStorage is UpgradeQueueStorage {
    /// @notice The upgrade authority, which also installs the risk council.
    address public admin;

    /// @notice Seeds both delay bounds of the four delayed flows when the risk council is
    ///         installed.
    uint256 public riskParameterChangeDelaySeconds;

    /// @notice Mapping of asset index to associated risk parameters.
    mapping(uint16 => Registry.RiskParameters) public riskParameters;

    /// @notice Registry of all registered assets and associated chain data.
    Registry.AssetRegistry internal assets;

    /// @notice Reverse mapping: routingId => vmId => assetAddress => asset index + 1 (0 means not found).
    mapping(uint64 => mapping(uint64 => mapping(bytes32 => uint256))) internal assetIndexLookup;

    /// @notice Withdrawal delay parameters, used to calculate delays between request and execution of withdrawals.
    Registry.WithdrawalDelayParameters internal withdrawalDelayParameters;

    /// @notice Mapping of asset index to oracle configuration.
    /// @dev `OracleSourceConfig` and its nested identities are array elements with a frozen layout.
    mapping(uint16 => Registry.OracleConfig) internal oracleConfigs;

    /// @notice The CredentialManager whose security council vetoes or fast-tracks risk changes.
    address public credentialManager;

    /// @notice The risk council's members, in installation order.
    address[] internal riskCouncilMembers;

    /// @notice Whether an address is a risk council member.
    mapping(address => bool) internal riskCouncilMembership;

    /// @notice Member signatures a risk council schedule needs.
    uint256 internal riskCouncilThreshold;

    /// @notice Operations scheduled by the risk council.
    GovernanceCore.State internal riskCouncilGovernance;

    /// @notice The keys of every token ever given a representation config, in the order first
    ///         configured.
    bytes32[] internal representationKeys;

    /// @notice Each configured token's position in `representationKeys`, plus one.
    mapping(bytes32 key => uint256 position) internal representationPositions;

    /// @notice Each configured token's entry; a removed token keeps its chain and address with a
    ///         zero config.
    mapping(bytes32 key => Registry.RepresentationEntry) internal representationEntries;
}

src/RepresentationConfigFacet.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {CallContextChecker} from "solady/utils/CallContextChecker.sol";
import {Registry} from "./Registry.sol";
import {RegistryStorage} from "./RegistryStorage.sol";
import {IRegistryFacet} from "./interfaces/IRegistryFacet.sol";
import {Paging} from "./utils/Paging.sol";

/// @title RepresentationConfigFacet
/// @notice The Registry's representation configs: code the Registry delegatecalls, reading and
///         writing which provider answers each token's representation rate through
///         `RegistryStorage`.
contract RepresentationConfigFacet is IRegistryFacet, RegistryStorage, CallContextChecker {
    /// @dev Unset source kind; a config of all zeros removes the token's config.
    uint8 internal constant _SOURCE_KIND_NONE = 0;

    /// @notice Validates a representation config operation for the Registry, applies it when
    ///         `applyChange`, and returns the key it is pending under.
    /// @param opType The Registry's representation config op type.
    /// @param params `abi.encode(Registry.ChainId chain, bytes32 token, Registry.RepresentationConfig config)`.
    /// @param applyChange Whether to store the config.
    /// @return pendingKey The pending key.
    function applyOperation(bytes32 opType, bytes calldata params, bool applyChange)
        external
        onlyProxy
        returns (bytes32 pendingKey)
    {
        (
            Registry.ChainId memory chain,
            bytes32 token,
            Registry.RepresentationConfig memory config
        ) = abi.decode(params, (Registry.ChainId, bytes32, Registry.RepresentationConfig));
        _requireRepresentationConfig(config);
        bytes32 key = _tokenKey(chain, token);
        _requireConfigurable(chain, token, key, config);
        if (applyChange) _storeEntry(key, chain, token, config);
        return keccak256(abi.encode(opType, key));
    }

    /// @notice The entries at a range of positions, removed tokens included with a zero config.
    /// @param start The start position (inclusive).
    /// @param end The end position (not inclusive).
    /// @return entries Entry i is the token at position `start + i`.
    function getRepresentationConfigs(uint16 start, uint16 end)
        external
        view
        onlyProxy
        returns (Registry.RepresentationEntry[] memory entries)
    {
        entries = new Registry
            .RepresentationEntry[](Paging.clampPage(start, end, representationKeys.length));
        for (uint256 position; position < entries.length; ++position) {
            entries[position] = representationEntries[representationKeys[start + position]];
        }
    }

    /// @notice A token's representation config, all zeros when the token converts 1:1.
    /// @param chain The token's chain.
    /// @param token The token's address.
    /// @return The config.
    function getRepresentationConfig(Registry.ChainId calldata chain, bytes32 token)
        external
        view
        onlyProxy
        returns (Registry.RepresentationConfig memory)
    {
        return representationEntries[_tokenKey(chain, token)].config;
    }

    /// @notice The number of positions, one per token ever configured.
    /// @return The count.
    function representationEntryCount() external view onlyProxy returns (uint256) {
        return representationKeys.length;
    }

    /// @dev The Registry stores any config; the clearing engine validates what it reads.
    function _requireRepresentationConfig(Registry.RepresentationConfig memory config)
        private
        pure
    {
        if (config.sourceKind == _SOURCE_KIND_NONE && !_isEmptyConfig(config)) {
            revert Registry.InvalidRepresentationConfig();
        }
    }

    function _isEmptyConfig(Registry.RepresentationConfig memory config)
        private
        pure
        returns (bool)
    {
        return config.providerContract == bytes32(0) && config.staleAfterSecs == 0
            && config.maxRateJumpBps == 0;
    }

    function _requireConfigurable(
        Registry.ChainId memory chain,
        bytes32 token,
        bytes32 key,
        Registry.RepresentationConfig memory config
    ) private view {
        if (config.sourceKind == _SOURCE_KIND_NONE) {
            if (representationEntries[key].config.sourceKind == _SOURCE_KIND_NONE) {
                revert Registry.RepresentationNotConfigured();
            }
        } else if (assetIndexLookup[chain.routingId][chain.vmId][token] == 0) {
            revert Registry.RepresentationTokenNotRegistered();
        }
    }

    function _storeEntry(
        bytes32 key,
        Registry.ChainId memory chain,
        bytes32 token,
        Registry.RepresentationConfig memory config
    ) private {
        if (representationPositions[key] == 0) {
            representationKeys.push(key);
            representationPositions[key] = representationKeys.length;
        }
        representationEntries[key] = Registry.RepresentationEntry(chain, token, config);
        emit Registry.RepresentationConfigSet(chain, token, config);
    }

    function _tokenKey(Registry.ChainId memory chain, bytes32 token)
        private
        pure
        returns (bytes32)
    {
        return keccak256(abi.encode(chain.routingId, chain.vmId, token));
    }
}

src/TplusSettlerV5.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @notice Minimal ERC20 surface used by the settler.
interface IERC20 {
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
}

/// @notice Settlement collateral mode on the deployed `DepositVault`.
/// @dev uint8: Spot=0, Margin=1. Declared at file scope so `IDepositVault.Settlement`
///      can reference it as the `mode` field type.
enum SettlementMode {
    Spot,
    Margin
}

/// @notice The `DepositVault` settlement surface this settler drives.
/// @dev Field order MUST match `DepositVault.Settlement`
///      (tokenOut, amountOut, tokenIn, amountIn, mode, user, account, nonce, validUntil).
interface IDepositVault {
    struct Settlement {
        address tokenOut;
        uint256 amountOut;
        address tokenIn;
        uint256 amountIn;
        SettlementMode mode;
        bytes32 user;
        uint64 account;
        uint64 nonce;
        uint256 validUntil;
    }

    function executeAtomicSettlement(
        Settlement calldata order,
        bytes32 settler,
        bytes calldata data,
        bytes calldata signature
    ) external;

    function settlementCounts(bytes32 user, uint64 account) external view returns (uint256);
}

/// @notice Uniswap V3 pool surface used for the flash swap.
interface IUniswapV3Pool {
    function swap(
        address recipient,
        bool zeroForOne,
        int256 amountSpecified,
        uint160 sqrtPriceLimitX96,
        bytes calldata data
    ) external returns (int256 amount0, int256 amount1);

    function token0() external view returns (address);
    function token1() external view returns (address);
}

/// @title TplusSettlerV5
/// @author T+ integration framework
/// @notice Single-transaction, Uniswap-routed atomic settlement executor.
/// @dev The design doc claimed a same-tx hedge is impossible because the vault sends `tokenOut`
///      only *after* the `onAtomicSettlement` callback — so you cannot swap `tokenOut` for
///      `tokenIn` inside the callback. That reasoning only rules out nesting the swap INSIDE the
///      settlement. Inverting the nesting works: run the whole settlement INSIDE a Uniswap V3
///      flash swap.
///
///      Flow (one tx):
///        1. `settleViaFlashSwap` calls `pool.swap` for EXACT OUTPUT of `order.amountIn` of
///           `tokenIn`. The pool sends us `tokenIn` first, then calls `uniswapV3SwapCallback`,
///           where we now OWE the pool `tokenOut`.
///        2. Inside the callback we call `vault.executeAtomicSettlement`: the vault calls back
///           `onAtomicSettlement` (we hold `tokenIn` from the flash → return `amountIn`), pulls
///           `tokenIn` from us, and sends us `order.amountOut` of `tokenOut`.
///        3. We repay the pool the owed `tokenOut` from what the vault just sent us.
///
///      Net: `tokenIn` pool→us→vault, `tokenOut` vault→us→pool. The settler needs NO pre-funded
///      working-capital buffer — the flash swap sources the input leg. The gap between the
///      CE-signed settle price and the pool price is the realized t+/Uniswap basis (kept here).
///      The vault's receipt guard covers its token pull after the executor callback. This flow
///      never re-enters that measurement window or the locked pool.
contract TplusSettlerV5 {
    /// @dev Uniswap V3 price-limit sentinels (allow the swap to consume the whole range).
    uint160 internal constant MIN_SQRT_RATIO_PLUS_ONE = 4295128739 + 1;
    uint160 internal constant MAX_SQRT_RATIO_MINUS_ONE =
        1461446703485210103287273052203988822378723970342 - 1;

    /// @notice The DepositVault this settler serves and is registered as an executor for.
    address public vault;
    /// @notice The owner (MM EOA). Gates administration and the settle entry point.
    address public owner;

    event SettlementCallback(
        address indexed vault,
        address indexed tokenOut,
        uint256 amountOut,
        address indexed tokenIn,
        uint256 amountIn
    );
    event FlashSettled(
        address indexed pool,
        address indexed tokenIn,
        address indexed tokenOut,
        uint256 amountIn,
        uint256 amountOut,
        uint256 poolOwed
    );

    error NotOwner();
    error NotVault();
    error ZeroAddress();
    error PoolTokenMismatch();
    error BadFlashCallback();
    error Unprofitable(uint256 amountOut, uint256 poolOwed);
    error InsufficientAllowance(uint256 have, uint256 need);
    error InsufficientBalance(uint256 have, uint256 need);

    modifier onlyOwner() {
        if (msg.sender != owner) revert NotOwner();
        _;
    }

    constructor(address _owner, address _vault) {
        if (_owner == address(0) || _vault == address(0)) revert ZeroAddress();
        owner = _owner;
        vault = _vault;
    }

    // --------------------------------------------------------------------- //
    // Flash-swap settlement entry point
    // --------------------------------------------------------------------- //

    /// @notice Settle `order` atomically, sourcing the input leg from `pool` via a flash swap.
    /// @param pool The Uniswap V3 pool whose two tokens are exactly {order.tokenIn, order.tokenOut}.
    /// @param order The CE-signed settlement order.
    /// @param settler The t+ settler pubkey (this contract is its registered executor).
    /// @param signature The CE admin signature over the settlement digest.
    function settleViaFlashSwap(
        address pool,
        IDepositVault.Settlement calldata order,
        bytes32 settler,
        bytes calldata signature
    ) external onlyOwner {
        address t0 = IUniswapV3Pool(pool).token0();
        address t1 = IUniswapV3Pool(pool).token1();
        bool inIsT1 = order.tokenIn == t1 && order.tokenOut == t0;
        bool inIsT0 = order.tokenIn == t0 && order.tokenOut == t1;
        if (!inIsT0 && !inIsT1) revert PoolTokenMismatch();

        // We want EXACT OUTPUT of `amountIn` of `tokenIn`. zeroForOne=true outputs token1.
        bool zeroForOne = inIsT1;
        uint160 limit = zeroForOne ? MIN_SQRT_RATIO_PLUS_ONE : MAX_SQRT_RATIO_MINUS_ONE;

        IUniswapV3Pool(pool)
            .swap(
                address(this),
                zeroForOne,
                -int256(order.amountIn), // negative = exact output
                limit,
                abi.encode(pool, order, settler, signature)
            );
    }

    /// @notice Uniswap V3 flash-swap callback: the settlement runs here.
    function uniswapV3SwapCallback(int256 amount0Delta, int256 amount1Delta, bytes calldata data)
        external
    {
        (
            address pool,
            IDepositVault.Settlement memory order,
            bytes32 settler,
            bytes memory signature
        ) = abi.decode(data, (address, IDepositVault.Settlement, bytes32, bytes));
        if (msg.sender != pool) revert BadFlashCallback();

        // The pool already sent us `order.amountIn` of `tokenIn`. Settle: the vault pulls it and
        // sends us `order.amountOut` of `tokenOut`.
        IDepositVault(vault)
            .executeAtomicSettlement(
                order, settler, abi.encode(order.tokenIn, order.amountIn), signature
            );

        // Repay the pool the owed input (the positive delta), paid in `tokenOut`.
        uint256 owed = amount0Delta > 0 ? uint256(amount0Delta) : uint256(amount1Delta);
        if (order.amountOut < owed) revert Unprofitable(order.amountOut, owed);
        require(IERC20(order.tokenOut).transfer(pool, owed), "repay-failed");

        emit FlashSettled(
            pool, order.tokenIn, order.tokenOut, order.amountIn, order.amountOut, owed
        );
    }

    // --------------------------------------------------------------------- //
    // Vault settlement callback (called by the vault, mid-settle)
    // --------------------------------------------------------------------- //

    /// @notice `IAtomicSettlementCallback` entry point. Returns the `amountIn` the vault will pull.
    /// @dev We already hold `tokenIn` (from the flash swap) and have pre-approved the vault.
    function onAtomicSettlement(address token, uint256 amount, bytes calldata data)
        external
        returns (uint256)
    {
        if (msg.sender != vault) revert NotVault();
        (address tokenIn, uint256 amountIn) = abi.decode(data, (address, uint256));

        uint256 allowed = IERC20(tokenIn).allowance(address(this), vault);
        if (allowed < amountIn) revert InsufficientAllowance(allowed, amountIn);
        uint256 bal = IERC20(tokenIn).balanceOf(address(this));
        if (bal < amountIn) revert InsufficientBalance(bal, amountIn);

        emit SettlementCallback(msg.sender, token, amount, tokenIn, amountIn);
        return amountIn;
    }

    // --------------------------------------------------------------------- //
    // Owner-gated administration
    // --------------------------------------------------------------------- //

    /// @notice Pre-approve the vault to pull `token` (max). Call once per `tokenIn`.
    function approveVault(address token) external onlyOwner {
        require(IERC20(token).approve(vault, type(uint256).max), "approve-failed");
    }

    function setVault(address _vault) external onlyOwner {
        if (_vault == address(0)) revert ZeroAddress();
        vault = _vault;
    }

    function setOwner(address _owner) external onlyOwner {
        if (_owner == address(0)) revert ZeroAddress();
        owner = _owner;
    }

    /// @notice Recover tokens (e.g. accrued basis profit) to `receiver`.
    function recoverERC20(address token, uint256 amount, address receiver) external onlyOwner {
        if (receiver == address(0)) revert ZeroAddress();
        require(IERC20(token).transfer(receiver, amount), "transfer-failed");
    }

    receive() external payable {}
}

src/VaultFacet.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {CallContextChecker} from "solady/utils/CallContextChecker.sol";
import {LibCall} from "solady/utils/LibCall.sol";
import {CredentialManager} from "./CredentialManager.sol";
import {CredentialManagerStorage} from "./CredentialManagerStorage.sol";
import {GovernanceCore} from "./governance/GovernanceCore.sol";
import {IAdminUpdateStrategy} from "./interfaces/IAdminUpdateStrategy.sol";
import {ICredentialManagerFacet} from "./interfaces/ICredentialManagerFacet.sol";
import {GovernanceSnapshot} from "./types/GovernanceSnapshot.sol";

/// @title VaultFacet
/// @notice The CredentialManager's vault registry, vault delivery and child-manager list: code the
///         CredentialManager delegatecalls, working on the CredentialManager's own storage.
contract VaultFacet is ICredentialManagerFacet, CredentialManagerStorage, CallContextChecker {
    /// @dev Routing ID of EVM chains, whose `vmId` is the chain ID.
    uint8 private constant _EVM_ROUTING_ID = 0;

    /// @notice Validates a vault, strategy or child-manager operation for the CredentialManager,
    ///         applies it when `applyChange`, and returns the key it is pending under.
    /// @param opType The op type's portable ID: `OP_ADD_VAULT`, `OP_SET_VAULT_MANAGEMENT_MODE`,
    ///        `OP_REGISTER_STRATEGY`, `OP_REPLACE_STRATEGY` or `OP_ADD_CHILD_MANAGER`.
    /// @param deploymentType The op type's deployment op type.
    /// @param params The op type's parameters, ABI-encoded as its constant documents.
    /// @param applyChange Whether to apply the change.
    /// @return pendingKey The pending key.
    function applyOperation(
        bytes32 opType,
        bytes32 deploymentType,
        bytes calldata params,
        bool applyChange
    ) external onlyProxy returns (bytes32 pendingKey) {
        if (opType == OP_ADD_VAULT) {
            (
                uint8 routingId,
                uint64 vmId,
                bytes32 vaultAddress,
                CredentialManager.ChainConfig memory config
            ) = abi.decode(params, (uint8, uint64, bytes32, CredentialManager.ChainConfig));
            if (vaultAddress == bytes32(0)) revert CredentialManager.InvalidVaultAddress();
            (bool vaultExists,) = _findVaultIndex(routingId, vmId);
            if (vaultExists) revert CredentialManager.VaultAlreadyExists();
            if (applyChange) {
                vaults.push(
                    CredentialManager.Vault({
                        routingId: routingId, vmId: vmId, vaultAddress: vaultAddress, config: config
                    })
                );
                emit CredentialManager.VaultAdded(routingId, vmId, vaultAddress, config);
            }
            return _chainKey(deploymentType, routingId, vmId);
        } else if (opType == OP_SET_VAULT_MANAGEMENT_MODE) {
            (uint8 routingId, uint64 vmId, CredentialManager.VaultManagementMode mode) =
                abi.decode(params, (uint8, uint64, CredentialManager.VaultManagementMode));
            (bytes32 vaultModeKey,) = _requireVaultRegistered(routingId, vmId);
            if (applyChange) {
                vaultManagementModes[vaultModeKey] = mode;
                emit CredentialManager.VaultManagementModeUpdated(vaultModeKey, mode);
            }
            return _chainKey(deploymentType, routingId, vmId);
        } else if (opType == OP_REGISTER_STRATEGY) {
            (uint8 routingId, uint64 vmId, address strategy, bytes32 codeHash) =
                abi.decode(params, (uint8, uint64, address, bytes32));
            _requireStrategyCode(strategy, codeHash);
            if (address(adminUpdateStrategies[routingId][vmId]) != address(0)) {
                revert CredentialManager.StrategyAlreadyExists();
            }
            if (applyChange) {
                _setAdminUpdateStrategy(routingId, vmId, strategy, codeHash);
                emit CredentialManager.AdminUpdateStrategyRegistered(routingId, vmId, strategy);
            }
            return _chainKey(deploymentType, routingId, vmId);
        } else if (opType == OP_REPLACE_STRATEGY) {
            (
                uint8 routingId,
                uint64 vmId,
                address expectedCurrent,
                address replacement,
                bytes32 codeHash
            ) = abi.decode(params, (uint8, uint64, address, address, bytes32));
            _requireStrategyCode(replacement, codeHash);
            address current = address(adminUpdateStrategies[routingId][vmId]);
            if (current == address(0)) revert CredentialManager.NoStrategy();
            if (current != expectedCurrent) revert CredentialManager.UnexpectedStrategy();
            if (applyChange) {
                _setAdminUpdateStrategy(routingId, vmId, replacement, codeHash);
                emit CredentialManager.AdminUpdateStrategyReplaced(
                    routingId, vmId, current, replacement
                );
            }
            return _chainKey(deploymentType, routingId, vmId);
        } else if (opType == OP_ADD_CHILD_MANAGER) {
            (uint8 routingId, uint64 vmId, bytes32 childManager) =
                abi.decode(params, (uint8, uint64, bytes32));
            _requireChildManagerAddable(routingId, vmId, childManager);
            if (applyChange) _addChildManager(routingId, vmId, childManager);
            return _chainKey(deploymentType, routingId, vmId);
        } else {
            revert GovernanceCore.UnknownOperationType(opType);
        }
    }

    /// @notice Delivers the committed governance snapshot to a vault through its strategy.
    /// @dev `msg.value` pays the strategy's bridge fees.
    /// @param routingId Routing namespace of the vault's chain.
    /// @param vmId Chain identifier within the routing namespace.
    function syncVaultGovernanceSnapshot(uint8 routingId, uint64 vmId) external payable onlyProxy {
        (bytes32 key, bytes32 vaultAddress) = _requireVaultRegistered(routingId, vmId);
        if (
            vaultManagementModes[key]
                == CredentialManager.VaultManagementMode.ManagedByAnotherManager
        ) {
            revert CredentialManager.VaultManagedByAnotherManager();
        }
        (GovernanceSnapshot memory snapshot, bytes32 stateHash) = _committedSnapshot();

        address strategy = address(adminUpdateStrategies[routingId][vmId]);
        if (strategy == address(0)) revert CredentialManager.NoStrategy();
        if (strategy.codehash != _adminUpdateStrategyCodeHashes[routingId][vmId]) {
            revert CredentialManager.StrategyCodeMismatch(strategy);
        }
        (bool supportsVersioning, bytes memory capability) =
            strategy.staticcall(abi.encodeCall(IAdminUpdateStrategy.enforcesSnapshotVersion, ()));
        if (
            !supportsVersioning || capability.length != 32 || abi.decode(capability, (uint256)) != 1
        ) {
            revert CredentialManager.StrategyDoesNotEnforceSnapshotVersion();
        }
        bytes memory result = LibCall.delegateCallContract(
            strategy,
            abi.encodeCall(
                IAdminUpdateStrategy.deliverGovernanceSnapshot,
                (address(bytes20(vaultAddress)), snapshot)
            )
        );
        emit CredentialManager.VaultGovernanceSnapshotSyncSubmitted(
            key, snapshot.version, stateHash, strategy, abi.decode(result, (bytes32))
        );
    }

    /// @notice The committed governance snapshot a registered vault receives on sync.
    /// @param routingId Routing namespace of the vault's chain.
    /// @param vmId Chain identifier within the routing namespace.
    /// @return snapshot The snapshot.
    /// @return stateHash The snapshot's hash.
    function getVaultGovernanceSnapshot(uint8 routingId, uint64 vmId)
        external
        view
        onlyProxy
        returns (GovernanceSnapshot memory snapshot, bytes32 stateHash)
    {
        _requireVaultRegistered(routingId, vmId);
        return _committedSnapshot();
    }

    /// @notice Registered vaults in `[start, end)`, clamped to the list.
    /// @param start The first index.
    /// @param end The index after the last.
    /// @return page The vaults.
    function getVaults(uint16 start, uint16 end)
        external
        view
        onlyProxy
        returns (CredentialManager.Vault[] memory page)
    {
        uint256 vaultCount = vaults.length;
        uint256 pageEnd = end > vaultCount ? vaultCount : end;
        if (pageEnd <= start) return page;
        page = new CredentialManager.Vault[](pageEnd - start);
        for (uint256 pageIndex; pageIndex < page.length; ++pageIndex) {
            page[pageIndex] = vaults[start + pageIndex];
        }
    }

    /// @notice A chain's vault; `vaultAddress` is zero when it has none.
    /// @param routingId Routing namespace of the chain.
    /// @param vmId Chain identifier within the routing namespace.
    /// @return vault The vault.
    function getVault(uint8 routingId, uint64 vmId)
        external
        view
        onlyProxy
        returns (CredentialManager.Vault memory vault)
    {
        (bool vaultExists, uint256 index) = _findVaultIndex(routingId, vmId);
        if (vaultExists) vault = vaults[index];
    }

    /// @notice Every child manager, in the order they were added.
    /// @return The child managers.
    function getChildManagers()
        external
        view
        onlyProxy
        returns (CredentialManager.ChildManager[] memory)
    {
        return _childManagers;
    }

    /// @notice A chain's child manager; zero when it has none.
    /// @param routingId Routing namespace of the chain.
    /// @param vmId Chain identifier within the routing namespace.
    /// @return The child manager's address, left-aligned for EVM chains.
    function getChildManager(uint8 routingId, uint64 vmId)
        external
        view
        onlyProxy
        returns (bytes32)
    {
        return _childManagerByChain[routingId][vmId];
    }

    function _requireChildManagerAddable(uint8 routingId, uint64 vmId, bytes32 childManager)
        private
        view
    {
        if (managerRole != CredentialManager.ManagerRole.Canonical) {
            revert CredentialManager.NotCanonicalManager();
        } else if (childManager == bytes32(0)) {
            revert CredentialManager.ZeroAddress();
        } else if (routingId == _EVM_ROUTING_ID && vmId == block.chainid) {
            revert CredentialManager.ChildManagerOnOwnChain(routingId, vmId);
        } else if (_childManagerByChain[routingId][vmId] != bytes32(0)) {
            revert CredentialManager.ChildManagerAlreadyAdded(routingId, vmId);
        }
    }

    function _addChildManager(uint8 routingId, uint64 vmId, bytes32 childManager) private {
        _childManagers.push(
            CredentialManager.ChildManager({
                routingId: routingId, vmId: vmId, manager: childManager
            })
        );
        _childManagerByChain[routingId][vmId] = childManager;
        emit CredentialManager.ChildManagerAdded(routingId, vmId, childManager);
    }

    function _requireStrategyCode(address strategy, bytes32 codeHash) private view {
        if (strategy.code.length == 0) revert CredentialManager.StrategyHasNoCode();
        if (strategy.codehash != codeHash) revert CredentialManager.StrategyCodeMismatch(strategy);
    }

    function _setAdminUpdateStrategy(
        uint8 routingId,
        uint64 vmId,
        address strategy,
        bytes32 codeHash
    ) private {
        adminUpdateStrategies[routingId][vmId] = IAdminUpdateStrategy(strategy);
        _adminUpdateStrategyCodeHashes[routingId][vmId] = codeHash;
    }

    function _chainKey(bytes32 opType, uint8 routingId, uint64 vmId)
        private
        pure
        returns (bytes32)
    {
        return keccak256(abi.encode(opType, routingId, vmId));
    }

    /// @notice The committed governance snapshot, the genesis a new vault is deployed with.
    /// @dev Reverts with `GovernanceSnapshotUnavailable` before the first commit.
    /// @return snapshot The snapshot.
    /// @return stateHash The snapshot's hash.
    function getGovernanceSnapshot()
        external
        view
        onlyProxy
        returns (GovernanceSnapshot memory snapshot, bytes32 stateHash)
    {
        return _committedSnapshot();
    }

    function _committedSnapshot()
        private
        view
        returns (GovernanceSnapshot memory snapshot, bytes32 stateHash)
    {
        snapshot = _governanceSnapshot;
        if (snapshot.version == 0) revert CredentialManager.GovernanceSnapshotUnavailable();
        stateHash = governanceSnapshotHash;
    }

    function _findVaultIndex(uint8 routingId, uint64 vmId)
        private
        view
        returns (bool vaultExists, uint256 index)
    {
        for (uint256 position = vaults.length; position > 0; --position) {
            CredentialManager.Vault storage vault = vaults[position - 1];
            if (vault.routingId == routingId && vault.vmId == vmId) return (true, position - 1);
        }
    }

    function _requireVaultRegistered(uint8 routingId, uint64 vmId)
        private
        view
        returns (bytes32 key, bytes32 vaultAddress)
    {
        (bool vaultExists, uint256 index) = _findVaultIndex(routingId, vmId);
        if (!vaultExists) revert CredentialManager.VaultNotFound();
        vaultAddress = vaults[index].vaultAddress;
        key = _vaultKey(routingId, vmId, vaultAddress);
    }
}

src/WithdrawalConfigFacet.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {CallContextChecker} from "solady/utils/CallContextChecker.sol";
import {Registry} from "./Registry.sol";
import {RegistryStorage} from "./RegistryStorage.sol";
import {IRegistryFacet} from "./interfaces/IRegistryFacet.sol";
import {SeriesValidation} from "./utils/SeriesValidation.sol";

/// @title WithdrawalConfigFacet
/// @notice The Registry's withdrawal delay parameters: code the Registry delegatecalls, reading
///         and writing the Registry's storage through `RegistryStorage`.
contract WithdrawalConfigFacet is IRegistryFacet, RegistryStorage, CallContextChecker {
    /// @notice Validates a withdrawal delay operation for the Registry, applies it when
    ///         `applyChange`, and returns the key it is pending under.
    /// @param opType The Registry's withdrawal delay op type.
    /// @param params `abi.encode(Registry.WithdrawalDelayParameters parameters)`.
    /// @param applyChange Whether to store the parameters.
    /// @return pendingKey The pending key.
    function applyOperation(bytes32 opType, bytes calldata params, bool applyChange)
        external
        onlyProxy
        returns (bytes32 pendingKey)
    {
        Registry.WithdrawalDelayParameters memory parameters =
            abi.decode(params, (Registry.WithdrawalDelayParameters));
        validateWithdrawalDelayParameters(parameters);
        if (applyChange) withdrawalDelayParameters = parameters;
        return opType;
    }

    /// @notice The withdrawal delay parameters.
    /// @return The parameters.
    function getWithdrawalDelayParameters()
        external
        view
        onlyProxy
        returns (Registry.WithdrawalDelayParameters memory)
    {
        return withdrawalDelayParameters;
    }

    /// @notice Reverts unless `params` are valid withdrawal delay parameters.
    /// @param params The parameters to validate.
    function validateWithdrawalDelayParameters(Registry.WithdrawalDelayParameters memory params)
        public
        pure
    {
        // The off-chain withdrawal parameters use u32 seconds. Bounding maxDelay
        // also bounds minDelay and every delayValue through the checks below.
        if (params.minDelay > params.maxDelay || params.maxDelay > type(uint32).max) {
            revert Registry.InvalidWithdrawalDelayBounds();
        }
        if (params.capFloor == 0 || params.capFloor > type(uint32).max) {
            revert Registry.InvalidWithdrawalDelayCapFloor();
        }
        uint256 valueCount = params.delayValues.length;
        if (params.delayClamps.length != valueCount) {
            revert Registry.InvalidWithdrawalDelayConfiguration();
        }
        if (!SeriesValidation.validateStartAtZeroIsAlwaysBelowOneAndIncreases(params.delayClamps)) {
            revert Registry.InvalidWithdrawalDelayClamps();
        }
        if (!SeriesValidation.validateIncreases(params.delayValues)) {
            revert Registry.InvalidWithdrawalDelayValues();
        }
        for (uint256 position; position < valueCount; ++position) {
            // Withdrawal thresholds must be distinct, as required by the Rust
            // constructor; the shared risk/IM series check permits repeated points.
            if (position > 0 && params.delayClamps[position] <= params.delayClamps[position - 1]) {
                revert Registry.InvalidWithdrawalDelayClamps();
            }
            uint256 delayValue = params.delayValues[position];
            if (delayValue < params.minDelay || delayValue > params.maxDelay) {
                revert Registry.WithdrawalDelayValueOutOfBounds();
            }
        }
    }
}

