// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {SafeTransferLib} from "solady/utils/SafeTransferLib.sol";

/// @notice Per-account deposit address. Deployed lazily via CREATE2 by the deposit forwarder
///         factory at an address derived from (account, index), so funds can land here before
///         any code exists.
/// @dev Deliberately immutable and dumb: it knows nothing about the account, the vault or the
///      token list. Its only capability is handing its whole balance of one asset to the
///      factory that deployed it; the factory decides which account gets credited from the
///      salt it derived this address from.
///
///      The constructor takes no arguments and the factory is read from `msg.sender`, so the
///      init code, and therefore the init-code hash every deposit address depends on, is the
///      same on every chain and for every factory. Changing anything in this file changes
///      every deposit address; the hash is pinned in the tests.
contract DepositForwarder {
    /// @notice Reverts when anyone other than the deploying factory calls `flush`.
    error NotFactory();

    /// @notice The factory that deployed this forwarder and the only recipient of its funds.
    address public immutable factory;

    constructor() {
        factory = msg.sender;
    }

    /// @notice Accepts native ETH sent after deployment (before deployment no code runs).
    receive() external payable {}

    /// @notice Transfers this forwarder's entire balance of `token` to the factory.
    /// @param token The ERC-20 to flush, or address(0) for native ETH.
    /// @return amount The amount transferred; zero when the balance is empty.
    function flush(address token) external returns (uint256 amount) {
        if (msg.sender != factory) revert NotFactory();
        if (token == address(0)) {
            amount = address(this).balance;
            if (amount != 0) SafeTransferLib.safeTransferETH(factory, amount);
        } else {
            amount = SafeTransferLib.balanceOf(token, address(this));
            if (amount != 0) SafeTransferLib.safeTransfer(token, factory, amount);
        }
    }
}

src/deposit-addresses/DepositForwarderFa.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {SafeTransferLib} from "solady/utils/SafeTransferLib.sol";
import {ReentrancyGuard} from "solady/utils/ReentrancyGuard.sol";
import {TPlusUUPSUpgradeable} from "../utils/TPlusUUPSUpgradeable.sol";
import {IDepositVault} from "../interfaces/IDepositVault.sol";

interface IDepositForwarder {
    function flush(address token) external returns (uint256 amount);
}

interface IWrappedNative {
    function deposit() external payable;
}

/// @notice Deploys per-account deposit forwarders and is the single depositor into the vault on
///         their behalf. Anyone can sweep a forwarder; nobody can redirect it: the credited
///         account is always the one this factory derived the forwarder's address from.
/// @dev Invariants (see tplus-services#2344):
///      - A forwarder credits only the account in its salt. The account is never taken from the
///        forwarder or the caller, only from the salt this contract recomputes.
///      - Addresses never change: the forwarder creation code is frozen below and does not depend
///        on the implementation, the vault or the chain.
///      - Zero-balance sweeps are no-ops, not reverts, and deploy nothing.
///      - The vault is fixed at initialization; it is a proxy and upgrades in place. Upgrades of
///        this contract are authorised by the vault's upgrade authority and wait this contract's
///        upgrade delay, which starts no shorter than the vault's.
///      - Nothing here reads `depositCounts`: it is attacker-incrementable and says nothing about
///        whether an account exists or has a config. Whether to attach the initial config is the
///        relayer's call, based on CE state; the CE ignores a config once one is installed.
contract DepositForwarderFactory is TPlusUUPSUpgradeable, ReentrancyGuard {
    /// @notice The initial multisig config carried by an account-creating deposit.
    struct InitialConfig {
        uint32 masterWeight;
        uint32 lowThreshold;
        uint32 mediumThreshold;
        uint32 highThreshold;
        IDepositVault.SignerConfig[] signers;
        bytes masterConfigSignature;
    }

    error ZeroAddress();
    error NotGateAdmin();
    error BetaGateBlocked(bytes32 user);
    error WrappedNativeNotSet();
    error UnexpectedEth();
    error ForwarderDeploymentFailed();
    error UpgradeDelayShorterThanVault(uint64 delaySeconds, uint64 vaultDelaySeconds);

    event ForwarderDeployed(bytes32 indexed user, uint32 indexed index, address forwarder);
    event Swept(
        bytes32 indexed user,
        uint32 indexed index,
        address indexed token,
        address forwarder,
        uint256 amount,
        bool withConfig,
        address caller
    );
    event GateAdminChanged(address indexed oldGateAdmin, address indexed newGateAdmin);
    event BetaAllowedSet(bytes32 indexed user, bool allowed);
    event BetaGateDisabled(address caller);

    /// @notice Domain separator mixed into every forwarder salt.
    bytes32 public constant SALT_DOMAIN = keccak256("tplus.deposit-forwarder.v1");

    /// @dev Creation code of `DepositForwarder`, frozen. Every deposit address depends on it, so
    ///      it is embedded as bytes rather than taken from `type(DepositForwarder).creationCode`,
    ///      whose trailing metadata changes with any edit to the source file, even a comment.
    ///      The tests check that it matches the compiled source apart from metadata.
    bytes internal constant FORWARDER_CREATION_CODE =
        hex"";

    /// @notice keccak256 of the forwarder creation code; the CREATE2 init-code hash.
    bytes32 public constant FORWARDER_INIT_CODE_HASH = keccak256(FORWARDER_CREATION_CODE);

    /// @notice The vault deposits are credited through.
    address public vault;
    /// @notice The chain's wrapped native token (WETH, WMON, ...); native deposits are wrapped.
    address public wrappedNative;
    /// @notice Maintains the beta allow-list; cannot move funds or change anything else.
    address public gateAdmin;
    /// @notice While true, only accounts in `betaAllowed` can be swept. Can only be switched off.
    bool public betaGateEnabled;
    /// @notice Beta allow-list, keyed by account id.
    mapping(bytes32 => bool) public betaAllowed;
    /// @dev The forwarder currently being flushed for native ETH; the only accepted ETH sender.
    address private _expectedEthSender;

    /// @notice Initializes a proxy.
    /// @param vault_ The vault to deposit into; its upgrade authority governs this factory.
    /// @param wrappedNative_ Wrapped native token, or zero on a chain without a native leg.
    /// @param gateAdmin_ Beta allow-list maintainer; zero if unused.
    /// @param betaGateEnabled_ Whether the beta gate starts enabled.
    /// @param upgradeDelaySeconds_ Upgrade delay; at least the vault's.
    function initialize(
        address vault_,
        address wrappedNative_,
        address gateAdmin_,
        bool betaGateEnabled_,
        uint64 upgradeDelaySeconds_
    ) external initializer {
        if (vault_ == address(0)) revert ZeroAddress();
        uint64 vaultDelay = IDepositVault(vault_).upgradeDelaySeconds();
        if (upgradeDelaySeconds_ < vaultDelay) {
            revert UpgradeDelayShorterThanVault(upgradeDelaySeconds_, vaultDelay);
        }
        _initializeUpgradeDelay(upgradeDelaySeconds_);
        vault = vault_;
        wrappedNative = wrappedNative_;
        gateAdmin = gateAdmin_;
        betaGateEnabled = betaGateEnabled_;
        emit GateAdminChanged(address(0), gateAdmin_);
    }

    // ---------------------------------------------------------------------
    // Addresses
    // ---------------------------------------------------------------------

    /// @notice The CREATE2 salt of the forwarder for (`user`, `index`).
    function saltOf(bytes32 user, uint32 index) public pure returns (bytes32) {
        return keccak256(abi.encode(SALT_DOMAIN, user, index));
    }

    /// @notice The deposit address for (`user`, `index`), whether or not it is deployed yet.
    function addressOf(bytes32 user, uint32 index) public view returns (address) {
        bytes32 hash = keccak256(
            abi.encodePacked(
                bytes1(0xff), address(this), saltOf(user, index), FORWARDER_INIT_CODE_HASH
            )
        );
        return address(uint160(uint256(hash)));
    }

    // ---------------------------------------------------------------------
    // Sweeping
    // ---------------------------------------------------------------------

    /// @notice Moves the forwarder's balance of `token` into the vault, credited to `user`.
    /// @param token An ERC-20, or address(0) for native ETH (deposited as `wrappedNative`).
    /// @return amount The amount deposited; zero when there was nothing to sweep.
    function sweep(bytes32 user, uint32 index, address token)
        external
        nonReentrant
        returns (uint256 amount)
    {
        (address forwarder, address depositToken, uint256 pulled) = _pull(user, index, token);
        if (pulled == 0) return 0;
        address vault_ = _approveVault(depositToken, pulled);
        IDepositVault(vault_).deposit(user, depositToken, pulled);
        emit Swept(user, index, depositToken, forwarder, pulled, false, msg.sender);
        return pulled;
    }

    /// @notice Like `sweep`, but deposits with `cfg` as the account's initial multisig config.
    /// @dev Allowed at any nonce. The CE verifies `cfg.masterConfigSignature` against `user` and
    ///      installs the config only if the account has none, so a stale or forged config is
    ///      ignored while the deposit itself is still credited to `user`.
    function sweepWithConfig(bytes32 user, uint32 index, address token, InitialConfig calldata cfg)
        external
        nonReentrant
        returns (uint256 amount)
    {
        (address forwarder, address depositToken, uint256 pulled) = _pull(user, index, token);
        if (pulled == 0) return 0;
        address vault_ = _approveVault(depositToken, pulled);
        IDepositVault(vault_)
            .deposit(
                user,
                depositToken,
                pulled,
                cfg.masterWeight,
                cfg.lowThreshold,
                cfg.mediumThreshold,
                cfg.highThreshold,
                cfg.signers,
                cfg.masterConfigSignature
            );
        emit Swept(user, index, depositToken, forwarder, pulled, true, msg.sender);
        return pulled;
    }

    /// @dev Deploys the forwarder if needed and moves its balance here. Returns the token to
    ///      deposit (wrapped native for ETH) and the amount that actually arrived, which for
    ///      fee-on-transfer tokens is less than what the forwarder sent.
    function _pull(bytes32 user, uint32 index, address token)
        internal
        returns (address forwarder, address depositToken, uint256 amount)
    {
        if (betaGateEnabled && !betaAllowed[user]) revert BetaGateBlocked(user);

        forwarder = addressOf(user, index);
        uint256 available =
            token == address(0) ? forwarder.balance : SafeTransferLib.balanceOf(token, forwarder);
        if (available == 0) return (forwarder, token, 0);

        if (forwarder.code.length == 0) _deployForwarder(user, index, forwarder);

        if (token == address(0)) {
            depositToken = wrappedNative;
            if (depositToken == address(0)) revert WrappedNativeNotSet();
            uint256 before = address(this).balance;
            _expectedEthSender = forwarder;
            IDepositForwarder(forwarder).flush(address(0));
            _expectedEthSender = address(0);
            amount = address(this).balance - before;
            if (amount != 0) IWrappedNative(depositToken).deposit{value: amount}();
        } else {
            depositToken = token;
            uint256 before = SafeTransferLib.balanceOf(token, address(this));
            IDepositForwarder(forwarder).flush(token);
            amount = SafeTransferLib.balanceOf(token, address(this)) - before;
        }
    }

    function _approveVault(address token, uint256 amount) internal returns (address vault_) {
        vault_ = vault;
        SafeTransferLib.safeApproveWithRetry(token, vault_, amount);
    }

    function _deployForwarder(bytes32 user, uint32 index, address expected) internal {
        bytes memory code = FORWARDER_CREATION_CODE;
        bytes32 salt = saltOf(user, index);
        address deployed;
        /// @solidity memory-safe-assembly
        assembly {
            deployed := create2(0, add(code, 0x20), mload(code), salt)
        }
        if (deployed == address(0) || deployed != expected) revert ForwarderDeploymentFailed();
        emit ForwarderDeployed(user, index, deployed);
    }

    /// @notice Accepts native ETH only from the forwarder being flushed.
    receive() external payable {
        if (msg.sender != _expectedEthSender) revert UnexpectedEth();
    }

    // ---------------------------------------------------------------------
    // Governance
    // ---------------------------------------------------------------------

    /// @dev Whoever can upgrade the vault can upgrade this factory: that authority can already
    ///      redirect everything the vault holds.
    function _isUpgradeAuthority(address caller) internal view override returns (bool) {
        IDepositVault v = IDepositVault(vault);
        return caller == v.owner() || caller == v.credentialManager();
    }

    modifier onlyUpgradeAuthority() {
        if (!_isUpgradeAuthority(msg.sender)) revert NotUpgradeAuthority();
        _;
    }

    /// @notice Sets the beta allow-list maintainer.
    function setGateAdmin(address newGateAdmin) external onlyUpgradeAuthority {
        emit GateAdminChanged(gateAdmin, newGateAdmin);
        gateAdmin = newGateAdmin;
    }

    /// @notice Switches the beta gate off for good (GA).
    function disableBetaGate() external onlyUpgradeAuthority {
        betaGateEnabled = false;
        emit BetaGateDisabled(msg.sender);
    }

    /// @notice Adds or removes accounts from the beta allow-list.
    function setBetaAllowed(bytes32[] calldata users, bool allowed) external {
        if (msg.sender != gateAdmin) revert NotGateAdmin();
        for (uint256 i = 0; i < users.length; i++) {
            betaAllowed[users[i]] = allowed;
            emit BetaAllowedSet(users[i], allowed);
        }
    }
}

src/governance/GovernanceCore.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {SignatureCheckerLib} from "solady/utils/SignatureCheckerLib.sol";

/// @notice Scheduled operations approved by k-of-n member signatures, held in the host's storage.
/// @dev A host names its op types `keccak256("<Contract>.<NAME>")`, derives the op types of
///      settings local to one deployment with `deriveDeploymentOpType`, and takes its universe
///      ID from `script/Universes.sol` (Python tooling: tpluspy).
library GovernanceCore {
    using SignatureCheckerLib for address;

    /// @notice Longest lower or upper delay bound any op type can have.
    uint64 internal constant MAX_DELAY_SECONDS = 365 days;

    /// @notice Furthest one schedule's nonce may move past the highest one accepted.
    uint256 internal constant MAX_NONCE_STEP = 1_000_000;

    /// @notice Op type of a delay-bounds change, scheduled through `scheduleDelayChange` only.
    bytes32 internal constant OP_SET_DELAY_BOUNDS = keccak256("SET_DELAY_BOUNDS");

    bytes32 private constant _DOMAIN_TYPEHASH =
        keccak256("EIP712Domain(string name,string version,bytes32 salt)");
    bytes32 private constant _NAME_HASH = keccak256("TplusGovernanceCore");
    bytes32 private constant _VERSION_HASH = keccak256("1");
    bytes32 private constant _SCHEDULE_TYPEHASH = keccak256(
        "Schedule(bytes32 opType,bytes32 key,bytes32 paramsHash,uint256 nonce,uint256 deadline)"
    );
    bytes32 private constant _EXECUTE_TYPEHASH = keccak256("Execute(bytes32 opId,uint256 nonce)");
    bytes32 private constant _VETO_TYPEHASH = keccak256("Veto(bytes32 opId,uint256 nonce)");
    bytes32 private constant _OPERATION_ID_TAG = keccak256("TplusGovernanceCore.OperationId.v1");
    bytes32 private constant _DEPLOYMENT_OP_TYPE_TAG =
        keccak256("TplusGovernanceCore.DeploymentOpType.v1");

    /// @notice Lifecycle of an operation.
    enum OperationStatus {
        /// @dev The ID was never scheduled.
        None,
        /// @dev Scheduled and neither executed nor canceled.
        Pending,
        /// @dev Executed; the host applied its params.
        Executed,
        /// @dev Superseded by a new schedule under its key, or vetoed by the council.
        Canceled
    }

    /// @notice A member set the host builds per call: its membership check and its threshold.
    struct Authority {
        /// @dev The host's check for whether an address is in the set.
        function(address) view returns (bool) isMember;
        /// @dev The number of member signatures required.
        uint256 threshold;
    }

    /// @notice The lower and upper delay bounds of an op type.
    struct DelayBounds {
        /// @dev Wait before a council-approved execute succeeds.
        uint64 lowerSeconds;
        /// @dev Wait before anyone can execute without council approval.
        uint64 upperSeconds;
        /// @dev Whether the host initialized this op type.
        bool configured;
    }

    /// @notice A scheduled operation.
    struct Operation {
        /// @dev The operation's type, which selects its delay bounds and the host entry point.
        bytes32 opType;
        /// @dev Slot holding at most one pending operation.
        bytes32 key;
        /// @dev Hash of the ABI-encoded params the host applies on execute.
        bytes32 paramsHash;
        /// @dev Earliest timestamp at which a council-approved execute succeeds.
        uint64 lowerEtaSeconds;
        /// @dev Earliest timestamp at which anyone can execute without council approval.
        uint64 upperEtaSeconds;
        /// @dev Where the operation is in its lifecycle.
        OperationStatus status;
    }

    /// @notice Governance state a host appends to its storage.
    struct State {
        /// @dev Every scheduled operation by ID, terminal records included.
        mapping(bytes32 opId => Operation) operations;
        /// @dev ID of the operation pending under each key.
        mapping(bytes32 key => bytes32 opId) pendingIds;
        /// @dev Delay bounds of each op type.
        mapping(bytes32 opType => DelayBounds) delayBoundsByOpType;
        /// @dev Highest schedule nonce accepted; a signed schedule needs a higher one.
        uint64 scheduleNonce;
        /// @dev Nonce council signatures commit to; advances on every council execute and veto.
        uint64 councilNonce;
        /// @dev Serial of the latest schedule; advances on every schedule.
        uint64 scheduleCounter;
        /// @dev Universe whose deployments accept the same schedule approvals; the domain salt.
        bytes32 universeId;
    }

    /// @notice Emitted when an operation is scheduled.
    /// @param opId The new operation's ID.
    /// @param opType The operation's type.
    /// @param key The slot the operation is pending under.
    /// @param lowerEtaSeconds Earliest timestamp at which a council-approved execute succeeds.
    /// @param upperEtaSeconds Earliest timestamp at which anyone can execute.
    /// @param parameters The full ABI-encoded params.
    /// @param signers The approving members; empty for a self-authorized schedule.
    event OperationScheduled(
        bytes32 indexed opId,
        bytes32 indexed opType,
        bytes32 indexed key,
        uint64 lowerEtaSeconds,
        uint64 upperEtaSeconds,
        bytes parameters,
        address[] signers
    );

    /// @notice Emitted when a new schedule under the same key supersedes a pending operation.
    /// @param opId The superseded operation's ID.
    /// @param opType The superseded operation's type.
    event OperationCanceled(bytes32 indexed opId, bytes32 indexed opType);

    /// @notice Emitted when the council vetoes a pending operation.
    /// @param opId The vetoed operation's ID.
    /// @param opType The vetoed operation's type.
    event OperationVetoed(bytes32 indexed opId, bytes32 indexed opType);

    /// @notice Emitted when a pending operation executes.
    /// @param opId The executed operation's ID.
    /// @param opType The executed operation's type.
    event OperationExecuted(bytes32 indexed opId, bytes32 indexed opType);

    /// @notice Emitted when an op type's delay bounds are set.
    /// @param targetOpType The op type whose bounds are set.
    /// @param lowerSeconds The new lower bound.
    /// @param upperSeconds The new upper bound.
    event DelayBoundsChanged(
        bytes32 indexed targetOpType, uint64 lowerSeconds, uint64 upperSeconds
    );

    /// @notice Thrown when an authority's threshold is zero.
    error InvalidThreshold();

    /// @notice Thrown when the signer and signature arrays differ in length.
    error SignatureCountMismatch();

    /// @notice Thrown when fewer signatures than the threshold are supplied.
    /// @param supplied The number of signers supplied.
    /// @param required The threshold.
    error InsufficientSignatures(uint256 supplied, uint256 required);

    /// @notice Thrown when signers are not in strictly ascending address order.
    error SignersNotSortedOrUnique();

    /// @notice Thrown when a signer is not in the authority's member set.
    /// @param signer The signer that is not a member.
    error NotMember(address signer);

    /// @notice Thrown when a signature does not verify for its signer over the signed digest.
    /// @param signer The signer whose signature failed.
    error InvalidSignature(address signer);

    /// @notice Thrown when a bound exceeds `MAX_DELAY_SECONDS` or the upper is below the lower.
    /// @param lowerSeconds The rejected lower bound.
    /// @param upperSeconds The rejected upper bound.
    error InvalidBounds(uint64 lowerSeconds, uint64 upperSeconds);

    /// @notice Thrown when an eta does not fit in 64 bits.
    error EtaOverflow();

    /// @notice Thrown when an operation is not pending: unknown, executed, superseded or vetoed.
    /// @param opId The operation's ID.
    error NotPending(bytes32 opId);

    /// @notice Thrown when an operation is executed through another op type's entry point.
    /// @param opId The operation's ID.
    error WrongOperationType(bytes32 opId);

    /// @notice Thrown when an operation is executed under another key.
    /// @param opId The operation's ID.
    error WrongOperationKey(bytes32 opId);

    /// @notice Thrown when execute params do not hash to the scheduled params hash.
    /// @param opId The operation's ID.
    error ParametersMismatch(bytes32 opId);

    /// @notice Thrown when an operation is executed before the eta its path requires.
    /// @param etaSeconds The eta that has not passed yet.
    error NotReady(uint64 etaSeconds);

    /// @notice Thrown when `OP_SET_DELAY_BOUNDS` is used outside the delay-change entry points.
    error ReservedOperationType();

    /// @notice Thrown when an op type has no initialized bounds or the entry point rejects it.
    /// @param opType The rejected op type.
    error UnknownOperationType(bytes32 opType);

    /// @notice Thrown when a schedule's nonce is not above the highest one accepted.
    /// @param nonce The rejected nonce.
    /// @param lastAccepted The highest nonce accepted so far.
    error StaleNonce(uint256 nonce, uint256 lastAccepted);

    /// @notice Thrown when a schedule approval is submitted after its deadline.
    /// @param deadline The approval's deadline.
    error ApprovalExpired(uint256 deadline);

    /// @notice Thrown when a schedule's nonce moves more than `MAX_NONCE_STEP` past the highest
    ///         one accepted.
    /// @param nonce The rejected nonce.
    /// @param lastAccepted The highest nonce accepted so far.
    error NonceTooFar(uint256 nonce, uint256 lastAccepted);

    /// @notice Thrown when a universe ID is zero.
    error ZeroUniverse();

    /// @notice Thrown when a host's universe ID is set a second time.
    error UniverseAlreadySet();

    /// @notice Thrown when a digest is computed before the host's universe ID is set.
    error UniverseUnset();

    /// @notice Thrown when an op type's delay bounds are initialized a second time.
    /// @param opType The already configured op type.
    error BoundsAlreadyInitialized(bytes32 opType);

    /// @notice Sets the universe whose deployments accept the same schedule approvals, once.
    /// @param self The host's governance state.
    /// @param universeId The universe, for example `keccak256("tplus-mainnet")`; not zero.
    function initializeUniverse(State storage self, bytes32 universeId) internal {
        if (universeId == bytes32(0)) revert ZeroUniverse();
        if (self.universeId != bytes32(0)) revert UniverseAlreadySet();
        self.universeId = universeId;
    }

    /// @notice Sets an op type's delay bounds immediately, for the host's initializer.
    /// @param self The host's governance state.
    /// @param opType The op type whose bounds are set.
    /// @param lowerSeconds The lower bound, at most `upperSeconds`.
    /// @param upperSeconds The upper bound, at most `MAX_DELAY_SECONDS`.
    function initializeBounds(
        State storage self,
        bytes32 opType,
        uint64 lowerSeconds,
        uint64 upperSeconds
    ) internal {
        if (opType == OP_SET_DELAY_BOUNDS) revert ReservedOperationType();
        if (self.delayBoundsByOpType[opType].configured) revert BoundsAlreadyInitialized(opType);
        _setBounds(self, opType, lowerSeconds, upperSeconds);
    }

    /// @notice Schedules an operation approved by members, superseding the one pending under `key`.
    /// @dev Rejects `OP_SET_DELAY_BOUNDS`. Nonces may skip values; accepting one invalidates every
    ///      unsubmitted approval signed with a lower or equal nonce, whatever its op type, so
    ///      submit approvals in nonce order.
    /// @param self The host's governance state.
    /// @param opType The operation's type, which selects its delay bounds.
    /// @param key Slot holding at most one pending operation, chosen by the host.
    /// @param params The ABI-encoded parameters the host applies on execute.
    /// @param governing The member set that signs schedules.
    /// @param nonce The nonce the approval was signed with, above the highest one accepted.
    /// @param deadline Last timestamp at which the approval may be submitted.
    /// @param signers Member addresses in strictly ascending order.
    /// @param signatures Signatures over the schedule digest, in signer order.
    /// @return opId The new operation's ID.
    function schedule(
        State storage self,
        bytes32 opType,
        bytes32 key,
        bytes memory params,
        Authority memory governing,
        uint256 nonce,
        uint256 deadline,
        address[] calldata signers,
        bytes[] calldata signatures
    ) internal returns (bytes32 opId) {
        return _scheduleSigned(
            self,
            opType,
            key,
            params,
            _requireBounds(self, opType),
            governing,
            nonce,
            deadline,
            signers,
            signatures
        );
    }

    /// @notice Schedules an operation the host authorized by other means, without signatures.
    /// @dev Consumes no nonce; the event carries an empty signer list.
    /// @param self The host's governance state.
    /// @param opType The operation's type, which selects its delay bounds.
    /// @param key Slot holding at most one pending operation, chosen by the host.
    /// @param params The ABI-encoded parameters the host applies on execute.
    /// @return opId The new operation's ID.
    function scheduleSelfAuthorized(
        State storage self,
        bytes32 opType,
        bytes32 key,
        bytes memory params
    ) internal returns (bytes32 opId) {
        return _store(
            self,
            opType,
            key,
            params,
            keccak256(params),
            _requireBounds(self, opType),
            new address[](0)
        );
    }

    /// @notice Executes a pending operation; the host then applies `params`.
    /// @dev Rejects `OP_SET_DELAY_BOUNDS`. Empty arrays select the unsigned path, which waits the
    ///      upper eta. Any bundle is verified against the council and needs only the lower eta.
    /// @param self The host's governance state.
    /// @param opId The operation to execute.
    /// @param expectedOpType The op type the host's entry point applies.
    /// @param expectedKey The key the host derives from `params`.
    /// @param params The raw parameters, which must hash to the scheduled params hash.
    /// @param council The council that approves early execution.
    /// @param signers Council addresses in strictly ascending order, or empty.
    /// @param signatures Signatures over the execute digest and council nonce, or empty.
    function execute(
        State storage self,
        bytes32 opId,
        bytes32 expectedOpType,
        bytes32 expectedKey,
        bytes memory params,
        Authority memory council,
        address[] calldata signers,
        bytes[] calldata signatures
    ) internal {
        if (expectedOpType == OP_SET_DELAY_BOUNDS) {
            revert ReservedOperationType();
        }
        _execute(self, opId, expectedOpType, expectedKey, params, council, signers, signatures);
    }

    /// @notice Cancels a pending operation with council approval, at any time before it executes.
    /// @param self The host's governance state.
    /// @param opId The pending operation to cancel.
    /// @param council The council that vetoes.
    /// @param signers Council addresses in strictly ascending order.
    /// @param signatures Signatures over the veto digest and council nonce, in signer order.
    function veto(
        State storage self,
        bytes32 opId,
        Authority memory council,
        address[] calldata signers,
        bytes[] calldata signatures
    ) internal {
        Operation storage op = _requirePending(self, opId);
        _consumeCouncilApproval(self, _VETO_TYPEHASH, opId, council, signers, signatures);

        op.status = OperationStatus.Canceled;
        delete self.pendingIds[op.key];
        emit OperationVetoed(opId, op.opType);
    }

    /// @notice Schedules a change of `targetOpType`'s bounds, waiting its current bounds.
    /// @param self The host's governance state.
    /// @param targetOpType The op type whose bounds change.
    /// @param lowerSeconds The new lower bound, at most `upperSeconds`.
    /// @param upperSeconds The new upper bound, at most `MAX_DELAY_SECONDS`.
    /// @param governing The member set that signs schedules.
    /// @param nonce The nonce the approval was signed with, above the highest one accepted.
    /// @param deadline Last timestamp at which the approval may be submitted.
    /// @param signers Member addresses in strictly ascending order.
    /// @param signatures Signatures over the schedule digest, in signer order.
    /// @return opId The new operation's ID.
    function scheduleDelayChange(
        State storage self,
        bytes32 targetOpType,
        uint64 lowerSeconds,
        uint64 upperSeconds,
        Authority memory governing,
        uint256 nonce,
        uint256 deadline,
        address[] calldata signers,
        bytes[] calldata signatures
    ) internal returns (bytes32 opId) {
        DelayBounds memory targetBounds = _requireBounds(self, targetOpType);
        _requireValidBounds(lowerSeconds, upperSeconds);
        return _scheduleSigned(
            self,
            OP_SET_DELAY_BOUNDS,
            delayChangeKey(targetOpType),
            abi.encode(targetOpType, lowerSeconds, upperSeconds),
            targetBounds,
            governing,
            nonce,
            deadline,
            signers,
            signatures
        );
    }

    /// @notice Executes a pending delay change and applies the new bounds.
    /// @param self The host's governance state.
    /// @param opId The delay change to execute.
    /// @param targetOpType The op type whose bounds change.
    /// @param lowerSeconds The scheduled lower bound.
    /// @param upperSeconds The scheduled upper bound.
    /// @param council The council that approves early execution.
    /// @param signers Council addresses in strictly ascending order, or empty.
    /// @param signatures Signatures over the execute digest and council nonce, or empty.
    function executeDelayChange(
        State storage self,
        bytes32 opId,
        bytes32 targetOpType,
        uint64 lowerSeconds,
        uint64 upperSeconds,
        Authority memory council,
        address[] calldata signers,
        bytes[] calldata signatures
    ) internal {
        _execute(
            self,
            opId,
            OP_SET_DELAY_BOUNDS,
            delayChangeKey(targetOpType),
            abi.encode(targetOpType, lowerSeconds, upperSeconds),
            council,
            signers,
            signatures
        );
        _setBounds(self, targetOpType, lowerSeconds, upperSeconds);
    }

    /// @notice Key under which a delay change for `targetOpType` is pending.
    /// @param targetOpType The op type whose bounds change.
    /// @return The delay change's key.
    function delayChangeKey(bytes32 targetOpType) internal pure returns (bytes32) {
        return keccak256(abi.encode(OP_SET_DELAY_BOUNDS, targetOpType));
    }

    /// @notice ID of the operation pending under `key`, or zero when none is.
    /// @param self The host's governance state.
    /// @param key The slot to look up.
    /// @return The pending operation's ID.
    function pendingId(State storage self, bytes32 key) internal view returns (bytes32) {
        return self.pendingIds[key];
    }

    /// @notice Operation stored under `opId`.
    /// @param self The host's governance state.
    /// @param opId The operation's ID.
    /// @return The operation.
    function operation(State storage self, bytes32 opId) internal view returns (Operation memory) {
        return self.operations[opId];
    }

    /// @notice Delay bounds of `opType`.
    /// @param self The host's governance state.
    /// @param opType The op type to look up.
    /// @return The op type's bounds.
    function delayBounds(State storage self, bytes32 opType)
        internal
        view
        returns (DelayBounds memory)
    {
        return self.delayBoundsByOpType[opType];
    }

    /// @notice The highest schedule nonce accepted and the council nonce signed next.
    /// @param self The host's governance state.
    /// @return lastScheduleNonce The highest schedule nonce accepted; sign a schedule above it.
    /// @return nextCouncilNonce The nonce the next council execute or veto signs.
    function governanceNonces(State storage self)
        internal
        view
        returns (uint256 lastScheduleNonce, uint256 nextCouncilNonce)
    {
        return (self.scheduleNonce, self.councilNonce);
    }

    /// @notice EIP-712 domain separator shared by every deployment in the host's universe.
    /// @param self The host's governance state.
    /// @return The domain separator.
    function domainSeparator(State storage self) internal view returns (bytes32) {
        bytes32 universeId = self.universeId;
        if (universeId == bytes32(0)) revert UniverseUnset();
        return keccak256(abi.encode(_DOMAIN_TYPEHASH, _NAME_HASH, _VERSION_HASH, universeId));
    }

    /// @notice Op type unique to the calling deployment, for settings that must not be shared
    ///         across a universe.
    /// @dev Call it at runtime; behind a proxy only a runtime call binds to the proxy's address.
    /// @param opType The op type's portable identifier.
    /// @return The op type bound to this chain and host.
    function deriveDeploymentOpType(bytes32 opType) internal view returns (bytes32) {
        return keccak256(abi.encode(_DEPLOYMENT_OP_TYPE_TAG, opType, block.chainid, address(this)));
    }

    /// @notice Digest members sign to schedule an operation.
    /// @param self The host's governance state.
    /// @param opType The operation's type.
    /// @param key The operation's key.
    /// @param paramsHash Hash of the ABI-encoded params.
    /// @param nonce The nonce the approval is signed with.
    /// @param deadline Last timestamp at which the approval may be submitted.
    /// @return The digest.
    function scheduleDigest(
        State storage self,
        bytes32 opType,
        bytes32 key,
        bytes32 paramsHash,
        uint256 nonce,
        uint256 deadline
    ) internal view returns (bytes32) {
        return _hashTypedData(
            self,
            keccak256(abi.encode(_SCHEDULE_TYPEHASH, opType, key, paramsHash, nonce, deadline))
        );
    }

    /// @notice Digest the council signs to execute an operation after its lower eta.
    /// @param self The host's governance state.
    /// @param opId The operation's ID.
    /// @param nonce The council nonce.
    /// @return The digest.
    function executeDigest(State storage self, bytes32 opId, uint256 nonce)
        internal
        view
        returns (bytes32)
    {
        return _hashTypedData(self, keccak256(abi.encode(_EXECUTE_TYPEHASH, opId, nonce)));
    }

    /// @notice Digest the council signs to veto an operation.
    /// @param self The host's governance state.
    /// @param opId The operation's ID.
    /// @param nonce The council nonce.
    /// @return The digest.
    function vetoDigest(State storage self, bytes32 opId, uint256 nonce)
        internal
        view
        returns (bytes32)
    {
        return _hashTypedData(self, keccak256(abi.encode(_VETO_TYPEHASH, opId, nonce)));
    }

    function _execute(
        State storage self,
        bytes32 opId,
        bytes32 expectedOpType,
        bytes32 expectedKey,
        bytes memory params,
        Authority memory council,
        address[] calldata signers,
        bytes[] calldata signatures
    ) private {
        Operation storage op = _requirePending(self, opId);
        if (op.opType != expectedOpType) revert WrongOperationType(opId);
        if (op.key != expectedKey) revert WrongOperationKey(opId);
        if (keccak256(params) != op.paramsHash) revert ParametersMismatch(opId);

        if (signers.length == 0 && signatures.length == 0) {
            if (block.timestamp < op.upperEtaSeconds) revert NotReady(op.upperEtaSeconds);
        } else {
            if (block.timestamp < op.lowerEtaSeconds) revert NotReady(op.lowerEtaSeconds);
            _consumeCouncilApproval(self, _EXECUTE_TYPEHASH, opId, council, signers, signatures);
        }

        op.status = OperationStatus.Executed;
        delete self.pendingIds[op.key];
        emit OperationExecuted(opId, op.opType);
    }

    function _scheduleSigned(
        State storage self,
        bytes32 opType,
        bytes32 key,
        bytes memory params,
        DelayBounds memory bounds,
        Authority memory governing,
        uint256 nonce,
        uint256 deadline,
        address[] calldata signers,
        bytes[] calldata signatures
    ) private returns (bytes32 opId) {
        if (block.timestamp > deadline) {
            revert ApprovalExpired(deadline);
        }
        uint256 lastAccepted = self.scheduleNonce;
        if (nonce <= lastAccepted) revert StaleNonce(nonce, lastAccepted);
        if (nonce - lastAccepted > MAX_NONCE_STEP) revert NonceTooFar(nonce, lastAccepted);
        bytes32 paramsHash = keccak256(params);
        _verifySignatures(
            scheduleDigest(self, opType, key, paramsHash, nonce, deadline),
            governing,
            signers,
            signatures
        );
        self.scheduleNonce = uint64(nonce);
        return _store(self, opType, key, params, paramsHash, bounds, signers);
    }

    function _store(
        State storage self,
        bytes32 opType,
        bytes32 key,
        bytes memory params,
        bytes32 paramsHash,
        DelayBounds memory bounds,
        address[] memory signers
    ) private returns (bytes32 opId) {
        bytes32 supersededId = self.pendingIds[key];
        if (supersededId != bytes32(0)) {
            Operation storage superseded = self.operations[supersededId];
            superseded.status = OperationStatus.Canceled;
            emit OperationCanceled(supersededId, superseded.opType);
        }

        uint256 serial = ++self.scheduleCounter;
        opId = keccak256(
            abi.encode(
                _OPERATION_ID_TAG, block.chainid, address(this), serial, opType, key, paramsHash
            )
        );
        uint64 lowerEtaSeconds = _computeEta(bounds.lowerSeconds);
        uint64 upperEtaSeconds = _computeEta(bounds.upperSeconds);
        self.operations[opId] = Operation({
            opType: opType,
            key: key,
            paramsHash: paramsHash,
            lowerEtaSeconds: lowerEtaSeconds,
            upperEtaSeconds: upperEtaSeconds,
            status: OperationStatus.Pending
        });
        self.pendingIds[key] = opId;
        emit OperationScheduled(
            opId, opType, key, lowerEtaSeconds, upperEtaSeconds, params, signers
        );
    }

    function _consumeCouncilApproval(
        State storage self,
        bytes32 typehash,
        bytes32 opId,
        Authority memory council,
        address[] calldata signers,
        bytes[] calldata signatures
    ) private {
        uint64 nonce = self.councilNonce;
        _verifySignatures(
            _hashTypedData(self, keccak256(abi.encode(typehash, opId, uint256(nonce)))),
            council,
            signers,
            signatures
        );
        unchecked {
            self.councilNonce = nonce + 1;
        }
    }

    function _setBounds(
        State storage self,
        bytes32 opType,
        uint64 lowerSeconds,
        uint64 upperSeconds
    ) private {
        _requireValidBounds(lowerSeconds, upperSeconds);
        self.delayBoundsByOpType[opType] =
            DelayBounds({lowerSeconds: lowerSeconds, upperSeconds: upperSeconds, configured: true});
        emit DelayBoundsChanged(opType, lowerSeconds, upperSeconds);
    }

    function _requireBounds(State storage self, bytes32 opType)
        private
        view
        returns (DelayBounds memory bounds)
    {
        if (opType == OP_SET_DELAY_BOUNDS) revert ReservedOperationType();
        bounds = self.delayBoundsByOpType[opType];
        if (!bounds.configured) revert UnknownOperationType(opType);
    }

    function _requirePending(State storage self, bytes32 opId)
        private
        view
        returns (Operation storage op)
    {
        op = self.operations[opId];
        if (op.status != OperationStatus.Pending) revert NotPending(opId);
    }

    function _requireValidBounds(uint64 lowerSeconds, uint64 upperSeconds) private pure {
        if (upperSeconds > MAX_DELAY_SECONDS || lowerSeconds > upperSeconds) {
            revert InvalidBounds(lowerSeconds, upperSeconds);
        }
    }

    function _computeEta(uint64 delaySeconds) private view returns (uint64) {
        uint256 etaSeconds = block.timestamp + delaySeconds;
        if (etaSeconds > type(uint64).max) revert EtaOverflow();
        return uint64(etaSeconds);
    }

    function _verifySignatures(
        bytes32 digest,
        Authority memory authority,
        address[] calldata signers,
        bytes[] calldata signatures
    ) private view {
        if (authority.threshold == 0) revert InvalidThreshold();
        if (signers.length != signatures.length) {
            revert SignatureCountMismatch();
        }
        if (signers.length < authority.threshold) {
            revert InsufficientSignatures(signers.length, authority.threshold);
        }

        address previousSigner = address(0);
        for (uint256 signerIndex = 0; signerIndex < signers.length; signerIndex++) {
            address signer = signers[signerIndex];
            if (signer <= previousSigner) revert SignersNotSortedOrUnique();
            previousSigner = signer;

            if (!authority.isMember(signer)) revert NotMember(signer);
            if (!signer.isValidSignatureNowCalldata(digest, signatures[signerIndex])) {
                revert InvalidSignature(signer);
            }
        }
    }

    function _hashTypedData(State storage self, bytes32 structHash) private view returns (bytes32) {
        return keccak256(abi.encodePacked("\x19\x01", domainSeparator(self), structHash));
    }
}

