// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {GovernanceSnapshot} from "../types/GovernanceSnapshot.sol";

interface IAdminUpdateStrategy {
    /// @notice Whether this strategy guarantees that stale asynchronous deliveries cannot restore
    ///         an older governance snapshot. Synchronous strategies may return true because the
    ///         destination call completes in the source transaction.
    function enforcesSnapshotVersion() external pure returns (bool);

    /// @notice Delivers a committed snapshot to a vault.
    /// @dev Delegatecalled by the CredentialManager.
    /// @param vault The destination vault.
    /// @param snapshot The committed snapshot.
    /// @return deliveryIdentifier The strategy's identifier for the delivery.
    function deliverGovernanceSnapshot(address vault, GovernanceSnapshot calldata snapshot)
        external
        payable
        returns (bytes32 deliveryIdentifier);
}

