src/interfaces/IDepositVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.4;

import {GovernanceSnapshot} from "../types/GovernanceSnapshot.sol";

import {CommitteeMember} from "../types/GovernanceSnapshot.sol";

interface IDepositVault {
    type SettlementMode is uint8;

    struct Settlement {
        address tokenOut;
        uint256 amountOut;
        address tokenIn;
        uint256 amountIn;
        SettlementMode mode;
        bytes32 user;
        uint64 account;
        uint64 nonce;
        uint256 validUntil;
    }

    struct SignedSettlement {
        Settlement settlement;
        bytes clearingEngineSignature;
    }

    struct SignerConfig {
        bytes32 key;
        uint8 keyType;
        uint8 keyPrefix;
        uint32 weight;
        uint64 expiresAtNs;
        uint64 maxSigningWindowNs;
    }

    struct Withdrawal {
        address tokenAddress;
        uint256 amount;
        uint64 nonce;
    }

    error AdministratorIndexOutOfBounds(uint256 index);
    error DecimalsCallFailed();
    error DepositorNotApproved();
    error DuplicateSnapshotMember(address account);
    error Expired();
    error FirstDepositBelowMinimum(uint256 minimum, uint256 actual);
    error InsufficientAmountFromExecutor(uint256 actual, uint256 required);
    error InsufficientCallbackReturnForSettlement(
        uint256 settlementIndex, uint256 actual, uint256 required
    );
    error InvalidInitialization();
    error InvalidNonce(uint256 expected, uint256 given);
    error InvalidSignature();
    error InvalidSnapshotCommitteeThreshold(uint256 threshold, uint256 memberCount);
    error InvalidSnapshotCouncilThreshold(uint256 threshold, uint256 councilCount);
    error InvalidSnapshotWithdrawalQuorum(uint256 quorum, uint256 keyCount);
    error MissedQuorum(uint256 provided, uint256 required);
    error NormalizationOverflow();
    error NormalizationRoundsToZero();
    error NotAdmin();
    error NotCredentialManager();
    error NotExecutor();
    error NotInitializing();
    error NotOwner();
    error NotUpgradeAuthority();
    error NotVaultConfigManager();
    error PayloadMismatch();
    error Reentrancy();
    error SettlerNotApproved();
    error TokenAmountMismatch(uint256 expected, uint256 actual);
    error TokenBalanceQueryFailed();
    error UnauthorizedCallContext();
    error UpgradeDelayChangeNotReady(uint256 validAfter);
    error UpgradeDelayChangeNotScheduled();
    error UpgradeDelayOutOfBounds(uint64 requested, uint64 minimum, uint64 maximum);
    error UpgradeFailed();
    error UpgradeNotReady(address implementation, uint256 validAfter);
    error UpgradeNotScheduled(address implementation);
    error ZeroAddress();
    error ZeroAmount();
    error ZeroImplementation();
    error ZeroSnapshotMember();
    error ZeroSnapshotVersion();
    error ZeroWithdrawalQuorum();

    event CredentialManagerChanged(address oldCredentialManager, address newCredentialManager);
    event Deposited(
        bytes32 indexed user, uint256 indexed nonce, address indexed tokenAddress, uint256 amount
    );
    event DepositedWithConfig(
        bytes32 indexed user,
        uint256 indexed nonce,
        address indexed tokenAddress,
        uint256 amount,
        uint32 masterWeight,
        uint32 lowThreshold,
        uint32 mediumThreshold,
        uint32 highThreshold,
        SignerConfig[] signers,
        bytes masterConfigSignature
    );
    event GovernanceSnapshotSet(
        uint64 indexed version, bytes32 indexed stateHash, GovernanceSnapshot snapshot
    );
    event Initialized(uint64 version);
    event MinFirstDepositAmountChanged(
        address indexed tokenAddress, uint256 previous, uint256 current
    );
    event Settled(
        bytes32 indexed user,
        uint64 indexed account,
        uint256 indexed nonce,
        address tokenOut,
        uint256 amountOut,
        address tokenIn,
        uint256 amountIn,
        SettlementMode mode,
        bytes32 settler
    );
    event UpgradeCancelled(address indexed implementation, address indexed authority);
    event UpgradeDelayChangeCancelled(uint64 newDelay, address indexed authority);
    event UpgradeDelayChangeScheduled(
        uint64 currentDelay, uint64 newDelay, uint256 validAfter, address indexed authority
    );
    event UpgradeDelayChanged(uint64 previousDelay, uint64 newDelay);
    event UpgradeScheduled(
        address indexed implementation, uint256 validAfter, address indexed authority
    );
    event Upgraded(address indexed implementation);
    event WithdrawalQuorumChanged(uint256 previous, uint256 current);
    event Withdrew(
        bytes32 indexed user, uint256 indexed nonce, address tokenAddress, uint256 amount
    );

    function MAXIMUM_UPGRADE_DELAY_SECONDS() external view returns (uint64);
    function MINIMUM_UPGRADE_DELAY_SECONDS() external view returns (uint64);
    function SETTLEMENT_TYPEHASH() external view returns (bytes32);
    function addSettlerExecutor(bytes32 settler, address executor) external;
    function administrators(uint256 index) external view returns (address);
    function approvedSettlers(uint256) external view returns (bytes32);
    function canDeposit(address) external view returns (bool);
    function cancelUpgrade(address newImplementation) external;
    function cancelUpgradeDelayChange() external;
    function credentialManager() external view returns (address);
    function deposit(
        bytes32 user,
        address tokenAddress,
        uint256 amount,
        uint32 masterWeight,
        uint32 lowThreshold,
        uint32 mediumThreshold,
        uint32 highThreshold,
        SignerConfig[] memory signers,
        bytes memory masterConfigSignature
    ) external;
    function deposit(bytes32 user, address tokenAddress, uint256 amount) external;
    function depositCounts(bytes32) external view returns (uint64);
    function domainSeparator() external view returns (bytes32);
    function executeAtomicSettlement(
        Settlement memory order,
        bytes32 settler,
        bytes memory data,
        bytes memory signature
    ) external;
    function executeSquashingSettlements(
        SignedSettlement[] memory requests,
        bytes[] memory data,
        bytes32 settler
    ) external;
    function executeUpgradeDelayChange() external;
    function getApprovedSettlers() external view returns (bytes32[] memory);
    function getGovernanceSnapshot() external view returns (GovernanceSnapshot memory);
    function initialize(
        address _owner,
        address _credentialManager,
        uint64 _upgradeDelaySeconds,
        GovernanceSnapshot memory genesis
    ) external;
    function isAdministrator(address account) external view returns (bool);
    function lastSignatureUse() external view returns (uint256);
    function minFirstDepositAmounts(address) external view returns (uint256);
    function owner() external view returns (address);
    function ownerWithdrawToken(address token, address to, uint256 amount) external;
    function pendingUpgradeDelayChange()
        external
        view
        returns (uint64 newDelaySeconds, uint256 validAfter);
    function pendingUpgradeValidAfter(address) external view returns (uint256);
    function proxiableUUID() external view returns (bytes32);
    function removeSettler(bytes32 settler) external;
    function scheduleUpgrade(address newImplementation) external;
    function scheduleUpgradeDelayChange(uint64 newDelaySeconds) external;
    function setCredentialManager(address newCredentialManager) external;
    function setDepositorStatus(address depositor, bool allowed) external;
    function setDomainSeparator(bytes32 domainSeparator) external;
    function setGovernanceSnapshot(GovernanceSnapshot memory snapshot) external;
    function setMinFirstDepositAmount(address tokenAddress, uint256 minimumAmount) external;
    function setOwner(address newOwner) external;
    function settlementCaps(address) external view returns (uint256);
    function settlementCounts(bytes32, uint64) external view returns (uint64);
    function upgradeDelaySeconds() external view returns (uint64);
    function upgradeToAndCall(address newImplementation, bytes memory data) external payable;
    function withdraw(
        Withdrawal memory withdrawal,
        bytes32 user,
        address target,
        uint256 validUntil,
        bytes32 epochHash,
        bytes[] memory signatures
    ) external;
    function withdrawalCounts(bytes32) external view returns (uint64);
    function withdrawalQuorum() external view returns (uint256);
}

src/interfaces/IGovernanceAuthority.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.4;

/// @notice What a contract governed alongside the CredentialManager reads from it: its governance
///         domain, its role and the security council.
interface IGovernanceAuthority {
    /// @notice Whether a manager is the universe's canonical manager or the manager of another L1.
    enum ManagerRole {
        /// @dev The canonical manager.
        Canonical,
        /// @dev The manager of another L1.
        Local
    }

    /// @notice EIP-712 domain separator the manager's council signatures are made under.
    /// @return The domain separator.
    function domainSeparator() external view returns (bytes32);

    /// @notice The manager's role.
    /// @return The role.
    function managerRole() external view returns (ManagerRole);

    /// @notice Whether an address is a security council member.
    /// @param account The address checked.
    /// @return Whether `account` is a security council member.
    function isSecurityCouncil(address account) external view returns (bool);

    /// @notice Council signatures an early execute or a veto needs.
    /// @return The security council threshold.
    function securityCouncilThreshold() external view returns (uint256);
}

