// SPDX-License-Identifier: MIT
pragma solidity ^0.8.4;

interface IRegistry {
    struct AssetData {
        uint16 index;
        bytes32 assetAddress;
        ChainId chainId;
        uint256 maxDeposits;
        uint256 max1hrDeposits;
        uint256 minWeight;
    }

    struct ChainId {
        uint64 routingId;
        uint64 vmId;
    }

    struct OracleConfig {
        OracleSourceConfig[] sources;
        uint8 minSources;
        uint8 priceDecimals;
        uint32 maxDeviationBps;
        uint64 canonicalStalenessSecs;
    }

    struct OracleSourceConfig {
        uint8 sourceKind;
        bytes32 feedId;
        bool active;
        OracleTlsIdentity[] tlsIdentities;
        ChainId chainId;
        uint64 unitsPerContract;
        uint8 validityKind;
        uint64 validitySecs;
        uint64 validityGraceSecs;
    }

    struct OracleTlsIdentity {
        uint8 kind;
        bytes32 identity;
    }

    struct RepresentationConfig {
        bytes32 providerContract;
        uint64 staleAfterSecs;
        uint32 maxRateJumpBps;
        uint8 sourceKind;
    }

    struct RepresentationEntry {
        ChainId chain;
        bytes32 token;
        RepresentationConfig config;
    }

    struct RiskParameters {
        uint8 collateralFactor;
        uint8 liabilityFactor;
        uint256 maxCollateral;
        uint256 maxOpenInterest;
        uint256 maxSpotOpenInterest;
        uint256 maxUtilization;
        bool isolatedOnly;
        uint256[] interestKinks;
        uint256[] kinkInterestRates;
        uint256[] usdInterestKinks;
        uint256[] usdKinkInterestRates;
        uint256 skewModifier;
        uint256 skewCliff;
        int256 baseFundingRate;
        uint256 premiumClamp;
        uint256[] initialMarginClamps;
        uint256[] initialMarginFactors;
        uint256 maxFundingRate;
        uint256 maxUtilizationRate;
        uint256 bufferMultiple;
        uint256 minSubAccountBalance;
        uint256 maxAdl;
    }

    struct WithdrawalDelayParameters {
        uint256 minDelay;
        uint256 maxDelay;
        uint256[] delayClamps;
        uint256[] delayValues;
        uint256 capFloor;
    }

    error ApprovalExpired(uint256 deadline);
    error BoundsAlreadyInitialized(bytes32 opType);
    error DomainMismatch();
    error EtaOverflow();
    error IndexOutOfBounds();
    error InsufficientSignatures(uint256 supplied, uint256 required);
    error InvalidBaseFundingRate();
    error InvalidBounds(uint64 lowerSeconds, uint64 upperSeconds);
    error InvalidBufferMultiple();
    error InvalidCollateralFactor();
    error InvalidInitialMarginsClamps();
    error InvalidInitialMarginsConfiguration();
    error InvalidInitialMarginsFactors();
    error InvalidInitialization();
    error InvalidInterestKinks();
    error InvalidLiabilityFactor();
    error InvalidMaxFundingRate();
    error InvalidMaxUtilizationRate();
    error InvalidOracleConfig();
    error InvalidPremiumClamp();
    error InvalidRateInterestKinks();
    error InvalidRepresentationConfig();
    error InvalidRiskCouncil();
    error InvalidSignature(address signer);
    error InvalidSkewCliff();
    error InvalidSkewModifier();
    error InvalidThreshold();
    error InvalidUSDInterestKinks();
    error InvalidUSDRateInterestKinks();
    error InvalidUtilizationCap();
    error InvalidWithdrawalDelayBounds();
    error InvalidWithdrawalDelayCapFloor();
    error InvalidWithdrawalDelayClamps();
    error InvalidWithdrawalDelayConfiguration();
    error InvalidWithdrawalDelayValues();
    error NonceTooFar(uint256 nonce, uint256 lastAccepted);
    error NotCanonicalManager();
    error NotInitializing();
    error NotMember(address signer);
    error NotPending(bytes32 opId);
    error NotReady(uint64 etaSeconds);
    error NotUpgradeAuthority();
    error ParametersMismatch(bytes32 opId);
    error RepresentationNotConfigured();
    error RepresentationTokenNotRegistered();
    error ReservedOperationType();
    error SignatureCountMismatch();
    error SignersNotSortedOrUnique();
    error StaleNonce(uint256 nonce, uint256 lastAccepted);
    error UnauthorizedCallContext();
    error UniverseAlreadySet();
    error UniverseUnset();
    error UnknownOperationType(bytes32 opType);
    error UpgradeDelayChangeNotReady(uint256 validAfter);
    error UpgradeDelayChangeNotScheduled();
    error UpgradeDelayOutOfBounds(uint64 requested, uint64 minimum, uint64 maximum);
    error UpgradeFailed();
    error UpgradeNotReady(address implementation, uint256 validAfter);
    error UpgradeNotScheduled(address implementation);
    error WithdrawalDelayValueOutOfBounds();
    error WrongOperationKey(bytes32 opId);
    error WrongOperationType(bytes32 opId);
    error ZeroAddress();
    error ZeroImplementation();
    error ZeroUniverse();

    event DelayBoundsChanged(
        bytes32 indexed targetOpType, uint64 lowerSeconds, uint64 upperSeconds
    );
    event Initialized(uint64 version);
    event Max1HrDepositChanged(ChainId chain, uint16 index, uint256 previous, uint256 current);
    event MaxDepositChanged(ChainId chain, uint16 index, uint256 previous, uint256 current);
    event MinWeightChanged(ChainId chain, uint16 index, uint256 previous, uint256 current);
    event OperationCanceled(bytes32 indexed opId, bytes32 indexed opType);
    event OperationExecuted(bytes32 indexed opId, bytes32 indexed opType);
    event OperationScheduled(
        bytes32 indexed opId,
        bytes32 indexed opType,
        bytes32 indexed key,
        uint64 lowerEtaSeconds,
        uint64 upperEtaSeconds,
        bytes parameters,
        address[] signers
    );
    event OperationVetoed(bytes32 indexed opId, bytes32 indexed opType);
    event OracleConfigSet(uint16 indexed index);
    event RepresentationConfigSet(
        ChainId chain, bytes32 indexed token, RepresentationConfig config
    );
    event RiskCouncilSet(address[] members, uint256 threshold);
    event UpgradeCancelled(address indexed implementation, address indexed authority);
    event UpgradeDelayChangeCancelled(uint64 newDelay, address indexed authority);
    event UpgradeDelayChangeScheduled(
        uint64 currentDelay, uint64 newDelay, uint256 validAfter, address indexed authority
    );
    event UpgradeDelayChanged(uint64 previousDelay, uint64 newDelay);
    event UpgradeScheduled(
        address indexed implementation, uint256 validAfter, address indexed authority
    );
    event Upgraded(address indexed implementation);

    function MAXIMUM_UPGRADE_DELAY_SECONDS() external view returns (uint64);
    function MAX_ORACLE_SOURCES() external view returns (uint256);
    function MAX_ORACLE_TLS_IDENTITIES() external view returns (uint256);
    function MINIMUM_UPGRADE_DELAY_SECONDS() external view returns (uint64);
    function admin() external view returns (address);
    function cancelUpgrade(address newImplementation) external;
    function cancelUpgradeDelayChange() external;
    function credentialManager() external view returns (address);
    function domainSeparator() external view returns (bytes32);
    function executeDelayChange(
        bytes32 opId,
        bytes32 targetOpType,
        uint64 lowerSeconds,
        uint64 upperSeconds,
        address[] memory councilSigners,
        bytes[] memory councilSignatures
    ) external;
    function executeOperation(
        bytes32 opId,
        bytes32 opType,
        bytes memory params,
        address[] memory councilSigners,
        bytes[] memory councilSignatures
    ) external;
    function executeUpgradeDelayChange() external;
    function getAssetData(ChainId memory chainId, uint16 index, bytes32 assetAddress)
        external
        view
        returns (AssetData memory);
    function getAssetIndex(ChainId memory chainId, bytes32 assetAddress)
        external
        view
        returns (uint32);
    function getAssets(uint16 start, uint16 end) external view returns (AssetData[] memory);
    function getOracleConfigs(uint16 start, uint16 end)
        external
        view
        returns (OracleConfig[] memory configs);
    function getRepresentationConfig(ChainId memory chain, bytes32 token)
        external
        view
        returns (RepresentationConfig memory config);
    function getRepresentationConfigs(uint16 start, uint16 end)
        external
        view
        returns (RepresentationEntry[] memory entries);
    function getRiskCouncil() external view returns (address[] memory members, uint256 threshold);
    function getRiskParameters(uint16 start, uint16 end)
        external
        view
        returns (RiskParameters[] memory);
    function getWithdrawalDelayParameters()
        external
        view
        returns (WithdrawalDelayParameters memory parameters);
    function governanceNonces()
        external
        view
        returns (uint256 lastScheduleNonce, uint256 nextCouncilNonce);
    function initialize(
        address _admin,
        uint256 _riskParameterChangeDelaySeconds,
        uint64 _upgradeDelaySeconds
    ) external;
    function initializeRiskCouncil(
        address manager,
        bytes32 universeId,
        address[] memory members,
        uint256 threshold
    ) external;
    function oracleConfigFacet() external view returns (address);
    function pendingId(bytes32 pendingKey) external view returns (bytes32);
    function pendingUpgradeDelayChange()
        external
        view
        returns (uint64 newDelaySeconds, uint256 validAfter);
    function pendingUpgradeValidAfter(address) external view returns (uint256);
    function proxiableUUID() external view returns (bytes32);
    function representationConfigFacet() external view returns (address);
    function representationEntryCount() external view returns (uint256 count);
    function riskParameterChangeDelaySeconds() external view returns (uint256);
    function riskParameters(uint16)
        external
        view
        returns (
            uint8 collateralFactor,
            uint8 liabilityFactor,
            uint256 maxCollateral,
            uint256 maxOpenInterest,
            uint256 maxSpotOpenInterest,
            uint256 maxUtilization,
            bool isolatedOnly,
            uint256 skewModifier,
            uint256 skewCliff,
            int256 baseFundingRate,
            uint256 premiumClamp,
            uint256 maxFundingRate,
            uint256 maxUtilizationRate,
            uint256 bufferMultiple,
            uint256 minSubAccountBalance,
            uint256 maxAdl
        );
    function scheduleDelayChange(
        bytes32 targetOpType,
        uint64 lowerSeconds,
        uint64 upperSeconds,
        uint256 nonce,
        uint256 deadline,
        address[] memory signers,
        bytes[] memory signatures
    ) external returns (bytes32 opId);
    function scheduleOperation(
        bytes32 opType,
        bytes memory params,
        uint256 nonce,
        uint256 deadline,
        address[] memory signers,
        bytes[] memory signatures
    ) external returns (bytes32 opId);
    function scheduleUpgrade(address newImplementation) external;
    function scheduleUpgradeDelayChange(uint64 newDelaySeconds) external;
    function upgradeDelaySeconds() external view returns (uint64);
    function upgradeToAndCall(address newImplementation, bytes memory data) external payable;
    function validateRiskParameters(RiskParameters memory params) external pure;
    function validateWithdrawalDelayParameters(WithdrawalDelayParameters memory params)
        external
        view;
    function vetoOperation(
        bytes32 opId,
        address[] memory councilSigners,
        bytes[] memory councilSignatures
    ) external;
    function withdrawalConfigFacet() external view returns (address);
}

src/interfaces/IRegistryFacet.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/// @notice The entry the Registry delegatecalls to validate and apply a facet's operation.
interface IRegistryFacet {
    /// @notice Validates an operation, applies it when `applyChange`, and returns the key it is
    ///         pending under.
    /// @param opType The op type.
    /// @param params The op type's parameters.
    /// @param applyChange Whether to apply the change.
    /// @return pendingKey The pending key.
    function applyOperation(bytes32 opType, bytes calldata params, bool applyChange)
        external
        returns (bytes32 pendingKey);
}

