// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {LibClone} from "solady/utils/LibClone.sol";

/// @notice Deploys minimal ERC1967 proxies backed by Solady's LibClone.
contract ERC1967ProxyFactory {
    /// @notice Reverts when proxy initialization fails.
    error InitializationFailed();

    /// @notice Reverts when a deterministic salt does not start with the caller's
    ///         20-byte address. This is salt-squatting / front-running protection:
    ///         it stops a third party from re-using a salt that was mined (and made
    ///         public by deploying on one chain) to occupy the same address on
    ///         another chain with attacker-controlled initialization. A salt whose
    ///         first 20 bytes are zero is permitted for permissionless deploys.
    error SaltDoesNotStartWithCaller();

    /// @notice Emitted when a new proxy is deployed.
    event ProxyDeployed(address indexed proxy, address indexed implementation);

    /// @notice Deploys an ERC1967 proxy and optionally runs initialization calldata.
    function deployProxy(address implementation, bytes calldata initializationData)
        external
        payable
        returns (address proxy)
    {
        proxy = LibClone.deployERC1967(msg.value, implementation);
        _initialize(proxy, initializationData);
        emit ProxyDeployed(proxy, implementation);
    }

    /// @notice Deploys an ERC1967 proxy to a deterministic (CREATE2) address and,
    ///         atomically, runs optional initialization calldata.
    /// @dev The resulting address depends only on (this factory, `salt`,
    ///      `implementation`) — NOT on `initializationData`. So the same salt yields
    ///      the same proxy address on every chain where this factory and `implementation`
    ///      share an address, even though each chain can be initialized differently.
    ///      `salt` MUST start with the caller's 20-byte address (or be zero in its first
    ///      20 bytes); see {SaltDoesNotStartWithCaller}. This matches the create2crunch /
    ///      0age ImmutableCreate2Factory salt convention used for offline vanity mining.
    /// @param implementation The logic contract the proxy delegatecalls into.
    /// @param salt 32-byte CREATE2 salt; bytes[0:20] == msg.sender (or zero).
    /// @param initializationData Calldata run against the proxy (e.g. initialize(...)).
    function deployDeterministicProxy(
        address implementation,
        bytes32 salt,
        bytes calldata initializationData
    ) external payable returns (address proxy) {
        if (bytes20(salt) != bytes20(msg.sender) && bytes20(salt) != bytes20(0)) {
            revert SaltDoesNotStartWithCaller();
        }
        proxy = LibClone.deployDeterministicERC1967(msg.value, implementation, salt);
        _initialize(proxy, initializationData);
        emit ProxyDeployed(proxy, implementation);
    }

    /// @notice Predicts the address of a proxy deployed via {deployDeterministicProxy}.
    function predictDeterministicProxy(address implementation, bytes32 salt)
        external
        view
        returns (address proxy)
    {
        proxy = LibClone.predictDeterministicAddressERC1967(implementation, salt, address(this));
    }

    /// @notice The ERC1967 proxy init-code hash for `implementation`. Feed this (with
    ///         this factory's address) to an offline CREATE2 miner (create2crunch
    ///         INIT_CODE_HASH) to search for vanity salts.
    function proxyInitCodeHash(address implementation) external pure returns (bytes32) {
        return LibClone.initCodeHashERC1967(implementation);
    }

    /// @dev Runs optional initialization calldata against a freshly deployed proxy,
    ///      bubbling up any revert reason.
    function _initialize(address proxy, bytes calldata initializationData) private {
        if (initializationData.length > 0) {
            (bool ok, bytes memory returndata) = proxy.call(initializationData);
            if (!ok) {
                if (returndata.length == 0) revert InitializationFailed();
                /// @solidity memory-safe-assembly
                assembly {
                    revert(add(returndata, 0x20), mload(returndata))
                }
            }
        }
    }
}

