// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {AddressAliasHelper} from "nitro-contracts/libraries/AddressAliasHelper.sol";
import {VersionedVaultAdminReceiver} from "./VersionedVaultAdminReceiver.sol";

/// @notice Authenticated vault-administrator receiver for Arbitrum L2 chains.
contract ArbitrumVaultAdminReceiver is VersionedVaultAdminReceiver {
    /// @notice The L1 CredentialManager whose snapshots this receiver applies.
    address public immutable L1_CREDENTIAL_MANAGER;
    /// @notice `L1_CREDENTIAL_MANAGER` aliased onto L2, the sender of its retryable tickets.
    address public immutable ALIASED_L1_CREDENTIAL_MANAGER;

    /// @notice Thrown when the caller is not the aliased L1 CredentialManager.
    /// @param caller The caller.
    /// @param expectedAliasedSender The aliased L1 CredentialManager.
    error InvalidArbitrumSender(address caller, address expectedAliasedSender);

    /// @param l1CredentialManager The L1 CredentialManager proxy.
    constructor(address l1CredentialManager) {
        if (l1CredentialManager == address(0)) revert ZeroAddress();
        L1_CREDENTIAL_MANAGER = l1CredentialManager;
        ALIASED_L1_CREDENTIAL_MANAGER = AddressAliasHelper.applyL1ToL2Alias(l1CredentialManager);
    }

    function _authenticateSource() internal view override {
        if (msg.sender != ALIASED_L1_CREDENTIAL_MANAGER) {
            revert InvalidArbitrumSender(msg.sender, ALIASED_L1_CREDENTIAL_MANAGER);
        }
    }
}

