// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {VersionedVaultAdminReceiver} from "./VersionedVaultAdminReceiver.sol";
import {IL2CrossDomainMessenger} from "../interfaces/IL2CrossDomainMessenger.sol";

/// @notice Authenticated vault-administrator receiver for OP Stack L2 chains, including Base.
contract OPStackVaultAdminReceiver is VersionedVaultAdminReceiver {
    /// @notice The L2 CrossDomainMessenger that relays the L1 CredentialManager's messages.
    address public immutable L2_CROSS_DOMAIN_MESSENGER;
    /// @notice The L1 CredentialManager whose snapshots this receiver applies.
    address public immutable L1_CREDENTIAL_MANAGER;

    /// @notice Thrown when the caller is not the L2 CrossDomainMessenger.
    /// @param caller The caller.
    /// @param expectedMessenger The L2 CrossDomainMessenger.
    error InvalidCrossDomainMessenger(address caller, address expectedMessenger);
    /// @notice Thrown when the relayed message's L1 sender is not the CredentialManager.
    /// @param sender The L1 sender.
    /// @param expectedSender The L1 CredentialManager.
    error InvalidCrossDomainSender(address sender, address expectedSender);

    /// @param l2CrossDomainMessenger The L2 CrossDomainMessenger.
    /// @param l1CredentialManager The L1 CredentialManager proxy.
    constructor(address l2CrossDomainMessenger, address l1CredentialManager) {
        if (l2CrossDomainMessenger == address(0) || l1CredentialManager == address(0)) {
            revert ZeroAddress();
        }
        L2_CROSS_DOMAIN_MESSENGER = l2CrossDomainMessenger;
        L1_CREDENTIAL_MANAGER = l1CredentialManager;
    }

    function _authenticateSource() internal view override {
        if (msg.sender != L2_CROSS_DOMAIN_MESSENGER) {
            revert InvalidCrossDomainMessenger(msg.sender, L2_CROSS_DOMAIN_MESSENGER);
        }

        address source = IL2CrossDomainMessenger(L2_CROSS_DOMAIN_MESSENGER).xDomainMessageSender();
        if (source != L1_CREDENTIAL_MANAGER) {
            revert InvalidCrossDomainSender(source, L1_CREDENTIAL_MANAGER);
        }
    }
}

