// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {IDepositVault} from "../interfaces/IDepositVault.sol";
import {GovernanceSnapshot, hashGovernanceSnapshot} from "../types/GovernanceSnapshot.sol";

/// @notice Common destination behavior for authenticated vault-administrator updates.
/// @dev Chain-specific receivers implement only source authentication. Vaults controlled by a
///      receiver must set their `credentialManager` to the receiver address. The receiver has no
///      owner and no vault allowlist: it forwards to whichever vault the authenticated
///      CredentialManager names, since that vault was committee-approved when it was registered.
abstract contract VersionedVaultAdminReceiver {
    /// @notice The version of the last snapshot applied to each vault, its watermark.
    mapping(address vault => uint256 version) public lastAppliedVersion;
    /// @notice The hash of the last snapshot applied to each vault.
    mapping(address vault => bytes32 stateHash) public lastAppliedStateHash;

    /// @notice Thrown when a constructor address is zero.
    error ZeroAddress();

    /// @notice Emitted when a snapshot is applied to a vault.
    /// @param vault The vault.
    /// @param version The snapshot's version, the vault's new watermark.
    /// @param stateHash The snapshot's hash.
    /// @param memberCount The snapshot's committee member count.
    /// @param withdrawalQuorum The snapshot's withdrawal quorum.
    event GovernanceSnapshotApplied(
        address indexed vault,
        uint256 indexed version,
        bytes32 indexed stateHash,
        uint256 memberCount,
        uint256 withdrawalQuorum
    );
    /// @notice Emitted when a snapshot at or below the vault's watermark is ignored.
    /// @param vault The vault.
    /// @param receivedVersion The ignored snapshot's version.
    /// @param lastAppliedVersion The vault's watermark.
    /// @param stateHash The ignored snapshot's hash.
    event GovernanceSnapshotIgnored(
        address indexed vault,
        uint256 indexed receivedVersion,
        uint256 indexed lastAppliedVersion,
        bytes32 stateHash
    );

    /// @notice Applies a committed snapshot if it is newer than the vault's last applied one.
    /// @dev Equal and older versions, version zero included, are successful no-ops so bridge
    ///      retries cannot roll state back. The content is not validated. A vault revert reverts the whole
    ///      delivery, leaving the watermark where it was.
    /// @param vault Destination vault address.
    /// @param snapshot The committed snapshot.
    function applyGovernanceSnapshot(address vault, GovernanceSnapshot calldata snapshot) external {
        _authenticateSource();

        bytes32 stateHash = hashGovernanceSnapshot(snapshot);

        uint256 appliedVersion = lastAppliedVersion[vault];
        if (snapshot.version <= appliedVersion) {
            emit GovernanceSnapshotIgnored(vault, snapshot.version, appliedVersion, stateHash);
            return;
        }

        // Store before the external call to make the operation reentrancy-safe. A vault revert rolls
        // these writes back together with the complete destination transaction.
        lastAppliedVersion[vault] = snapshot.version;
        lastAppliedStateHash[vault] = stateHash;
        IDepositVault(vault).setGovernanceSnapshot(snapshot);

        emit GovernanceSnapshotApplied(
            vault, snapshot.version, stateHash, snapshot.members.length, snapshot.withdrawalQuorum
        );
    }

    function _authenticateSource() internal view virtual;
}

src/strategies/ArbitrumAdminUpdateStrate.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {IInbox} from "nitro-contracts/bridge/IInbox.sol";
import {IAdminUpdateStrategy} from "../interfaces/IAdminUpdateStrategy.sol";
import {VersionedVaultAdminReceiver} from "../receivers/VersionedVaultAdminReceiver.sol";
import {GovernanceSnapshot, hashGovernanceSnapshot} from "../types/GovernanceSnapshot.sol";

/// @notice Network-configured source strategy for Arbitrum L1-to-L2 admin updates.
/// @dev Designed to be delegatecalled by the CredentialManager so the retryable ticket's aliased
///      L2 sender is the CredentialManager proxy rather than this strategy implementation.
contract ArbitrumAdminUpdateStrategy is IAdminUpdateStrategy {
    /// @notice The L1 Inbox of the Arbitrum chain.
    address public immutable INBOX;
    /// @notice The `ArbitrumVaultAdminReceiver` on the L2.
    address public immutable RECEIVER;
    /// @notice The L2 gas limit of every retryable ticket.
    uint256 public immutable GAS_LIMIT;
    /// @notice The L2 max fee per gas of every retryable ticket.
    uint256 public immutable MAX_FEE_PER_GAS;

    /// @notice Thrown when the inbox or the receiver is zero.
    error ZeroAddress();
    /// @notice Thrown when a gas parameter is zero or Nitro's sentinel one.
    /// @param value The parameter.
    error InvalidGasParameter(uint256 value);
    /// @notice Thrown when the call carries less ETH than the ticket costs.
    /// @param actual The ETH sent.
    /// @param expected The ticket's cost, see `quoteDeliveryPrice`.
    error InsufficientMsgValue(uint256 actual, uint256 expected);

    /// @notice Emitted when a retryable ticket carrying a snapshot is created.
    /// @param receiver The L2 receiver.
    /// @param vault The L2 vault.
    /// @param version The snapshot's version.
    /// @param stateHash The snapshot's hash.
    /// @param retryableTicketId The ticket.
    /// @param submissionCost The ticket's submission cost.
    /// @param gasLimit The ticket's L2 gas limit.
    /// @param maxFeePerGas The ticket's L2 max fee per gas.
    /// @param refundAddress The caller, refunded the excess fee and call value.
    event ArbitrumAdminUpdateQueued(
        address indexed receiver,
        address indexed vault,
        uint256 indexed version,
        bytes32 stateHash,
        uint256 retryableTicketId,
        uint256 submissionCost,
        uint256 gasLimit,
        uint256 maxFeePerGas,
        address refundAddress
    );

    // Retry guidance: redeem `retryableTicketId` through Nitro while the ticket remains alive. If
    // it expires, call CredentialManager.syncVaultGovernanceSnapshot again to create a fresh ticket.

    /// @inheritdoc IAdminUpdateStrategy
    function enforcesSnapshotVersion() external pure returns (bool) {
        return true;
    }

    /// @param inbox The L1 Inbox of the Arbitrum chain.
    /// @param receiver The `ArbitrumVaultAdminReceiver` on the L2.
    /// @param gasLimit The L2 gas limit of every ticket. A ticket it under-gasses can still be
    ///        redeemed by anyone with more gas through `ArbRetryableTx.redeem`.
    /// @param maxFeePerGas The L2 max fee per gas of every ticket.
    constructor(address inbox, address receiver, uint256 gasLimit, uint256 maxFeePerGas) {
        if (inbox == address(0) || receiver == address(0)) revert ZeroAddress();
        // Nitro reserves 1 as a sentinel for surfacing retryable parameters.
        if (gasLimit == 0 || gasLimit == 1) revert InvalidGasParameter(gasLimit);
        if (maxFeePerGas == 0 || maxFeePerGas == 1) {
            revert InvalidGasParameter(maxFeePerGas);
        }

        INBOX = inbox;
        RECEIVER = receiver;
        GAS_LIMIT = gasLimit;
        MAX_FEE_PER_GAS = maxFeePerGas;
    }

    /// @notice The ETH `deliverGovernanceSnapshot` needs for `snapshot` at the current base fee.
    /// @param vault The L2 vault.
    /// @param snapshot The snapshot.
    /// @return requiredValue The ETH to send: submission cost plus L2 gas.
    /// @return submissionCost The ticket's submission cost.
    function quoteDeliveryPrice(address vault, GovernanceSnapshot calldata snapshot)
        external
        view
        returns (uint256 requiredValue, uint256 submissionCost)
    {
        bytes memory callData = _encodeReceiverCall(vault, snapshot);
        submissionCost =
            IInbox(INBOX).calculateRetryableSubmissionFee(callData.length, block.basefee);
        requiredValue = submissionCost + GAS_LIMIT * MAX_FEE_PER_GAS;
    }

    /// @inheritdoc IAdminUpdateStrategy
    /// @dev Creates a retryable ticket to `RECEIVER`; reverts with `InsufficientMsgValue` below
    ///      `quoteDeliveryPrice`. The excess fee and call value refund to the caller.
    function deliverGovernanceSnapshot(address vault, GovernanceSnapshot calldata snapshot)
        external
        payable
        override
        returns (bytes32 deliveryIdentifier)
    {
        bytes32 stateHash = hashGovernanceSnapshot(snapshot);

        bytes memory callData = _encodeReceiverCall(vault, snapshot);
        uint256 submissionCost =
            IInbox(INBOX).calculateRetryableSubmissionFee(callData.length, block.basefee);
        uint256 expectedValue = submissionCost + GAS_LIMIT * MAX_FEE_PER_GAS;
        if (msg.value < expectedValue) {
            revert InsufficientMsgValue(msg.value, expectedValue);
        }

        // Delegatecall preserves the permissionless sync caller as msg.sender here. Direct refunds
        // to that account so excess bridge fees are never trapped in the CredentialManager.
        address refundAddress = msg.sender;
        uint256 ticketId = IInbox(INBOX).createRetryableTicket{value: msg.value}(
            RECEIVER,
            0,
            submissionCost,
            refundAddress,
            refundAddress,
            GAS_LIMIT,
            MAX_FEE_PER_GAS,
            callData
        );

        deliveryIdentifier = bytes32(ticketId);
        emit ArbitrumAdminUpdateQueued(
            RECEIVER,
            vault,
            snapshot.version,
            stateHash,
            ticketId,
            submissionCost,
            GAS_LIMIT,
            MAX_FEE_PER_GAS,
            refundAddress
        );
    }

    function _encodeReceiverCall(address vault, GovernanceSnapshot calldata snapshot)
        internal
        pure
        returns (bytes memory)
    {
        return
            abi.encodeCall(VersionedVaultAdminReceiver.applyGovernanceSnapshot, (vault, snapshot));
    }
}

src/strategies/IntraChainAdminUpdateStra.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {IAdminUpdateStrategy} from "../interfaces/IAdminUpdateStrategy.sol";
import {IDepositVault} from "../interfaces/IDepositVault.sol";
import {GovernanceSnapshot, hashGovernanceSnapshot} from "../types/GovernanceSnapshot.sol";

/// @notice Delivers snapshots to a vault on the same chain as the CredentialManager.
contract IntraChainAdminUpdateStrategy is IAdminUpdateStrategy {
    /// @inheritdoc IAdminUpdateStrategy
    function enforcesSnapshotVersion() external pure returns (bool) {
        return true;
    }

    /// @inheritdoc IAdminUpdateStrategy
    /// @dev Calls the vault directly; the identifier hashes the chain, this strategy, the vault,
    ///      the version and the snapshot's hash.
    function deliverGovernanceSnapshot(address vault, GovernanceSnapshot calldata snapshot)
        external
        payable
        returns (bytes32 deliveryIdentifier)
    {
        IDepositVault(vault).setGovernanceSnapshot(snapshot);
        deliveryIdentifier = keccak256(
            abi.encode(
                block.chainid,
                address(this),
                vault,
                snapshot.version,
                hashGovernanceSnapshot(snapshot)
            )
        );
    }
}

src/strategies/OPStackAdminUpdateStrateg.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {IAdminUpdateStrategy} from "../interfaces/IAdminUpdateStrategy.sol";
import {IL1CrossDomainMessenger} from "../interfaces/IL1CrossDomainMessenger.sol";
import {VersionedVaultAdminReceiver} from "../receivers/VersionedVaultAdminReceiver.sol";
import {GovernanceSnapshot, hashGovernanceSnapshot} from "../types/GovernanceSnapshot.sol";

/// @notice Admin update strategy for OP Stack chains (Optimism, Base, Unichain, etc)
contract OPStackAdminUpdateStrategy is IAdminUpdateStrategy {
    /// @notice L1 CrossDomainMessenger.
    address public immutable L1_CROSS_DOMAIN_MESSENGER;
    /// @notice The `OPStackVaultAdminReceiver` on the L2.
    address public immutable RECEIVER;
    /// @notice The minimum L2 gas limit of every message.
    uint32 public immutable L2_GAS_LIMIT;

    /// @notice Reverts if the messenger or the receiver is zero.
    error ZeroAddress();
    /// @notice Reverts if the L2 gas limit is zero.
    error ZeroGasLimit();
    /// @notice Reverts if a delivery carries ETH; OP Stack messages need none.
    /// @param actual The ETH sent.
    error UnexpectedMsgValue(uint256 actual);

    /// @notice Emitted when a cross-domain message carrying a snapshot is sent.
    /// @param receiver The L2 receiver.
    /// @param vault The L2 vault.
    /// @param version The snapshot's version.
    /// @param stateHash The snapshot's hash.
    /// @param messageNonce The messenger's nonce for the message.
    /// @param minGasLimit The message's minimum L2 gas limit.
    event OPStackAdminUpdateQueued(
        address indexed receiver,
        address indexed vault,
        uint256 indexed version,
        bytes32 stateHash,
        uint256 messageNonce,
        uint32 minGasLimit
    );

    // Retry guidance: relay the message identified by `messageNonce`, or call
    // CredentialManager.syncVaultGovernanceSnapshot again. Destination replay is idempotent.

    /// @inheritdoc IAdminUpdateStrategy
    function enforcesSnapshotVersion() external pure returns (bool) {
        return true;
    }

    /// @param l1CrossDomainMessenger The L1 CrossDomainMessenger of the OP Stack chain.
    /// @param receiver The `OPStackVaultAdminReceiver` on the L2.
    /// @param l2GasLimit The minimum L2 gas limit of every message.
    constructor(address l1CrossDomainMessenger, address receiver, uint32 l2GasLimit) {
        if (l1CrossDomainMessenger == address(0) || receiver == address(0)) revert ZeroAddress();
        if (l2GasLimit == 0) revert ZeroGasLimit();
        L1_CROSS_DOMAIN_MESSENGER = l1CrossDomainMessenger;
        RECEIVER = receiver;
        L2_GAS_LIMIT = l2GasLimit;
    }

    /**
     * @notice Delivers a committed snapshot to an OP Stack L2 vault
     * @dev Sends a cross-domain message from L1 → L2 using the OP Stack messenger
     * @dev The L2 receiver authenticates the messenger and this contract's delegatecall context,
     *      which is the CredentialManager proxy. No ETH is forwarded to the destination call.
     *
     * @param vault The L2 vault address
     * @param snapshot The committed snapshot
     */
    function deliverGovernanceSnapshot(address vault, GovernanceSnapshot calldata snapshot)
        external
        payable
        override
        returns (bytes32 deliveryIdentifier)
    {
        if (msg.value != 0) revert UnexpectedMsgValue(msg.value);
        bytes32 stateHash = hashGovernanceSnapshot(snapshot);

        bytes memory callData =
            abi.encodeCall(VersionedVaultAdminReceiver.applyGovernanceSnapshot, (vault, snapshot));

        IL1CrossDomainMessenger messenger = IL1CrossDomainMessenger(L1_CROSS_DOMAIN_MESSENGER);
        uint256 nonce = messenger.messageNonce();
        messenger.sendMessage(RECEIVER, callData, L2_GAS_LIMIT);

        deliveryIdentifier = bytes32(nonce);
        emit OPStackAdminUpdateQueued(
            RECEIVER, vault, snapshot.version, stateHash, nonce, L2_GAS_LIMIT
        );
    }
}

src/types/GovernanceSnapshot.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/// @notice A committee member and its attested key.
struct CommitteeMember {
    /// @dev The member's operator address.
    address operator;
    /// @dev The member's attested key, or zero while it has none.
    address key;
}

/// @notice The governance state a CredentialManager commits and delivers to its vaults.
/// @dev Carried unchanged from the CredentialManager through `IAdminUpdateStrategy`, the bridge
///      and the receiver to the vault. Its hash is `keccak256(abi.encode(snapshot))`, see
///      `hashGovernanceSnapshot`. The version and the three thresholds share one storage slot.
struct GovernanceSnapshot {
    /// @dev Increases by one on every commit; zero only for a vault's bootstrap snapshot.
    uint64 version;
    /// @dev Committee signatures a committee action needs.
    uint16 committeeThreshold;
    /// @dev Council signatures a council action needs.
    uint16 councilThreshold;
    /// @dev Approvals from distinct members' keys a withdrawal needs.
    uint16 withdrawalQuorum;
    /// @dev Every committee member with its key, in the manager's operator-array order.
    CommitteeMember[] members;
    /// @dev The security-council members.
    address[] council;
}

/// @notice The hash a snapshot is committed and delivered under.
function hashGovernanceSnapshot(GovernanceSnapshot memory snapshot) pure returns (bytes32) {
    return keccak256(abi.encode(snapshot));
}

/// @notice Thrown when a snapshot's version is zero.
error ZeroSnapshotVersion();

/// @notice Thrown when a snapshot's committee threshold is zero or above its member count.
/// @param threshold The committee threshold.
/// @param memberCount The member count.
error InvalidSnapshotCommitteeThreshold(uint256 threshold, uint256 memberCount);

/// @notice Thrown when a snapshot's council threshold is zero or above its council size.
/// @param threshold The council threshold.
/// @param councilCount The council size.
error InvalidSnapshotCouncilThreshold(uint256 threshold, uint256 councilCount);

/// @notice Thrown when a snapshot's withdrawal quorum is zero or above its non-zero key count.
/// @param quorum The withdrawal quorum.
/// @param keyCount The members' non-zero keys.
error InvalidSnapshotWithdrawalQuorum(uint256 quorum, uint256 keyCount);

/// @notice Thrown when a snapshot has a zero operator or council member.
error ZeroSnapshotMember();

/// @notice Thrown when a snapshot repeats an operator, a non-zero key or a council member.
/// @param account The repeated address.
error DuplicateSnapshotMember(address account);

/// @notice Reverts unless `snapshot` holds the invariants a CredentialManager holds before it
///         commits one: a non-zero version, thresholds in `[1, size]`, a withdrawal quorum in
///         `[1, non-zero keys]`, no zero operator or council member, and no repeated operator,
///         non-zero key or council member. A member's key may be zero while it has none.
/// @dev For snapshots that do not come from a CredentialManager, such as a vault's genesis.
function requireValidGovernanceSnapshot(GovernanceSnapshot memory snapshot) pure {
    if (snapshot.version == 0) revert ZeroSnapshotVersion();

    CommitteeMember[] memory members = snapshot.members;
    uint256 memberCount = members.length;
    uint256 keyCount;
    for (uint256 i; i < memberCount; ++i) {
        address operator = members[i].operator;
        address key = members[i].key;
        if (operator == address(0)) revert ZeroSnapshotMember();
        if (key != address(0)) ++keyCount;
        for (uint256 j; j < i; ++j) {
            if (members[j].operator == operator) revert DuplicateSnapshotMember(operator);
            if (key != address(0) && members[j].key == key) revert DuplicateSnapshotMember(key);
        }
    }
    if (snapshot.committeeThreshold == 0 || snapshot.committeeThreshold > memberCount) {
        revert InvalidSnapshotCommitteeThreshold(snapshot.committeeThreshold, memberCount);
    }
    if (snapshot.withdrawalQuorum == 0 || snapshot.withdrawalQuorum > keyCount) {
        revert InvalidSnapshotWithdrawalQuorum(snapshot.withdrawalQuorum, keyCount);
    }

    address[] memory council = snapshot.council;
    uint256 councilCount = council.length;
    for (uint256 i; i < councilCount; ++i) {
        address member = council[i];
        if (member == address(0)) revert ZeroSnapshotMember();
        for (uint256 j; j < i; ++j) {
            if (council[j] == member) revert DuplicateSnapshotMember(member);
        }
    }
    if (snapshot.councilThreshold == 0 || snapshot.councilThreshold > councilCount) {
        revert InvalidSnapshotCouncilThreshold(snapshot.councilThreshold, councilCount);
    }
}

