/// @notice Bounds for paged [start, end) getters.
library Paging {
    /// @notice The length of a paged [start, end) range clamped to `count` entries.
    /// @param start The start index (inclusive).
    /// @param end The end index (not inclusive).
    /// @param count The number of entries.
    /// @return The page length.
    function clampPage(uint16 start, uint16 end, uint256 count) internal pure returns (uint16) {
        if (start >= count) {
            return 0;
        }
        if (end > count) {
            // safe: count < end <= type(uint16).max here
            // forge-lint: disable-next-line(unsafe-typecast)
            end = uint16(count);
        }
        if (end < start) {
            return 0;
        }
        return end - start;
    }
}

