// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/// @notice Checks on piecewise series scaled so that 1_000_000 is one.
library SeriesValidation {
    /// @notice One, in the series' scale.
    uint256 internal constant ONE = 1_000_000;

    /// @notice Whether a series starts at zero, never decreases and stays at or below one.
    /// @param series The series checked.
    /// @return Whether the series is valid.
    function validateStartAtZeroIsAlwaysBelowOneAndIncreases(uint256[] memory series)
        internal
        pure
        returns (bool)
    {
        uint256 length = series.length;
        return
            length != 0 && series[0] == 0 && validateIncreases(series) && series[length - 1] <= ONE;
    }

    /// @notice Whether a series never decreases and stays at or below one.
    /// @param series The series checked.
    /// @return Whether the series is valid.
    function validateIncreasesAndBelowOne(uint256[] memory series) internal pure returns (bool) {
        uint256 length = series.length;
        return validateIncreases(series) && (length == 0 || series[length - 1] <= ONE);
    }

    /// @notice Whether a series is non-empty and ends at one.
    /// @param series The series checked.
    /// @return Whether the series is valid.
    function validateLastIsOne(uint256[] memory series) internal pure returns (bool) {
        uint256 length = series.length;
        return length != 0 && series[length - 1] == ONE;
    }

    /// @notice Whether a series never decreases.
    /// @param series The series checked.
    /// @return Whether the series is valid.
    function validateIncreases(uint256[] memory series) internal pure returns (bool) {
        for (uint256 position = 1; position < series.length; ++position) {
            if (series[position] < series[position - 1]) return false;
        }
        return true;
    }
}

