// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Initializable} from "solady/utils/Initializable.sol";
import {UUPSUpgradeable} from "solady/utils/UUPSUpgradeable.sol";
import {UpgradeQueueStorage} from "./UpgradeQueueStorage.sol";

/// @notice Shared UUPS upgradeability base for t+ contracts.
/// @dev The per-proxy delay is set at initialization; changes wait the current delay.
///      New delay state uses an ERC-7201 namespace. The original upgrade queue remains
///      at slot 0, preserving inherited storage layouts and previously scheduled upgrades.
abstract contract TPlusUUPSUpgradeable is Initializable, UUPSUpgradeable, UpgradeQueueStorage {
    /// @notice Reverts when the caller is not authorized to perform upgrades.
    error NotUpgradeAuthority();

    /// @notice Reverts when a zero implementation is supplied for scheduling.
    error ZeroImplementation();

    /// @notice Reverts when attempting an upgrade that has not been scheduled.
    error UpgradeNotScheduled(address implementation);

    /// @notice Reverts when an upgrade is scheduled but the timelock has not expired.
    error UpgradeNotReady(address implementation, uint256 validAfter);

    /// @notice Reverts when a requested upgrade delay is outside the allowed bounds.
    error UpgradeDelayOutOfBounds(uint64 requested, uint64 minimum, uint64 maximum);

    /// @notice Reverts when executing a delay change that was never scheduled.
    error UpgradeDelayChangeNotScheduled();

    /// @notice Reverts when a scheduled delay change is executed before its timelock expires.
    error UpgradeDelayChangeNotReady(uint256 validAfter);

    /// @notice Emitted when an upgrade is scheduled.
    event UpgradeScheduled(
        address indexed implementation, uint256 validAfter, address indexed authority
    );

    /// @notice Emitted when an upgrade schedule is canceled.
    event UpgradeCancelled(address indexed implementation, address indexed authority);

    /// @notice Emitted when a change of the upgrade delay is scheduled.
    event UpgradeDelayChangeScheduled(
        uint64 currentDelay, uint64 newDelay, uint256 validAfter, address indexed authority
    );

    /// @notice Emitted when a scheduled delay change is canceled.
    event UpgradeDelayChangeCancelled(uint64 newDelay, address indexed authority);

    /// @notice Emitted when the upgrade delay changes (at initialization or after execution).
    event UpgradeDelayChanged(uint64 previousDelay, uint64 newDelay);

    /// @notice Lower bound on the upgrade delay. Compound uses 2 days; 0 here so that staging
    ///         deployments can iterate without waiting. Raise for a stricter production floor.
    uint64 public constant MINIMUM_UPGRADE_DELAY_SECONDS = 0;

    /// @notice Upper bound on the upgrade delay, so a mistyped value cannot brick upgrades.
    uint64 public constant MAXIMUM_UPGRADE_DELAY_SECONDS = 30 days;

    /// @custom:storage-location erc7201:tplus.storage.TPlusUUPSUpgradeable
    struct UpgradeStorage {
        /// @dev Current timelock applied to scheduled upgrades.
        uint64 upgradeDelaySeconds;
        /// @dev Delay that takes effect once `pendingDelayValidAfter` passes.
        uint64 pendingDelaySeconds;
        /// @dev Earliest timestamp at which the pending delay can be applied; 0 = none pending.
        uint256 pendingDelayValidAfter;
    }

    // keccak256(abi.encode(uint256(keccak256("tplus.storage.TPlusUUPSUpgradeable")) - 1)) & ~bytes32(uint256(0xff))
    bytes32 private constant _UPGRADE_STORAGE_SLOT =
        0xfeb3e9c58378c2fa7eb4efa32af0a856e17a657aac8e217d1888e5ed98471b00;

    /// @dev Lock the implementation contract. Proxies can still initialize.
    constructor() {
        _disableInitializers();
    }

    function _upgradeStorage() private pure returns (UpgradeStorage storage $) {
        bytes32 slot = _UPGRADE_STORAGE_SLOT;
        /// @solidity memory-safe-assembly
        assembly {
            $.slot := slot
        }
    }

    function _checkDelayBounds(uint64 delaySeconds) private pure {
        if (
            delaySeconds < MINIMUM_UPGRADE_DELAY_SECONDS
                || delaySeconds > MAXIMUM_UPGRADE_DELAY_SECONDS
        ) {
            revert UpgradeDelayOutOfBounds(
                delaySeconds, MINIMUM_UPGRADE_DELAY_SECONDS, MAXIMUM_UPGRADE_DELAY_SECONDS
            );
        }
    }

    /// @dev Sets the initial upgrade delay. Inheriting contracts call this from their initializer.
    function _initializeUpgradeDelay(uint64 delaySeconds) internal {
        _checkDelayBounds(delaySeconds);
        UpgradeStorage storage $ = _upgradeStorage();
        uint64 previous = upgradeDelaySeconds();
        $.upgradeDelaySeconds = delaySeconds;
        emit UpgradeDelayChanged(previous, delaySeconds);
    }

    /// @notice Returns the required delay for executing scheduled upgrades.
    function upgradeDelaySeconds() public view returns (uint64) {
        return _upgradeStorage().upgradeDelaySeconds;
    }

    /// @notice Returns the scheduled delay change, if any: the new delay and when it can apply.
    function pendingUpgradeDelayChange()
        public
        view
        returns (uint64 newDelaySeconds, uint256 validAfter)
    {
        UpgradeStorage storage $ = _upgradeStorage();
        return ($.pendingDelaySeconds, $.pendingDelayValidAfter);
    }

    /// @notice Schedules an implementation for upgrade after the contract timelock.
    function scheduleUpgrade(address newImplementation) external {
        if (!_isUpgradeAuthority(msg.sender)) revert NotUpgradeAuthority();
        if (newImplementation == address(0)) revert ZeroImplementation();
        uint256 validAfter = block.timestamp + upgradeDelaySeconds();
        pendingUpgradeValidAfter[newImplementation] = validAfter;
        emit UpgradeScheduled(newImplementation, validAfter, msg.sender);
    }

    /// @notice Cancels a previously scheduled implementation upgrade.
    function cancelUpgrade(address newImplementation) external {
        if (!_isUpgradeAuthority(msg.sender)) revert NotUpgradeAuthority();
        delete pendingUpgradeValidAfter[newImplementation];
        emit UpgradeCancelled(newImplementation, msg.sender);
    }

    /// @notice Schedules a change of the upgrade delay. The change can only be executed once the
    ///         CURRENT delay has elapsed, so shortening the timelock is as slow as an upgrade.
    /// @dev Scheduling again overwrites any pending change and restarts its timelock.
    function scheduleUpgradeDelayChange(uint64 newDelaySeconds) external {
        if (!_isUpgradeAuthority(msg.sender)) revert NotUpgradeAuthority();
        _checkDelayBounds(newDelaySeconds);
        UpgradeStorage storage $ = _upgradeStorage();
        uint256 validAfter = block.timestamp + upgradeDelaySeconds();
        $.pendingDelaySeconds = newDelaySeconds;
        $.pendingDelayValidAfter = validAfter;
        emit UpgradeDelayChangeScheduled(
            upgradeDelaySeconds(), newDelaySeconds, validAfter, msg.sender
        );
    }

    /// @notice Applies a scheduled delay change once its timelock has elapsed.
    function executeUpgradeDelayChange() external {
        if (!_isUpgradeAuthority(msg.sender)) revert NotUpgradeAuthority();
        UpgradeStorage storage $ = _upgradeStorage();
        uint256 validAfter = $.pendingDelayValidAfter;
        if (validAfter == 0) revert UpgradeDelayChangeNotScheduled();
        if (block.timestamp < validAfter) revert UpgradeDelayChangeNotReady(validAfter);
        uint64 previous = upgradeDelaySeconds();
        uint64 next = $.pendingDelaySeconds;
        $.upgradeDelaySeconds = next;
        delete $.pendingDelaySeconds;
        delete $.pendingDelayValidAfter;
        emit UpgradeDelayChanged(previous, next);
    }

    /// @notice Cancels a scheduled delay change.
    function cancelUpgradeDelayChange() external {
        if (!_isUpgradeAuthority(msg.sender)) revert NotUpgradeAuthority();
        UpgradeStorage storage $ = _upgradeStorage();
        uint64 pending = $.pendingDelaySeconds;
        delete $.pendingDelaySeconds;
        delete $.pendingDelayValidAfter;
        emit UpgradeDelayChangeCancelled(pending, msg.sender);
    }

    /// @dev UUPS hook called on upgrade.
    function _authorizeUpgrade(address newImplementation) internal virtual override {
        if (!_isUpgradeAuthority(msg.sender)) revert NotUpgradeAuthority();
        uint256 validAfter = pendingUpgradeValidAfter[newImplementation];
        if (validAfter == 0) revert UpgradeNotScheduled(newImplementation);
        if (block.timestamp < validAfter) revert UpgradeNotReady(newImplementation, validAfter);
        delete pendingUpgradeValidAfter[newImplementation];
    }

    /// @dev Implemented per-contract to define who can authorize upgrades.
    function _isUpgradeAuthority(address caller) internal view virtual returns (bool);
}

