// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/// @title UpgradeQueueStorage
/// @notice The upgrade queue at slot 0 of every `TPlusUUPSUpgradeable` host, a base of its own so
///         a facet sharing the host's layout starts at the same slot.
abstract contract UpgradeQueueStorage {
    /// @notice Earliest timestamp each scheduled implementation can be installed; 0 = not scheduled.
    mapping(address => uint256) public pendingUpgradeValidAfter;
}
